export const definitions: Record<string, string> = {
  'plaint':
    'ಸಿವಿಲ್ ಪ್ರಕರಣ ಆರಂಭಿಸಲು ಒಬ್ಬ ವ್ಯಕ್ತಿ ಸಲ್ಲಿಸುವ ಲಿಖಿತ ದಾಖಲೆ. ಇದು ಪಕ್ಷಗಳು ಯಾರು, ಏನು ಸಂಭವಿಸಿತು, ಮತ್ತು ನ್ಯಾಯಾಲಯ ಏನು ಆದೇಶಿಸಬೇಕು ಎಂದು ವ್ಯಕ್ತಿ ಬಯಸುತ್ತಾರೆ ಎಂಬುದನ್ನು ವಿವರಿಸುತ್ತದೆ.',
  'written-statement':
    'ಸಿವಿಲ್ ಪ್ರಕರಣದಲ್ಲಿ ಪ್ರತಿವಾದಿ ಸಲ್ಲಿಸುವ ಔಪಚಾರಿಕ ಲಿಖಿತ ಉತ್ತರ, ಪ್ಲೇಯಿಂಟ್‌ನಲ್ಲಿ ಮಾಡಿದ ಹಕ್ಕುಗಳಿಗೆ ಉತ್ತರಿಸುತ್ತದೆ. ಇದು ಯಾವ ಆರೋಪಗಳನ್ನು ಒಪ್ಪಿಕೊಳ್ಳಲಾಗಿದೆ, ಯಾವುದನ್ನು ನಿರಾಕರಿಸಲಾಗಿದೆ ಎಂಬುದನ್ನು ಹೇಳುತ್ತದೆ ಮತ್ತು ಪ್ರತಿವಾದಿಯ ಸ್ವಂತ ಪ್ರತಿವಾದಗಳನ್ನು ಎತ್ತಬಹುದು.',
  'affidavit':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿ ನೋಟರಿ, ಪ್ರಮಾಣ ಆಯುಕ್ತ, ಅಥವಾ ಇತರ ಅಧಿಕೃತ ಅಧಿಕಾರಿಯ ಮುಂದೆ ಸಹಿ ಮಾಡಿ ಸತ್ಯವೆಂದು ಪ್ರಮಾಣ ಮಾಡುವ ಲಿಖಿತ ಸತ್ಯ ಹೇಳಿಕೆ. ಅನೇಕ ಕಾರ್ಯವಿಧಾನ ಉದ್ದೇಶಗಳಿಗೆ, ವ್ಯಕ್ತಿ ಸ್ವತಃ ಹಾಜರಾಗಿ ಆ ಸಂಗತಿಗಳನ್ನು ಪುನರಾವರ್ತಿಸುವುದಕ್ಕೆ ಪರ್ಯಾಯವಾಗಿ ನ್ಯಾಯಾಲಯಗಳು ಇದನ್ನು ಸ್ವೀಕರಿಸುತ್ತವೆ.',
  'decree':
    'ಸಿವಿಲ್ ದಾವೆಯಲ್ಲಿ ನ್ಯಾಯಾಲಯದ ನಿರ್ಧಾರದ ಔಪಚಾರಿಕ, ಅಂತಿಮ ಅಭಿವ್ಯಕ್ತಿ, ಇದು ವಿವಾದದಲ್ಲಿರುವ ವಿಷಯಗಳ ಬಗ್ಗೆ ಪಕ್ಷಗಳ ಹಕ್ಕುಗಳನ್ನು ನಿರ್ಣಾಯಕವಾಗಿ ತೀರ್ಮಾನಿಸುತ್ತದೆ. ಇದು "ಆದೇಶ"ಕ್ಕಿಂತ ಭಿನ್ನವಾಗಿದೆ, ಇದು ಸಾಮಾನ್ಯವಾಗಿ ಪ್ರಕರಣವನ್ನು ಅಂತಿಮವಾಗಿ ನಿರ್ಧರಿಸುವ ಬದಲು ಕಾರ್ಯವಿಧಾನ ಅಥವಾ ಮಧ್ಯಂತರ ವಿಷಯಗಳನ್ನು ನಿಭಾಯಿಸುತ್ತದೆ.',
  'judicial-order':
    'ಪ್ರಕರಣದ ಸಂದರ್ಭದಲ್ಲಿ ನ್ಯಾಯಾಲಯ ನೀಡುವ ಔಪಚಾರಿಕ ನಿರ್ದೇಶನ, ಕಾರ್ಯವಿಧಾನ ಅಥವಾ ಮಧ್ಯಂತರ ವಿಷಯಗಳ ಮೇಲೆ, ಉದಾಹರಣೆಗೆ ಮುಂದೂಡಿಕೆ ನೀಡುವುದು ಅಥವಾ ದಾಖಲೆಯನ್ನು ಸ್ವೀಕರಿಸುವುದು. ಡಿಕ್ರಿಗಿಂತ ಭಿನ್ನವಾಗಿ, ಆದೇಶ ಪ್ರಕರಣವನ್ನು, ಅಥವಾ ಅದರಲ್ಲಿರುವ ಒಂದು ಮೂಲಭೂತ ಹಕ್ಕನ್ನು, ಅಗತ್ಯವಾಗಿ ಅಂತಿಮ ತೀರ್ಮಾನಕ್ಕೆ ತರುವುದಿಲ್ಲ.',
  'ex-parte':
    'ಕೇವಲ ಒಂದು ಪಕ್ಷ ಹಾಜರಿದ್ದಾಗ ನಡೆಸಿದ ವಿಚಾರಣೆ ಅಥವಾ ನೀಡಿದ ಆದೇಶ, ಸಾಮಾನ್ಯವಾಗಿ ಇತರ ಪಕ್ಷಕ್ಕೆ ನೋಟಿಸ್ ನೀಡಿದ್ದರೂ ಹಾಜರಾಗದ ಕಾರಣ. ಗೈರುಹಾಜರಾದ ಪಕ್ಷ ವಿಚಾರಣೆಗೆ ಹಾಜರಾಗದಿರಲು ಸಮಂಜಸ ಕಾರಣ ತೋರಿಸಿದರೆ ಎಕ್ಸ್ ಪಾರ್ಟೆ ಆದೇಶವನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಪ್ರಶ್ನಿಸಬಹುದು ಅಥವಾ ರದ್ದುಗೊಳಿಸಬಹುದು.',
  'limitation-period':
    'ಒಂದು ವ್ಯಕ್ತಿ ಪ್ರಕರಣ ದಾಖಲಿಸಬೇಕಾದ ಅಥವಾ ಒಂದು ನಿರ್ದಿಷ್ಟ ಕಾನೂನು ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕಾದ ಕಾಲಮಿತಿ, ಮೊಕದ್ದಮೆ ಹೂಡುವ ಅಥವಾ ಕ್ರಮ ಕೈಗೊಳ್ಳುವ ಹಕ್ಕು ಮೊದಲು ಉದ್ಭವಿಸಿದಾಗಿನಿಂದ ಎಣಿಕೆ ಮಾಡಲಾಗುತ್ತದೆ. ವಿಳಂಬಕ್ಕೆ ಸಮರ್ಥ ಕಾರಣವಿಲ್ಲದೆ ಈ ಅವಧಿಯ ನಂತರ ಪ್ರಕರಣ ದಾಖಲಿಸಿದರೆ, ಅದರ ಮೌಲ್ಯ ಏನೇ ಇರಲಿ, ನ್ಯಾಯಾಲಯಗಳು ಅದನ್ನು ಆಲಿಸಲು ಸಂಪೂರ್ಣವಾಗಿ ನಿರಾಕರಿಸಬಹುದು.',
  'cause-of-action':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿಗೆ ಇನ್ನೊಬ್ಬರ ಮೇಲೆ ಮೊಕದ್ದಮೆ ಹೂಡುವ ಕಾನೂನು ಹಕ್ಕು ನೀಡುವ ಸಂಗತಿಗಳ ಗುಂಪು. ನಿಜವಾದ ವಾದಹೇತು ಅಸ್ತಿತ್ವದಲ್ಲಿದ್ದು ಸ್ಪಷ್ಟವಾಗಿ ಹೇಳಿದ ಹೊರತು ಪ್ರಕರಣವನ್ನು ದಾಖಲಿಸಲಾಗುವುದಿಲ್ಲ, ಮತ್ತು ನ್ಯಾಯಾಲಯ ಅದನ್ನು ಪರಿಗಣಿಸುವುದಿಲ್ಲ.',
  'jurisdiction':
    'ವಿಷಯ, ಹಕ್ಕಿನ ಮೌಲ್ಯ, ಮತ್ತು ಪಕ್ಷಗಳು ಅಥವಾ ಸಂಬಂಧಿತ ಆಸ್ತಿಯ ಸ್ಥಳದಂತಹ ಅಂಶಗಳ ಆಧಾರದ ಮೇಲೆ, ಒಂದು ಪ್ರಕರಣವನ್ನು ಆಲಿಸಿ ನಿರ್ಧರಿಸುವ ನಿರ್ದಿಷ್ಟ ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯ ಅಧಿಕಾರ. ಅಧಿಕಾರವ್ಯಾಪ್ತಿ ಇಲ್ಲದ ತಪ್ಪು ವೇದಿಕೆಯಲ್ಲಿ ಪ್ರಕರಣ ದಾಖಲಿಸುವುದರಿಂದ, ಅದರ ಮೌಲ್ಯ ಏನೇ ಇರಲಿ, ಅದನ್ನು ವಜಾಗೊಳಿಸಬಹುದು ಅಥವಾ ವರ್ಗಾಯಿಸಬಹುದು.',
  'locus-standi':
    'ಒಂದು ವಿಷಯದಿಂದ ನೇರವಾಗಿ ಬಾಧಿತರಾಗಿರುವ ಕಾರಣ, ಒಂದು ನಿರ್ದಿಷ್ಟ ಪ್ರಕರಣವನ್ನು ತರುವ ಅಥವಾ ಅದರಲ್ಲಿ ಆಲಿಸಲ್ಪಡುವ ವ್ಯಕ್ತಿಯ ಕಾನೂನು ಹಕ್ಕು. ಆಧಾರವಾಗಿರುವ ದೂರಿನಲ್ಲಿ ಹುರುಳಿದ್ದರೂ, ಲೋಕಸ್ ಸ್ಟ್ಯಾಂಡಿ ಇಲ್ಲದ ವ್ಯಕ್ತಿಯನ್ನು ಆಲಿಸಲು ನ್ಯಾಯಾಲಯ ನಿರಾಕರಿಸಬಹುದು.',
  'adjournment':
    'ನ್ಯಾಯಾಲಯದ ವಿಚಾರಣೆಯನ್ನು ಮುಂದಿನ ದಿನಾಂಕಕ್ಕೆ ಮುಂದೂಡುವುದು, ಸಾಮಾನ್ಯವಾಗಿ ಒಂದು ಪಕ್ಷದ ಮನವಿಯ ಮೇಲೆ ಸಮಂಜಸ ಕಾರಣಕ್ಕಾಗಿ ನೀಡಲಾಗುತ್ತದೆ, ಉದಾಹರಣೆಗೆ ತಯಾರಿಗೆ ಹೆಚ್ಚಿನ ಸಮಯ ಬೇಕಾಗಿರುವುದು ಅಥವಾ ವಕೀಲರ ಅಲಭ್ಯತೆ.',
  'stay-order':
    'ಒಂದು ನಿರ್ದಿಷ್ಟ ಕ್ರಮ, ಪ್ರಕ್ರಿಯೆ, ಅಥವಾ ಕೆಳಹಂತದ ಆದೇಶದ ಕಾರ್ಯಾಚರಣೆಯನ್ನು, ಮುಂದಿನ ನಿರ್ದೇಶನಗಳು ನೀಡುವವರೆಗೆ ನಿಲ್ಲಿಸುವ ಅಥವಾ ಸ್ಥಗಿತಗೊಳಿಸುವ ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯ ಆದೇಶ. ಉದಾಹರಣೆಗೆ, ಮೇಲ್ಮನವಿ ಬಾಕಿಯಿರುವಾಗ ನ್ಯಾಯಾಲಯ ಡಿಕ್ರಿಯ ಜಾರಿಯನ್ನು ತಡೆಹಿಡಿಯಬಹುದು.',
  'condonation-of-delay':
    'ಸಾಮಾನ್ಯ ಕಾಲಮಿತಿ ಮುಗಿದ ನಂತರ ಪ್ರಕರಣ ಅಥವಾ ಮೇಲ್ಮನವಿ ದಾಖಲಿಸಿದ ಪಕ್ಷವನ್ನು ಕ್ಷಮಿಸುವ ನ್ಯಾಯಾಲಯದ ಆದೇಶ, ಪಕ್ಷ ವಿಳಂಬಕ್ಕೆ ಸಮರ್ಪಕ ಮತ್ತು ನಿಜವಾದ ಕಾರಣ ತೋರಿಸಿದಾಗ ನೀಡಲಾಗುತ್ತದೆ. ಇದಿಲ್ಲದೆ, ತಡವಾದ ಫೈಲಿಂಗ್ ಅನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ನೇರವಾಗಿ ತಿರಸ್ಕರಿಸಲಾಗುತ್ತದೆ.',
  'interlocutory-application':
    'ಮುಖ್ಯ ಪ್ರಕರಣ ಇನ್ನೂ ಬಾಕಿಯಿರುವಾಗ, ಪ್ರಕರಣದ ಬಗ್ಗೆ ಅಂತಿಮ ನಿರ್ಧಾರಕ್ಕಿಂತ, ಮಧ್ಯಂತರ ಆದೇಶ ಅಥವಾ ನಿರ್ದೇಶನಕ್ಕಾಗಿ ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಗೆ ಮಾಡುವ ಮನವಿ. ಸಾಮಾನ್ಯ ಉದಾಹರಣೆಗಳಲ್ಲಿ ಮಧ್ಯಂತರ ತಡೆಯಾಜ್ಞೆಗೆ, ವಿಳಂಬ ಮನ್ನಾ ಮಾಡಲು, ಅಥವಾ ಪ್ಲೀಡಿಂಗ್ ತಿದ್ದುಪಡಿ ಮಾಡಲು ಅನುಮತಿಗೆ ಅರ್ಜಿಗಳು ಸೇರಿವೆ.',
  'show-cause-notice':
    'ಒಂದು ನಿರ್ದಿಷ್ಟ ಸಮಯದೊಳಗೆ, ಒಂದು ನಿರ್ದಿಷ್ಟ ಕ್ರಮವನ್ನು ಅವರ ವಿರುದ್ಧ ಏಕೆ ಕೈಗೊಳ್ಳಬಾರದು ಎಂದು ವಿವರಿಸಲು ಒಂದು ವ್ಯಕ್ತಿ ಅಥವಾ ಸಂಸ್ಥೆಯನ್ನು ಕೇಳುವ ಔಪಚಾರಿಕ ನೋಟಿಸ್. ಯಾವುದೇ ಪ್ರತಿಕೂಲ ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳುವ ಮೊದಲು ಇದು ಸ್ವೀಕೃತದಾರರಿಗೆ ಪ್ರತಿಕ್ರಿಯಿಸಲು ಅವಕಾಶ ನೀಡುತ್ತದೆ.',
  'interim-order':
    'ಪ್ರಕರಣ ಇನ್ನೂ ನಡೆಯುತ್ತಿರುವಾಗ ನ್ಯಾಯಾಲಯ ನೀಡುವ ತಾತ್ಕಾಲಿಕ ಆದೇಶ, ಪ್ರಕರಣ ಅಂತಿಮವಾಗಿ ನಿರ್ಧರಿಸುವವರೆಗೆ ಪರಿಸ್ಥಿತಿಯನ್ನು ಸಂರಕ್ಷಿಸಲು ಅಥವಾ ಪಕ್ಷದ ಹಿತಾಸಕ್ತಿಗಳನ್ನು ರಕ್ಷಿಸಲು ಉದ್ದೇಶಿಸಲಾಗಿದೆ. ಇದು ವಿವಾದದ ಹುರುಳಿನ ಬಗ್ಗೆ ತೀರ್ಪು ಅಲ್ಲ.',
  'summary-suit':
    'ಕೆಲವು ಪ್ರಕಾರದ ಹಕ್ಕುಗಳಿಗೆ, ಸಾಮಾನ್ಯವಾಗಿ ಪಾವತಿಯಾಗದ ಬಿಲ್ ಅಥವಾ ಲಿಖಿತ ಒಪ್ಪಂದದ ಮೇಲಿನ ಸಾಲದಂತಹ ಸ್ಪಷ್ಟ, ನಿಗದಿತ ಮೊತ್ತದ ವಸೂಲಿಗಾಗಿ ಬಳಸುವ ಫಾಸ್ಟ್-ಟ್ರ್ಯಾಕ್ ಸಿವಿಲ್ ಕಾರ್ಯವಿಧಾನ. ಇದು ಪ್ರತಿವಾದಿಯ ಪ್ರಕರಣವನ್ನು ವಿವಾದಿಸುವ ಸ್ವಯಂಚಾಲಿತ ಹಕ್ಕನ್ನು ನಿರ್ಬಂಧಿಸುತ್ತದೆ ಮತ್ತು ಪ್ರತಿವಾದ ನಿಜವಾಗುವ ಸಾಧ್ಯತೆ ಕಡಿಮೆಯಿರುವ ಪ್ರಕರಣಗಳನ್ನು ವೇಗಗೊಳಿಸುತ್ತದೆ.',
  'caveat':
    'ಇತರ ಪಕ್ಷದಿಂದ ನಿರೀಕ್ಷಿತ ಅರ್ಜಿಯ ಮೇಲೆ, ಉದಾಹರಣೆಗೆ ಎಕ್ಸ್ ಪಾರ್ಟೆ ತಡೆಯಾಜ್ಞೆಯಂತಹ, ಯಾವುದೇ ಆದೇಶ ನೀಡುವ ಮೊದಲು ತಿಳಿಸಬೇಕು ಮತ್ತು ಆಲಿಸಬೇಕು ಎಂದು ಕೋರಿ ನ್ಯಾಯಾಲಯದಲ್ಲಿ ದಾಖಲಿಸುವ ಔಪಚಾರಿಕ ನೋಟಿಸ್. ಕೇವಿಯಟ್ ದಾಖಲಿಸಿದ ನಂತರ, ನ್ಯಾಯಾಲಯ ಅದನ್ನು ದಾಖಲಿಸಿದ ವ್ಯಕ್ತಿಗೆ ಮೊದಲು ಆಲಿಸುವ ಅವಕಾಶ ನೀಡಬೇಕು.',
  'plaintiff':
    'ಪ್ರತಿವಾದಿಯ ವಿರುದ್ಧ ಕೆಲವು ಪರಿಹಾರ ನೀಡಬೇಕೆಂದು ನ್ಯಾಯಾಲಯವನ್ನು ಕೋರಿ ಸಿವಿಲ್ ದಾವೆ ದಾಖಲಿಸುವ ವ್ಯಕ್ತಿ.',
  'defendant':
    'ಸಿವಿಲ್ ದಾವೆ ದಾಖಲಿಸಲ್ಪಟ್ಟ ವ್ಯಕ್ತಿ, ಲಿಖಿತ ಹೇಳಿಕೆ ಸಲ್ಲಿಸುವ ಮೂಲಕ ವಾದಿಯ ಹಕ್ಕುಗಳಿಗೆ ಉತ್ತರಿಸಲು ಕರೆಯಲಾಗುತ್ತದೆ.',
  'petitioner':
    'ಅರ್ಜಿ ದಾಖಲಿಸುವ ವ್ಯಕ್ತಿ, ರಿಟ್ ಅರ್ಜಿ, ವೈವಾಹಿಕ ಪ್ರಕರಣಗಳು, ಅಥವಾ ಕಂಪನಿ ಕಾನೂನು ಪ್ರಕ್ರಿಯೆಗಳಂತಹ ವಿಷಯಗಳಲ್ಲಿ "ವಾದಿ" ಬದಲಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ.',
  'respondent':
    'ಅರ್ಜಿ, ಮೇಲ್ಮನವಿ, ಅಥವಾ ಮರುಪರಿಶೀಲನೆ ಮಾಡಲಾದ ವ್ಯಕ್ತಿ, ಅದಕ್ಕೆ ಉತ್ತರಿಸಲು ಕರೆಯಲಾಗುತ್ತದೆ, ದಾವೆಯಲ್ಲಿ ಪ್ರತಿವಾದಿ ವಹಿಸುವ ಅದೇ ಪಾತ್ರವನ್ನು ಅಂತಹ ಪ್ರಕ್ರಿಯೆಗಳಲ್ಲಿ ವಹಿಸುತ್ತಾರೆ.',
  'appellant':
    'ಕೆಳ ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯ ನಿರ್ಧಾರವನ್ನು ಪ್ರಶ್ನಿಸಿ ಮೇಲ್ಮನವಿ ದಾಖಲಿಸುವ ವ್ಯಕ್ತಿ, ಆ ನಿರ್ಧಾರವನ್ನು ಸಮರ್ಥಿಸುವ ಪ್ರತಿವಾದಿಗಿಂತ ಭಿನ್ನ.',
  'applicant':
    'ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯಿಂದ ನಿರ್ದಿಷ್ಟ ಆದೇಶ ಅಥವಾ ನಿರ್ದೇಶನ ಕೋರಿ ಅರ್ಜಿ ದಾಖಲಿಸುವ ವ್ಯಕ್ತಿ, ಮಧ್ಯಂತರ ಅರ್ಜಿಗಳಲ್ಲಿ ಮತ್ತು NCLT ಅಥವಾ ಗ್ರಾಹಕ ಆಯೋಗದಂತಹ ನ್ಯಾಯಮಂಡಳಿಗಳ ಮುಂದಿನ ಪ್ರಕ್ರಿಯೆಗಳಲ್ಲಿ ಹೆಚ್ಚಾಗಿ ಬಳಸುವ ಪದ.',
  'dismissal-for-default':
    'ಒಂದು ಪಕ್ಷ, ಸಾಮಾನ್ಯವಾಗಿ ವಾದಿ ಅಥವಾ ಮೇಲ್ಮನವಿದಾರ, ಹಾಜರಾಗಲು ಅಥವಾ ಕೋರ್ಟ್ ಫೀ ಪಾವತಿಸುವುದು ಅಥವಾ ದಾಖಲೆಗಳನ್ನು ಸಲ್ಲಿಸುವುದು ಮುಂತಾದ ಅಗತ್ಯ ಕ್ರಮ ಕೈಗೊಳ್ಳಲು ನಿಗದಿತ ಸಮಯದೊಳಗೆ ವಿಫಲರಾದ ಕಾರಣ ಪ್ರಕರಣವನ್ನು ಮುಚ್ಚುವ ಆದೇಶ. ಇದು ಪ್ರಕರಣದ ಹುರುಳಿನ ಬಗ್ಗೆ ನಿರ್ಧಾರ ಅಲ್ಲ.',
  'restoration-of-suit':
    'ಡಿಫಾಲ್ಟ್‌ಗಾಗಿ ವಜಾಗೊಳಿಸಲಾದ ಪ್ರಕರಣವನ್ನು ಪುನರುಜ್ಜೀವನಗೊಳಿಸಲು ನ್ಯಾಯಾಲಯವನ್ನು ಕೋರುವ ಅರ್ಜಿ, ಸಾಮಾನ್ಯವಾಗಿ ಹಿಂದಿನ ಗೈರುಹಾಜರಿ ಅಥವಾ ಅನುಸರಣೆ ಮಾಡದಿರುವಿಕೆಗೆ ಸಮರ್ಪಕ ಕಾರಣ ತೋರಿಸುವ ಮೂಲಕ. ಅನುಮತಿಸಿದರೆ, ಪ್ರಕರಣ ವಜಾಗೊಂಡ ಸ್ಥಳದಿಂದ ಮುಂದುವರಿಯುತ್ತದೆ.',
  'transfer-petition':
    'ಪಕ್ಷಗಳ ಅನುಕೂಲತೆ, ನ್ಯಾಯಸಮ್ಮತ ವಿಚಾರಣೆಯನ್ನು ಖಚಿತಪಡಿಸುವುದು, ಅಥವಾ ಬೇರೊಂದು ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಈಗಾಗಲೇ ಸಂಬಂಧಿತ ಪ್ರಕರಣ ಇರುವುದು ಮುಂತಾದ ಕಾರಣಗಳ ಆಧಾರದ ಮೇಲೆ, ಬಾಕಿ ಇರುವ ಪ್ರಕರಣವನ್ನು ಒಂದು ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯಿಂದ ಇನ್ನೊಂದಕ್ಕೆ ಸ್ಥಳಾಂತರಿಸಲು ಉನ್ನತ ನ್ಯಾಯಾಲಯವನ್ನು ಕೋರುವ ಮನವಿ.',
  'pecuniary-jurisdiction':
    'ಒಳಗೊಂಡಿರುವ ಹಕ್ಕಿನ ಹಣದ ಮೌಲ್ಯದ ಆಧಾರದ ಮೇಲೆ ಪ್ರಕರಣವನ್ನು ಆಲಿಸುವ ನ್ಯಾಯಾಲಯದ ಅಧಿಕಾರ. ನ್ಯಾಯಾಲಯಗಳು ಮತ್ತು ನ್ಯಾಯಮಂಡಳಿಗಳಿಗೆ ಸಾಮಾನ್ಯವಾಗಿ ಮೌಲ್ಯ ಶ್ರೇಣಿಗಳನ್ನು ನಿಗದಿಪಡಿಸಲಾಗಿದೆ, ಆದ್ದರಿಂದ ನಿಗದಿತ ಮಿತಿಗಿಂತ ಮೇಲೆ ಅಥವಾ ಕೆಳಗಿನ ಹಕ್ಕನ್ನು ಬೇರೆ ವೇದಿಕೆಯಲ್ಲಿ ದಾಖಲಿಸಬೇಕು.',
  'substituted-service':
    'ನೇರವಾಗಿ ಅಥವಾ ವ್ಯಕ್ತಿಗತವಾಗಿ ಒಂದು ಪಕ್ಷಕ್ಕೆ ಅದನ್ನು ತಲುಪಿಸಲು ಸಾಧ್ಯವಾಗದಿದ್ದಾಗ ಬಳಸುವ, ನೋಟಿಸ್ ಅಥವಾ ಸಮನ್ಸ್ ಜಾರಿ ಮಾಡುವ ಪರ್ಯಾಯ ವಿಧಾನ, ಉದಾಹರಣೆಗೆ ಪತ್ರಿಕೆಯಲ್ಲಿ ನೋಟಿಸ್ ಪ್ರಕಟಿಸುವುದು ಅಥವಾ ಪಕ್ಷದ ಕೊನೆಯ ತಿಳಿದಿರುವ ವಿಳಾಸದಲ್ಲಿ ಅಂಟಿಸುವುದು.',
  'court-fee':
    'ಪ್ಲೇಯಿಂಟ್, ಅರ್ಜಿ, ಅಥವಾ ಮೇಲ್ಮನವಿ ದಾಖಲಿಸುವ ಮೊದಲು, ಸಾಮಾನ್ಯವಾಗಿ ಸ್ಟ್ಯಾಂಪ್‌ಗಳ ಮೂಲಕ ಅಥವಾ ಆನ್‌ಲೈನ್ ಪಾವತಿಯ ಮೂಲಕ, ಸರ್ಕಾರಕ್ಕೆ ಪಾವತಿಸುವ ಶುಲ್ಕ. ಇದನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಪ್ರಕರಣದಲ್ಲಿ ಕೋರಿದ ಮೌಲ್ಯ ಅಥವಾ ಪ್ರಮಾಣದ ಶೇಕಡಾವಾರು ಆಧಾರದಲ್ಲಿ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ, ಕೆಲವು ಪ್ರಕಾರದ ಫೈಲಿಂಗ್‌ಗಳಿಗೆ ಮಿತಿಗೆ ಒಳಪಟ್ಟು.',
  'next-friend':
    'ಸಾಮಾನ್ಯವಾಗಿ ಪಾಲಕ ಅಥವಾ ಸಮೀಪ ಸಂಬಂಧಿ, ಅಪ್ರಾಪ್ತ ವಾದಿಯ ಪರವಾಗಿ ಸಿವಿಲ್ ದಾವೆಯನ್ನು ದಾಖಲಿಸಿ ನಿರ್ವಹಿಸುವ ಜವಾಬ್ದಾರ ವಯಸ್ಕ, ಅಪ್ರಾಪ್ತರು ಸ್ವಂತ ಹೆಸರಿನಲ್ಲಿ ಮೊಕದ್ದಮೆ ಹೂಡಲು ಸಾಧ್ಯವಿಲ್ಲದ ಕಾರಣ.',
  'petition':
    'ಲಿಖಿತ ಮನವಿ, ಕಂಪನಿ ಕಾನೂನು ಪ್ರಕರಣಗಳು, ವೈವಾಹಿಕ ಪ್ರಕರಣಗಳು, ಅಥವಾ ಕೆಲವು ವೇದಿಕೆಗಳಿಗೆ ಮೇಲ್ಮನವಿಗಳಂತಹ ವಿಷಯಗಳಲ್ಲಿ ಪ್ಲೇಯಿಂಟ್ ಬದಲಿಗೆ ಬಳಸುವ, ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯಿಂದ ನಿರ್ದಿಷ್ಟ ಕ್ರಮ ಕೈಗೊಳ್ಳಲು ಕೋರುವ ಔಪಚಾರಿಕ ಲಿಖಿತ ಮನವಿ. ಇದರ ರಚನೆ ಮತ್ತು ಅಗತ್ಯತೆಗಳು ವೇದಿಕೆ ಮತ್ತು ಪ್ರಕರಣದ ಪ್ರಕಾರವನ್ನು ಅವಲಂಬಿಸಿ ಬದಲಾಗುತ್ತವೆ.',
  'memorandum-of-appeal':
    'ಮೇಲ್ಮನವಿ ಪ್ರಾರಂಭಿಸಲು ದಾಖಲಿಸುವ ಔಪಚಾರಿಕ ದಾಖಲೆ, ಮೇಲ್ಮನವಿದಾರ ಕೆಳ ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯ ನಿರ್ಧಾರವನ್ನು ಪ್ರಶ್ನಿಸುವ ಆಧಾರಗಳನ್ನು ವಿವರಿಸುತ್ತದೆ. ಪ್ರತಿ ಆಧಾರವನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಹಿಂದಿನ ನಿರ್ಧಾರದಲ್ಲಿ ಏನು ತಪ್ಪಾಗಿತ್ತು ಎಂದು ವಿವರಿಸುವ ಪ್ರತ್ಯೇಕ ಸಂಖ್ಯೆಯ ಅಂಶವಾಗಿ ಪಟ್ಟಿ ಮಾಡಲಾಗುತ್ತದೆ.',
  'vakalatnama':
    'ಒಂದು ಪ್ರಕರಣದಲ್ಲಿ ತಮ್ಮನ್ನು ಪ್ರತಿನಿಧಿಸಲು ನಿರ್ದಿಷ್ಟ ವಕೀಲ ಅಥವಾ ಕಾನೂನು ಸಂಸ್ಥೆಗೆ ಅಧಿಕಾರ ನೀಡುವ, ಕ್ಲೈಂಟ್ ಸಹಿ ಮಾಡಿದ ದಾಖಲೆ. ವಕೀಲ ಔಪಚಾರಿಕವಾಗಿ ಹಾಜರಾಗಿ ಕ್ಲೈಂಟ್ ಪರವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುವ ಮೊದಲು ಇದನ್ನು ದಾಖಲಿಸಬೇಕು.',
  'index-of-documents':
    'ನ್ಯಾಯಾಲಯದ ಫೈಲಿಂಗ್‌ನ ಪ್ರಾರಂಭದಲ್ಲಿ ಇರಿಸಲಾದ ಪಟ್ಟಿ, ಅದರಲ್ಲಿ ಸೇರಿರುವ ಪ್ರತಿ ದಾಖಲೆಯ ಸಾರಾಂಶವನ್ನು ನೀಡುತ್ತದೆ, ಸಾಮಾನ್ಯವಾಗಿ ಪುಟ ಸಂಖ್ಯೆಗಳೊಂದಿಗೆ. ಇದು ನ್ಯಾಯಾಲಯ ಮತ್ತು ಇತರ ಕಡೆಯವರಿಗೆ ಫೈಲಿಂಗ್‌ನಲ್ಲಿ ಯಾವುದೇ ನಿರ್ದಿಷ್ಟ ದಾಖಲೆಯನ್ನು ತ್ವರಿತವಾಗಿ ಕಂಡುಹಿಡಿಯಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.',
  'annexure':
    'ಪ್ಲೀಡಿಂಗ್ ಅಥವಾ ಅರ್ಜಿಗೆ ಅದರಲ್ಲಿ ಹೇಳಿದ ಸಂಗತಿಗಳನ್ನು ಬೆಂಬಲಿಸಲು ಜೋಡಿಸಲಾದ ಒಪ್ಪಂದ, ರಸೀದಿ, ಅಥವಾ ಪತ್ರದಂತಹ ಪೋಷಕ ದಾಖಲೆ. ಅನೆಕ್ಷರ್‌ಗಳನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಅಕ್ಷರಗಳು ಅಥವಾ ಸಂಖ್ಯೆಗಳಿಂದ ಲೇಬಲ್ ಮಾಡಲಾಗುತ್ತದೆ ಮತ್ತು ಮುಖ್ಯ ದಾಖಲೆಯಲ್ಲಿ ಆ ಲೇಬಲ್‌ನಿಂದ ಉಲ್ಲೇಖಿಸಲಾಗುತ್ತದೆ.',
  'verification-clause':
    'ಪ್ಲೀಡಿಂಗ್‌ನ ಕೊನೆಯಲ್ಲಿ ಒಂದು ಸಣ್ಣ ಸಹಿ ಮಾಡಿದ ಹೇಳಿಕೆ, ಇದರಲ್ಲಿ ಅದನ್ನು ದಾಖಲಿಸುವ ವ್ಯಕ್ತಿ ಅದರ ವಿಷಯಗಳು ಅವರ ಜ್ಞಾನಕ್ಕೆ ಸತ್ಯವೆಂದು, ಅಥವಾ ಅವರು ಸತ್ಯವೆಂದು ನಂಬುವ ಮಾಹಿತಿಯ ಆಧಾರದಲ್ಲಿ ಎಂದು ದೃಢೀಕರಿಸುತ್ತಾರೆ. ಇದು ದಾಖಲೆಯಲ್ಲಿ ಹೇಳಿದ ವಿಷಯಕ್ಕಾಗಿ ದಾಖಲಿಸುವವರನ್ನು ವ್ಯಕ್ತಿಗತವಾಗಿ ಹೊಣೆಗಾರರನ್ನಾಗಿ ಮಾಡಲು ಉದ್ದೇಶಿಸಲಾಗಿದೆ.',
  'cause-title':
    'ನ್ಯಾಯಾಲಯದ ದಾಖಲೆಯ ಮೇಲ್ಭಾಗದಲ್ಲಿರುವ ಶಿರೋನಾಮೆ, ಇದು ನ್ಯಾಯಾಲಯ, ಪ್ರಕರಣ ಸಂಖ್ಯೆ, ಮತ್ತು ಒಳಗೊಂಡಿರುವ ಪಕ್ಷಗಳನ್ನು ಹೆಸರಿಸುತ್ತದೆ, ಸಾಮಾನ್ಯವಾಗಿ "ವಾದಿ ವಿರುದ್ಧ ಪ್ರತಿವಾದಿ" ಎಂದು ಬರೆಯಲಾಗುತ್ತದೆ. ಇದು ದಾಖಲೆ ಯಾವ ಪ್ರಕರಣಕ್ಕೆ ಸೇರಿದೆ ಎಂದು ನಿಖರವಾಗಿ ಗುರುತಿಸುತ್ತದೆ.',
  'prayer-clause':
    'ಪ್ಲೀಡಿಂಗ್ ಅಥವಾ ಅರ್ಜಿಯ ಭಾಗ, ಸಾಮಾನ್ಯವಾಗಿ ಕೊನೆಯಲ್ಲಿ, ಇದು ವ್ಯಕ್ತಿ ನ್ಯಾಯಾಲಯವನ್ನು ಯಾವ ನಿರ್ದಿಷ್ಟ ಪರಿಹಾರ ಅಥವಾ ಆದೇಶವನ್ನು ಕೋರುತ್ತಿದ್ದಾರೆ ಎಂದು ಸ್ಪಷ್ಟವಾಗಿ ಹೇಳುತ್ತದೆ. ಪ್ರೇಯರ್ ಕ್ಲಾಸ್‌ನಲ್ಲಿ ನಿರ್ದಿಷ್ಟವಾಗಿ ಕೋರದ ಪರಿಹಾರವನ್ನು ನ್ಯಾಯಾಲಯಗಳು ಸಾಮಾನ್ಯವಾಗಿ ನೀಡುವುದಿಲ್ಲ.',
  'schedule-to-document':
    'ಕಾನೂನು ದಾಖಲೆಯ ಕೊನೆಯಲ್ಲಿ, ಉದಾಹರಣೆಗೆ ಡೀಡ್ ಅಥವಾ ಪ್ಲೇಯಿಂಟ್‌ನಲ್ಲಿ, ದಾಖಲೆಯ ಇತರ ಭಾಗಗಳಲ್ಲಿ ಉಲ್ಲೇಖಿಸಲಾದ ವಿವರವಾದ ಮಾಹಿತಿ ನೀಡುವ ಭಾಗ, ಉದಾಹರಣೆಗೆ ಆಸ್ತಿಯ ನಿಖರ ವಿವರಣೆ ಮತ್ತು ಗಡಿಗಳು. ಈ ವಿವರವನ್ನು ಪ್ರತ್ಯೇಕ ಅನುಸೂಚಿಯಲ್ಲಿ ಇಡುವುದರಿಂದ ದಾಖಲೆಯ ಮುಖ್ಯ ಪಠ್ಯವನ್ನು ಓದಲು ಸುಲಭವಾಗುತ್ತದೆ.',
  'rejoinder':
    'ಪ್ರಕರಣ ಪ್ರಾರಂಭಿಸಿದ ಪಕ್ಷ ದಾಖಲಿಸುವ ಲಿಖಿತ ಪ್ರತಿಕ್ರಿಯೆ, ವಿರುದ್ಧ ಪಕ್ಷ ದಾಖಲಿಸಿದ ಲಿಖಿತ ಹೇಳಿಕೆ ಅಥವಾ ಪ್ರತಿಕ್ರಿಯೆಗೆ ಉತ್ತರಿಸುತ್ತದೆ. ಇದು ಎತ್ತಲಾದ ಹೊಸ ಅಂಶಗಳು ಅಥವಾ ಪ್ರತಿವಾದಗಳಿಗೆ ಮೂಲ ಪಕ್ಷ ಪ್ರತಿಕ್ರಿಯಿಸಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ.',
  'counter-affidavit':
    'ವಿರುದ್ಧ ಪಕ್ಷ ದಾಖಲಿಸಿದ ಅಫಿಡವಿಟ್ ಅಥವಾ ಅರ್ಜಿಗೆ ಪ್ರತಿಕ್ರಿಯೆಯಾಗಿ ಒಂದು ಪಕ್ಷ ದಾಖಲಿಸುವ ಅಫಿಡವಿಟ್, ಅದರಲ್ಲಿ ಮಾಡಿದ ಸಂಗತಿಗಳು ಮತ್ತು ಹಕ್ಕುಗಳನ್ನು ವಿವಾದಿಸುತ್ತದೆ ಅಥವಾ ಪ್ರತಿಕ್ರಿಯಿಸುತ್ತದೆ.',
  'legal-notice':
    'ಇನ್ನೊಬ್ಬ ವ್ಯಕ್ತಿ ಅಥವಾ ಸಂಸ್ಥೆಗೆ, ಸಾಮಾನ್ಯವಾಗಿ ವಕೀಲರ ಮೂಲಕ, ಕಳುಹಿಸುವ ಔಪಚಾರಿಕ ಲಿಖಿತ ಸಂವಹನ, ಅವರಿಗೆ ಕುಂದುಕೊರತೆಯ ಬಗ್ಗೆ ತಿಳಿಸುತ್ತದೆ ಮತ್ತು ಹೇಳಿದ ಸಮಯದೊಳಗೆ ಅದನ್ನು ಬಗೆಹರಿಸದಿದ್ದರೆ ಕಾನೂನು ಕ್ರಮದ ಬಗ್ಗೆ ಎಚ್ಚರಿಸುತ್ತದೆ. ಕೆಲವು ಪ್ರಕಾರದ ಪ್ರಕರಣಗಳನ್ನು ದಾಖಲಿಸುವ ಮೊದಲು ಒಂದನ್ನು ಕಳುಹಿಸುವುದು ಸಾಮಾನ್ಯವಾಗಿ ಅಗತ್ಯ ಅಥವಾ ಸಲಹೆಯ ಹಂತವಾಗಿದೆ.',
  'written-submissions':
    'ಒಂದು ಪಕ್ಷ ನ್ಯಾಯಾಲಯ ಪರಿಗಣಿಸಬೇಕೆಂದು ಬಯಸುವ ವಾದಗಳು ಮತ್ತು ಕಾನೂನು ಅಂಶಗಳನ್ನು ಲಿಖಿತವಾಗಿ ವಿವರಿಸುವ ದಾಖಲೆ, ಹೆಚ್ಚಾಗಿ ಬಾಯಿಮಾತಿನ ವಾದ ಮಾಡಿದ ನಂತರ ಅಥವಾ ದೀರ್ಘ ಬಾಯಿಮಾತಿನ ವಿಚಾರಣೆಯ ಬದಲಿಗೆ ದಾಖಲಿಸಲಾಗುತ್ತದೆ. ನ್ಯಾಯಾಲಯಗಳು ಹೆಚ್ಚಾಗಿ ತಮ್ಮ ಅಂತಿಮ ನಿರ್ಧಾರ ಬರೆಯುವಾಗ ಲಿಖಿತ ಸಲ್ಲಿಕೆಗಳನ್ನು ಮತ್ತೆ ಉಲ್ಲೇಖಿಸುತ್ತವೆ.',
  'certified-copy':
    'ನ್ಯಾಯಾಲಯದ ಆದೇಶ, ತೀರ್ಪು, ಅಥವಾ ದಾಖಲೆಯ ಅಧಿಕೃತ ಪ್ರತಿ, ಅದು ದಾಖಲೆಯಲ್ಲಿರುವ ಮೂಲದ ನಿಜವಾದ ಮತ್ತು ನಿಖರವಾದ ಪ್ರತಿ ಎಂದು ದೃಢೀಕರಿಸಲು ನ್ಯಾಯಾಲಯದ ರಿಜಿಸ್ಟ್ರಿಯಿಂದ ಮುದ್ರೆ ಹಾಕಿ ಸಹಿ ಮಾಡಲಾಗಿದೆ. ಮೇಲ್ಮನವಿ ದಾಖಲಿಸಲು ಅಥವಾ ಇನ್ನೆಲ್ಲಿಯಾದರೂ ದಾಖಲೆಯ ವಿಷಯಗಳನ್ನು ಸಾಬೀತುಪಡಿಸಲು ಪ್ರಮಾಣೀಕೃತ ಪ್ರತಿಗಳು ಹೆಚ್ಚಾಗಿ ಅಗತ್ಯವಾಗಿವೆ.',
  'memorandum-of-parties':
    'ಅರ್ಜಿ ಅಥವಾ ಮೇಲ್ಮನವಿಯ ಪ್ರಾರಂಭದಲ್ಲಿ ಇರುವ ಪಟ್ಟಿ, ಪ್ರಕರಣದ ಪ್ರತಿ ಪಕ್ಷವನ್ನು ಅವರ ವಿಳಾಸಗಳೊಂದಿಗೆ ಹೆಸರಿಸುತ್ತದೆ, ಚಿಕ್ಕ ಕಾಸ್ ಟೈಟಲ್‌ಗಿಂತ ಭಿನ್ನ. ಪ್ರತ್ಯೇಕವಾಗಿ ಪೂರ್ಣ ಪಕ್ಷದ ವಿವರಗಳನ್ನು ಬೇಡುವ ಫೈಲಿಂಗ್‌ಗಳಲ್ಲಿ, ಉದಾಹರಣೆಗೆ ಹೈಕೋರ್ಟ್‌ಗಳು ಮತ್ತು ಸುಪ್ರೀಂ ಕೋರ್ಟ್‌ಗಳ ಮುಂದೆ, ಇದನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.',
  'synopsis-and-list-of-dates':
    'ಹೈಕೋರ್ಟ್‌ಗಳು ಮತ್ತು ಸುಪ್ರೀಂ ಕೋರ್ಟ್‌ನಲ್ಲಿ ಅರ್ಜಿಗಳ ಪ್ರಾರಂಭದಲ್ಲಿ ದಾಖಲಿಸುವ, ಪ್ರಕರಣದ ಹಿನ್ನೆಲೆಯ ಸಣ್ಣ ಸಾರಾಂಶ, ಜೊತೆಗೆ ಪ್ರಮುಖ ಘಟನೆಗಳ ಕಾಲಾನುಕ್ರಮ ಕೋಷ್ಟಕ ಮತ್ತು ಅವುಗಳ ದಿನಾಂಕಗಳು. ಪೂರ್ಣ ಅರ್ಜಿಯನ್ನು ಓದುವ ಮೊದಲು ನ್ಯಾಯಾಧೀಶರು ಪ್ರಕರಣದ ಇತಿಹಾಸವನ್ನು ತ್ವರಿತವಾಗಿ ಗ್ರಹಿಸಲು ಇದು ಸಹಾಯ ಮಾಡುತ್ತದೆ.',
  'written-version':
    'ಗ್ರಾಹಕ ಆಯೋಗದ ಮುಂದಿನ ಪ್ರಕರಣದಲ್ಲಿ ವಿರುದ್ಧ ಪಕ್ಷ ದಾಖಲಿಸುವ ಔಪಚಾರಿಕ ಲಿಖಿತ ಉತ್ತರ, ದೂರಿನಲ್ಲಿ ಮಾಡಿದ ಆರೋಪಗಳಿಗೆ ಉತ್ತರಿಸುತ್ತದೆ. ಸಾಮಾನ್ಯ ಸಿವಿಲ್ ದಾವೆಯಲ್ಲಿ ಲಿಖಿತ ಹೇಳಿಕೆ ಮಾಡುವ ಉದ್ದೇಶವನ್ನೇ ಇದು ಅಲ್ಲಿ ಪೂರೈಸುತ್ತದೆ.',
  'memorandum-of-appearance':
    'NCLT ಯಂತಹ ಕೆಲವು ನ್ಯಾಯಮಂಡಳಿಗಳ ಮುಂದೆ ದಾಖಲಿಸುವ ದಾಖಲೆ, ಇದರ ಮೂಲಕ ಪಕ್ಷದ ಅಧಿಕೃತ ಪ್ರತಿನಿಧಿ ಪ್ರಕರಣದಲ್ಲಿ ಔಪಚಾರಿಕವಾಗಿ ಹಾಜರಾಗುತ್ತಾರೆ, ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ದಾಖಲಿಸುವ ವಕಾಲತ್‌ನಾಮಾದಂತೆಯೇ ಉದ್ದೇಶ ಪೂರೈಸುತ್ತದೆ.',
  'affidavit-of-service':
    'ಇನ್ನೊಂದು ಪಕ್ಷದ ಮೇಲೆ ನೋಟಿಸ್, ಸಮನ್ಸ್, ಅಥವಾ ಇತರ ದಾಖಲೆ ಜಾರಿ ಮಾಡಿದ ವ್ಯಕ್ತಿ ದಾಖಲಿಸುವ ಅಫಿಡವಿಟ್, ಅದನ್ನು ಯಾವಾಗ, ಹೇಗೆ, ಮತ್ತು ಯಾರ ಮೇಲೆ ಜಾರಿ ಮಾಡಲಾಗಿದೆ ಎಂದು ದೃಢೀಕರಿಸುತ್ತದೆ. ಸರಿಯಾಗಿ ಸೇವೆ ಸಲ್ಲಿಸಲಾಗಿದೆ ಎಂದು ತೃಪ್ತರಾಗಲು ನ್ಯಾಯಾಲಯಗಳು ಇದನ್ನು ಅವಲಂಬಿಸುತ್ತವೆ.',
  'list-of-witnesses':
    'ಸಾಕ್ಷ್ಯ ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲು ಒಂದು ಪಕ್ಷ ದಾಖಲಿಸುವ ಪಟ್ಟಿ, ಅವರು ತಮ್ಮ ಪ್ರಕರಣ ಸಾಬೀತುಪಡಿಸಲು ಹಾಜರುಪಡಿಸಲು ಉದ್ದೇಶಿಸಿರುವ ಸಾಕ್ಷಿಗಳನ್ನು ಹೆಸರಿಸುತ್ತದೆ. ಇದು ಯಾರನ್ನು ಪರೀಕ್ಷಿಸಲಾಗುವುದು ಎಂದು ನ್ಯಾಯಾಲಯ ಮತ್ತು ಇತರ ಕಡೆಯವರಿಗೆ ಮುಂಚಿತವಾಗಿ ತಿಳಿಸುತ್ತದೆ.',
  'paper-book':
    'ಪ್ರಕರಣದಲ್ಲಿರುವ ಎಲ್ಲಾ ಸಂಬಂಧಿತ ಪ್ಲೀಡಿಂಗ್‌ಗಳು, ದಾಖಲೆಗಳು, ಮತ್ತು ಆದೇಶಗಳ ಸಂಗ್ರಹಿತ ಸೆಟ್, ಒಟ್ಟಿಗೆ ಬೈಂಡ್ ಮಾಡಿ ಸೂಚಿಕೆ ಮಾಡಲಾಗುತ್ತದೆ, ಮುಖ್ಯವಾಗಿ ಮೇಲ್ಮನವಿಗಳು ಮತ್ತು ಉನ್ನತ ನ್ಯಾಯಾಲಯಗಳು ಮತ್ತು ನ್ಯಾಯಮಂಡಳಿಗಳ ಮುಂದಿನ ವಿಚಾರಣೆಗಳಿಗಾಗಿ ತಯಾರಿಸಲಾಗುತ್ತದೆ.',
  'supplementary-affidavit':
    'ಮೂಲ ಅಫಿಡವಿಟ್ ನಂತರ ಒಂದು ಪಕ್ಷ ದಾಖಲಿಸುವ ಹೆಚ್ಚುವರಿ ಅಫಿಡವಿಟ್, ಸಂಪೂರ್ಣವಾಗಿ ಹೊಸ ಅರ್ಜಿ ದಾಖಲಿಸುವ ಬದಲು, ಮೊದಲು ಒಳಗೊಳ್ಳದ ಹೊಸ ಸಂಗತಿಗಳು, ದಾಖಲೆಗಳು, ಅಥವಾ ಬೆಳವಣಿಗೆಗಳನ್ನು ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಇಡಲು.',
  'amendment-of-pleadings':
    'ಅದನ್ನು ಈಗಾಗಲೇ ದಾಖಲಿಸಿದ ನಂತರ, ಒಂದು ಸಂಗತಿ ಅಥವಾ ಪರಿಹಾರ ಸೇರಿಸುವಂತಹ, ಒಂದು ಪಕ್ಷ ತಮ್ಮ ಪ್ಲೇಯಿಂಟ್ ಅಥವಾ ಲಿಖಿತ ಹೇಳಿಕೆಯಲ್ಲಿ ತಿದ್ದುಪಡಿ ಅಥವಾ ಸೇರ್ಪಡೆ ಮಾಡಲು ನ್ಯಾಯಾಲಯದ ಅನುಮತಿ. ಇದು ಪ್ರಕರಣದ ಸ್ವರೂಪವನ್ನು ಮೂಲಭೂತವಾಗಿ ಬದಲಾಯಿಸದಿದ್ದರೆ ನ್ಯಾಯಾಲಯಗಳು ಸಾಮಾನ್ಯವಾಗಿ ಇದನ್ನು ಅನುಮತಿಸುತ್ತವೆ.',
  'undertaking':
    'ನ್ಯಾಯಾಲಯಕ್ಕೆ ನೀಡಿದ ಔಪಚಾರಿಕ ವಾಗ್ದಾನ, ಬಾಯಿಮಾತಿನಲ್ಲಿ ಮತ್ತು ಆದೇಶದಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ, ಅಥವಾ ಅಫಿಡವಿಟ್ ಮೂಲಕ, ಒಂದು ಪಕ್ಷ ಒಂದು ನಿರ್ದಿಷ್ಟ ವಿಷಯವನ್ನು ಮಾಡುತ್ತಾರೆ ಅಥವಾ ಮಾಡುವುದಿಲ್ಲ ಎಂದು. ನ್ಯಾಯಾಲಯಕ್ಕೆ ನೀಡಿದ ಭರವಸೆಯನ್ನು ಮುರಿಯುವುದು ಸ್ವತಃ ನ್ಯಾಯಾಂಗ ನಿಂದನೆಗೆ ಸಮನಾಗಬಹುದು.',
  'notice-of-motion':
    'ಮುಖ್ಯವಾಗಿ ಕೆಲವು ಹೈಕೋರ್ಟ್‌ಗಳ ಮೂಲ ಸಿವಿಲ್ ಅಧಿಕಾರವ್ಯಾಪ್ತಿಯಲ್ಲಿ ದಾಖಲಿಸುವ ಔಪಚಾರಿಕ ನೋಟಿಸ್, ಮಧ್ಯಂತರ ಪರಿಹಾರಕ್ಕಾಗಿ ಅರ್ಜಿಯನ್ನು ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕದಂದು ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಇಡಲಾಗುವುದು ಎಂದು ವಿರುದ್ಧ ಕಡೆಯವರಿಗೆ ತಿಳಿಸುತ್ತದೆ.',
  'reply-to-legal-notice':
    'ಕಾನೂನು ನೋಟಿಸ್ ಸ್ವೀಕೃತದಾರ, ತಮ್ಮ ಸ್ವಂತ ವಕೀಲರ ಮೂಲಕ, ಯಾವುದೇ ಪ್ರಕರಣ ದಾಖಲಿಸುವ ಮೊದಲು, ಅದರಲ್ಲಿ ಮಾಡಿದ ಹಕ್ಕುಗಳನ್ನು ಒಪ್ಪಿಕೊಳ್ಳುವ, ನಿರಾಕರಿಸುವ, ಅಥವಾ ವಿವರಿಸುವ ಕಳುಹಿಸುವ ಲಿಖಿತ ಪ್ರತಿಕ್ರಿಯೆ.',
  'compilation-of-judgments':
    'ಒಂದು ಪಕ್ಷ ಪ್ರಕರಣದಲ್ಲಿ ಮಾಡಿದ ಕಾನೂನು ವಾದಗಳನ್ನು ಬೆಂಬಲಿಸಲು ಅವಲಂಬಿಸುವ ಮತ್ತು ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ದಾಖಲಿಸುವ, ಈ ಮೊದಲು ನಿರ್ಧರಿಸಲಾದ ತೀರ್ಪುಗಳ ಬೈಂಡ್ ಮಾಡಿದ ಸೆಟ್.',
  'examination-in-chief':
    'ಸಾಕ್ಷಿಯನ್ನು ಸಾಕ್ಷ್ಯ ನೀಡಲು ಕರೆದ ಪಕ್ಷದ ವಕೀಲರು ನಡೆಸುವ ಸಾಕ್ಷಿಯ ಮೊದಲ ಪ್ರಶ್ನೆ ಸುತ್ತು. ಅದರ ಉದ್ದೇಶ ಆ ಪಕ್ಷದ ಪ್ರಕರಣವನ್ನು ಬೆಂಬಲಿಸುವ ಸಂಗತಿಗಳನ್ನು ಹೊರಗೆಳೆಯುವುದು.',
  'cross-examination':
    'ಮುಖ್ಯ ಪರೀಕ್ಷೆ ಮುಗಿದ ನಂತರ ವಿರುದ್ಧ ಪಕ್ಷದ ವಕೀಲರು ಸಾಕ್ಷಿಯನ್ನು ಪ್ರಶ್ನಿಸುವುದು. ಇದರ ಉದ್ದೇಶ ಸಾಕ್ಷಿಯ ಕಥೆಯನ್ನು ಪರೀಕ್ಷಿಸುವುದು, ದೌರ್ಬಲ್ಯಗಳು ಅಥವಾ ವಿರೋಧಾಭಾಸಗಳನ್ನು ಬಹಿರಂಗಪಡಿಸುವುದು, ಮತ್ತು ಅವರ ವಿಶ್ವಾಸಾರ್ಹತೆಯನ್ನು ಪ್ರಶ್ನಿಸುವುದು.',
  're-examination':
    'ಅಡ್ಡ ಪರೀಕ್ಷೆಯ ನಂತರ ನಡೆಸುವ, ಸಾಕ್ಷಿಯನ್ನು ಮೂಲತಃ ಕರೆದ ಪಕ್ಷದಿಂದ ಹೆಚ್ಚಿನ ಪ್ರಶ್ನೆ ಸುತ್ತು, ಅಡ್ಡ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಎದ್ದ ಅಂಶಗಳನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಲು ಮಾತ್ರ ಸೀಮಿತವಾಗಿದೆ.',
  'hearsay':
    'ಸಾಕ್ಷಿ ವ್ಯಕ್ತಿಗತವಾಗಿ ನೋಡಿದ ಅಥವಾ ಅನುಭವಿಸಿದ ಸಂಗತಿಯ ಬದಲು, ಇನ್ನೊಬ್ಬರು ಹೇಳಿದ್ದನ್ನು ಬಗ್ಗೆ ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಮಾಡುವ ಹೇಳಿಕೆ. ಹಿಯರ್‌ಸೇಯನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ವಿಶ್ವಾಸಾರ್ಹ ಸಾಕ್ಷ್ಯವೆಂದು ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ, ಆದರೂ ಅದನ್ನು ಸ್ವೀಕರಿಸಬಹುದಾದ ಮಾನ್ಯ ವಿನಾಯಿತಿಗಳಿವೆ.',
  'burden-of-proof':
    'ಒಂದು ಪಕ್ಷ ತಾನು ಹೇಳುತ್ತಿರುವ ಸಂಗತಿಗಳನ್ನು ಸಾಬೀತುಪಡಿಸುವ ಒಟ್ಟಾರೆ ಕಾನೂನು ಕಡ್ಡಾಯ, ಆದ್ದರಿಂದ ಅವರು ಯಾವುದೇ ಸಾಕ್ಷ್ಯ ನೀಡದಿದ್ದರೆ, ಅವರು ಆ ಅಂಶದಲ್ಲಿ ಸೋಲುತ್ತಾರೆ. ಹೆಚ್ಚಿನ ಸಿವಿಲ್ ಮತ್ತು ಕ್ರಿಮಿನಲ್ ಪ್ರಕರಣಗಳಲ್ಲಿ, ಈ ಜವಾಬ್ದಾರಿಯನ್ನು ಕಾನೂನು ಆರಂಭದಲ್ಲೇ ನಿಗದಿಪಡಿಸುತ್ತದೆ ಮತ್ತು ಸಾಮಾನ್ಯವಾಗಿ ಇತರ ಪಕ್ಷಕ್ಕೆ ಬದಲಾಗುವುದಿಲ್ಲ.',
  'deposition':
    'ಮುಖ್ಯ ಪರೀಕ್ಷೆ, ಅಡ್ಡ ಪರೀಕ್ಷೆ, ಮತ್ತು ಪುನರ್ ಪರೀಕ್ಷೆಯ ಹಾದಿಯಲ್ಲಿ ದಾಖಲಿಸಲಾದ ಸಾಕ್ಷಿಯ ಪ್ರಮಾಣ ಮಾಡಿದ ಸಾಕ್ಷ್ಯದ ಔಪಚಾರಿಕ ದಾಖಲೆ. ಇದು ಪ್ರಕರಣ ನಿರ್ಧರಿಸುವಾಗ ನ್ಯಾಯಾಲಯ ಅವಲಂಬಿಸುವ ಅಧಿಕೃತ ಪ್ರಕರಣ ದಾಖಲೆಯ ಭಾಗವಾಗುತ್ತದೆ.',
  'exhibit-evidence':
    'ಪ್ರಕರಣದ ಹಾದಿಯಲ್ಲಿ ಔಪಚಾರಿಕವಾಗಿ ಸಾಕ್ಷ್ಯಕ್ಕೆ ಸೇರಿಸಲಾದ ಮತ್ತು ನಂತರ ಗುರುತಿಸಲು ಉಲ್ಲೇಖ ಸಂಖ್ಯೆ ಅಥವಾ ಅಕ್ಷರದಿಂದ ಗುರುತಿಸಲಾದ ದಾಖಲೆ ಅಥವಾ ವಸ್ತು. ಒಮ್ಮೆ ಎಕ್ಸಿಬಿಟ್ ಆಗಿ ಗುರುತಿಸಿದ ನಂತರ, ನ್ಯಾಯಾಲಯ ಮತ್ತು ಎರಡೂ ಕಡೆಯವರು ಪ್ರಕರಣದ ಉಳಿದ ಅವಧಿಯಲ್ಲಿ ಆ ಗುರುತಿನಿಂದ ಅದನ್ನು ಉಲ್ಲೇಖಿಸಬಹುದು.',
  'documentary-evidence':
    'ಒಪ್ಪಂದಗಳು, ಪತ್ರಗಳು, ರಸೀದಿಗಳು, ಅಥವಾ ಎಲೆಕ್ಟ್ರಾನಿಕ್ ದಾಖಲೆಗಳಂತಹ ಲಿಖಿತ ಅಥವಾ ದಾಖಲಿತ ವಸ್ತುಗಳ ರೂಪದಲ್ಲಿ ಸಾಕ್ಷ್ಯ, ಪ್ರಕರಣದಲ್ಲಿ ಒಂದು ಸಂಗತಿಯನ್ನು ಸಾಬೀತುಪಡಿಸಲು ಪ್ರಸ್ತುತಪಡಿಸಲಾಗುತ್ತದೆ. ಸಾಕ್ಷಿ ವ್ಯಕ್ತಿಗತವಾಗಿ ನೀಡುವ ಬಾಯಿಮಾತಿನ ಸಾಕ್ಷ್ಯದಿಂದ ಇದನ್ನು ಪ್ರತ್ಯೇಕಿಸಲಾಗಿದೆ.',
  'oral-evidence':
    'ಲಿಖಿತ ಅಥವಾ ದಾಖಲಿತ ರೂಪದಲ್ಲಿರುವ ದಾಖಲೆ ಸಾಕ್ಷ್ಯಕ್ಕೆ ವಿರುದ್ಧವಾಗಿ, ಸಾಮಾನ್ಯವಾಗಿ ಪ್ರಮಾಣದ ಅಡಿಯಲ್ಲಿ, ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ನೇರವಾಗಿ ಮಾತನಾಡುವ ಸಾಕ್ಷಿ ನೀಡುವ ಸಾಕ್ಷ್ಯ. ಬಾಯಿಮಾತಿನ ಸಾಕ್ಷ್ಯವನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಮುಖ್ಯ ಪರೀಕ್ಷೆ, ಅಡ್ಡ ಪರೀಕ್ಷೆ, ಮತ್ತು ಪುನರ್ ಪರೀಕ್ಷೆಯ ಮೂಲಕ ತೆಗೆದುಕೊಂಡು ದಾಖಲಿಸಲಾಗುತ್ತದೆ.',
  'admission-evidence':
    'ಬಾಯಿಮಾತಿನಲ್ಲಿ, ಲಿಖಿತವಾಗಿ, ಅಥವಾ ನಡವಳಿಕೆಯ ಮೂಲಕ ಮಾಡಿದ ಹೇಳಿಕೆ, ಇದರಲ್ಲಿ ಒಂದು ಪಕ್ಷ ಪ್ರಕರಣದಲ್ಲಿ ತಮ್ಮ ಸ್ವಂತ ಹಿತಾಸಕ್ತಿಗೆ ವಿರುದ್ಧವಾದ ಸಂಗತಿಯನ್ನು ಒಪ್ಪಿಕೊಳ್ಳುತ್ತಾರೆ. ಒಬ್ಬ ವ್ಯಕ್ತಿ ತಮ್ಮ ಸ್ವಂತ ಪ್ರಕರಣಕ್ಕೆ ಹಾನಿ ಮಾಡುವ ಸುಳ್ಳನ್ನು ಒಪ್ಪಿಕೊಳ್ಳುವ ಸಾಧ್ಯತೆ ಕಡಿಮೆಯಿರುವುದರಿಂದ, ನ್ಯಾಯಾಲಯಗಳು ಒಪ್ಪಿಗೆಗಳನ್ನು ಬಲವಾದ ಸಾಕ್ಷ್ಯವೆಂದು ಪರಿಗಣಿಸುತ್ತವೆ.',
  'onus-of-proof':
    'ಒಟ್ಟಾರೆ ಸಾಕ್ಷ್ಯದ ಹೊರೆಗಿಂತ ಭಿನ್ನವಾಗಿ, ವಿಚಾರಣೆಯ ಒಂದು ನಿರ್ದಿಷ್ಟ ಹಂತದಲ್ಲಿ ಒಂದು ನಿರ್ದಿಷ್ಟ ವಿಷಯದ ಮೇಲೆ ಸಾಕ್ಷ್ಯ ಉತ್ಪಾದಿಸುವ ಕಡ್ಡಾಯ. ಸಾಕ್ಷ್ಯದ ಹೊರೆಗಿಂತ ಭಿನ್ನವಾಗಿ, ಓನಸ್ ಪ್ರತಿ ಕಡೆ ಒಂದು ಅಂಶದ ಮೇಲೆ ಸಾಕ್ಷ್ಯ ಉತ್ಪಾದಿಸುವಲ್ಲಿ ಅಥವಾ ಉತ್ಪಾದಿಸಲು ವಿಫಲವಾದಲ್ಲಿ, ಪಕ್ಷಗಳ ನಡುವೆ ಮುಂದೆ ಹಿಂದೆ ಬದಲಾಗಬಹುದು.',
  'hostile-witness':
    'ಸಾಕ್ಷ್ಯ ನೀಡುವಾಗ, ಅವರನ್ನು ಕರೆದ ಪಕ್ಷಕ್ಕೆ ಮೊದಲು ನೀಡಿದ ಹೇಳಿಕೆಗೆ ವಿರೋಧಾಭಾಸ ಮಾಡುವ, ಅಥವಾ ಇಲ್ಲದಿದ್ದರೆ ಆ ಪಕ್ಷದ ಪ್ರಕರಣವನ್ನು ಬೆಂಬಲಿಸಲು ಇಷ್ಟವಿಲ್ಲದಂತೆ ಕಾಣುವ ಸಾಕ್ಷಿ. ಒಮ್ಮೆ ನ್ಯಾಯಾಲಯ ಸಾಕ್ಷಿಯನ್ನು ಹಗೆ ಎಂದು ಘೋಷಿಸಿದ ನಂತರ, ಅವರನ್ನು ಕರೆದ ಪಕ್ಷಕ್ಕೆ ಅಡ್ಡ ಪರೀಕ್ಷೆಯಂತೆಯೇ ಅವರನ್ನು ಹೆಚ್ಚು ನೇರವಾಗಿ ಪ್ರಶ್ನಿಸಲು ಅನುಮತಿಸಬಹುದು.',
  'expert-opinion':
    'ವೈದ್ಯ, ಫೊರೆನ್ಸಿಕ್ ಪರೀಕ್ಷಕ, ಅಥವಾ ಕೈಬರಹ ತಜ್ಞರಂತಹ ನಿರ್ದಿಷ್ಟ ಕ್ಷೇತ್ರದಲ್ಲಿ ವಿಶೇಷ ಕೌಶಲ್ಯ ಅಥವಾ ಜ್ಞಾನ ಹೊಂದಿರುವ ವ್ಯಕ್ತಿಯ ಅಭಿಪ್ರಾಯ, ನ್ಯಾಯಾಲಯ ಸ್ವತಃ ನಿರ್ಧರಿಸಲಾಗದ ತಾಂತ್ರಿಕ ಪ್ರಶ್ನೆಯ ಮೇಲೆ ಸಾಕ್ಷ್ಯವಾಗಿ ಪ್ರಸ್ತುತಪಡಿಸಲಾಗುತ್ತದೆ. ನ್ಯಾಯಾಲಯ ತಜ್ಞರ ಅಭಿಪ್ರಾಯವನ್ನು ಅಂಗೀಕರಿಸಲು ಬದ್ಧವಾಗಿರುವ ಬದಲು ಉಳಿದ ಸಾಕ್ಷ್ಯದೊಂದಿಗೆ ಅದನ್ನು ತೂಗುತ್ತದೆ.',
  'circumstantial-evidence':
    'ಒಂದು ಸಂಗತಿಯನ್ನು ನೇರವಾಗಿ ಸಾಬೀತುಪಡಿಸದ, ಆದರೆ ಸಂಬಂಧಿತ ಸನ್ನಿವೇಶಗಳ ಸರಣಿಯಿಂದ ನ್ಯಾಯಾಲಯ ಸಮಂಜಸವಾಗಿ ಅದನ್ನು ಅನುಮಾನಿಸಲು ಅನುವು ಮಾಡುವ ಸಾಕ್ಷ್ಯ. ಕೇವಲ ಸಾಂದರ್ಭಿಕ ಸಾಕ್ಷ್ಯದ ಆಧಾರದ ಮೇಲೆ ನ್ಯಾಯಾಲಯಗಳು ಶಿಕ್ಷೆ ನೀಡಬಹುದು ಅಥವಾ ಪ್ರಕರಣ ನಿರ್ಧರಿಸಬಹುದು, ಆದರೆ ಸಾಮಾನ್ಯವಾಗಿ ಸನ್ನಿವೇಶಗಳು ಒಟ್ಟಾಗಿ ಒಂದೇ ವಿವರಣೆಗೆ ನಿರ್ಣಾಯಕವಾಗಿ ಸೂಚಿಸಿದಾಗ ಮಾತ್ರ.',
  'corroboration':
    'ಮೊದಲೇ ನೀಡಿದ ಇನ್ನೊಂದು ಸಾಕ್ಷ್ಯವನ್ನು ಬೆಂಬಲಿಸುವ ಮತ್ತು ದೃಢೀಕರಿಸುವ ಸ್ವತಂತ್ರ ಸಾಕ್ಷ್ಯ, ಉದಾಹರಣೆಗೆ ಎರಡನೇ ಸಾಕ್ಷಿ ಮೊದಲ ಸಾಕ್ಷಿಯ ಕಥೆಯನ್ನು ಬೆಂಬಲಿಸುವುದು. ಕೆಲವು ಪ್ರಕಾರದ ಸಾಕ್ಷ್ಯಗಳನ್ನು, ಅವು ಪುಷ್ಟೀಕರಿಸಲ್ಪಟ್ಟಾಗ, ಹೆಚ್ಚು ವಿಶ್ವಾಸಾರ್ಹವೆಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ, ಅಥವಾ ಕೆಲವು ಸಂದರ್ಭಗಳಲ್ಲಿ ಪ್ರಾಕ್ಟೀಸ್‌ನಿಂದ ಅಗತ್ಯವಾಗಿವೆ.',
  'presumption':
    'ಕಾನೂನು ಕೆಲವು ಸಂಗತಿಗಳಿಂದ ನ್ಯಾಯಾಲಯ ತೆಗೆಯಲು ಅನುಮತಿಸುವ, ಅಥವಾ ಅಗತ್ಯಪಡಿಸುವ ತೀರ್ಮಾನ, ವಿರುದ್ಧ ಸಾಕ್ಷ್ಯದಿಂದ ಅದನ್ನು ನಿರಾಕರಿಸದ ಹೊರತು. ಉದಾಹರಣೆಗೆ, ಒಂದು ನಿರ್ದಿಷ್ಟ ವರ್ಷಗಳಿಗಿಂತ ಹಳೆಯದಾಗಿದ್ದು ಸರಿಯಾದ ಪಾಲನೆಯಿಂದ ಹೊರಬಂದ ದಾಖಲೆಯನ್ನು, ಪ್ರತ್ಯೇಕ ಸಾಬೀತು ಇಲ್ಲದೆ, ನಿಜವೆಂದು ಭಾವಿಸಬಹುದು.',
  'interrogatories':
    'ಒಂದು ಸಿವಿಲ್ ಪ್ರಕರಣದಲ್ಲಿ ಒಂದು ಪಕ್ಷ, ವಿಚಾರಣೆಗೆ ಮೊದಲು ಪ್ರಕರಣಕ್ಕೆ ಸಂಬಂಧಿತ ಸಂಗತಿಗಳು ಅಥವಾ ಒಪ್ಪಿಗೆಗಳನ್ನು ಪಡೆಯಲು, ವಿರುದ್ಧ ಪಕ್ಷ ಪ್ರಮಾಣದ ಅಡಿಯಲ್ಲಿ ಉತ್ತರಿಸಬೇಕೆಂದು ಬೇಡಬಹುದಾದ ಲಿಖಿತ ಪ್ರಶ್ನೆಗಳ ಸೆಟ್.',
  'discovery-of-documents':
    'ಒಂದು ಸಿವಿಲ್ ಪ್ರಕರಣದಲ್ಲಿ ಒಂದು ಪಕ್ಷ, ವಿಚಾರಣೆ ಪ್ರಾರಂಭವಾಗುವ ಮೊದಲು, ಇತರ ಕಡೆಯವರು ತಮ್ಮ ಬಳಿ ಹೊಂದಿರುವ ಪ್ರಕರಣಕ್ಕೆ ಸಂಬಂಧಿತ ದಾಖಲೆಗಳನ್ನು ಬಹಿರಂಗಪಡಿಸಿ ಹಾಜರುಪಡಿಸಬೇಕೆಂದು ಬೇಡಬಹುದಾದ ಕಾರ್ಯವಿಧಾನ.',
  'evidence-by-affidavit':
    'ಮುಖ್ಯವಾಗಿ ನ್ಯಾಯಮಂಡಳಿಗಳು ಮತ್ತು ಆಯೋಗಗಳ ಮುಂದೆ ಅನುಸರಿಸುವ ಪ್ರಾಕ್ಟೀಸ್, ಇದರಲ್ಲಿ ಸಾಕ್ಷಿಯ ಮುಖ್ಯ ಪರೀಕ್ಷೆಯನ್ನು ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಬಾಯಿಮಾತಿನಲ್ಲಿ ನೀಡುವ ಬದಲು ಪ್ರಮಾಣ ಮಾಡಿದ ಅಫಿಡವಿಟ್ ರೂಪದಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ. ಆ ಅಫಿಡವಿಟ್‌ನಲ್ಲಿ ಮಾಡಿದ ಹೇಳಿಕೆಗಳ ಮೇಲೆ ಅಡ್ಡ ಪರೀಕ್ಷೆಗೆ ಸಾಕ್ಷಿಯನ್ನು ಇನ್ನೂ ಕರೆಯಬಹುದು.',
  'primary-evidence':
    'ನ್ಯಾಯಾಲಯದ ತಪಾಸಣೆಗೆ ಹಾಜರುಪಡಿಸಲಾದ ಮೂಲ ದಾಖಲೆ ಸ್ವತಃ, ಅದರ ವಿಷಯಗಳ ಪ್ರತಿ ಅಥವಾ ಬಾಯಿಮಾತಿನ ಖಾತೆಯಂತಹ ದ್ವಿತೀಯ ಸಾಕ್ಷ್ಯಕ್ಕೆ ವಿರುದ್ಧ. ಮೂಲ ದಾಖಲೆ ಲಭ್ಯವಿರುವಲ್ಲೆಲ್ಲಾ ನ್ಯಾಯಾಲಯಗಳು ಸಾಮಾನ್ಯವಾಗಿ ಪ್ರಾಥಮಿಕ ಸಾಕ್ಷ್ಯಕ್ಕಾಗಿ ಒತ್ತಾಯಿಸುತ್ತವೆ.',
  'secondary-evidence':
    'ಮೂಲಕ್ಕಿಂತ ಬೇರೆ ದಾಖಲೆಯ ವಿಷಯಗಳ ಸಾಕ್ಷ್ಯ, ಉದಾಹರಣೆಗೆ ಪ್ರಮಾಣೀಕೃತ ಪ್ರತಿ ಅಥವಾ ಅದನ್ನು ನೋಡಿದ ವ್ಯಕ್ತಿಯ ಬಾಯಿಮಾತಿನ ಖಾತೆ, ಮೂಲ ಕಳೆದುಹೋದಾಗ ಅಥವಾ ಇತರ ಕಡೆಯವರ ಬಳಿ ಇರುವಾಗ ಮಾತ್ರ ನಿರ್ದಿಷ್ಟ ಸಂದರ್ಭಗಳಲ್ಲಿ ಅನುಮತಿಸಲಾಗುತ್ತದೆ.',
  'leading-question':
    'ತನ್ನ ಸ್ವಂತ ಉತ್ತರವನ್ನು ಸೂಚಿಸುವ ಅಥವಾ ಸುಳಿವು ನೀಡುವ, ಅಥವಾ ಇನ್ನೂ ಸ್ಥಾಪಿಸದ ಸಂಗತಿಯನ್ನು ಊಹಿಸುವ ಪ್ರಶ್ನೆ. ಪ್ರಾಸ್ತಾವಿಕ ಅಥವಾ ವಿವಾದರಹಿತ ವಿಷಯಗಳ ಹೊರತು, ಮುಖ್ಯ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಲೀಡಿಂಗ್ ಪ್ರಶ್ನೆಗಳನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಅನುಮತಿಸಲಾಗುವುದಿಲ್ಲ, ಆದರೆ ಅಡ್ಡ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಅನುಮತಿಸಲಾಗುತ್ತದೆ.',
  'test-identification-parade':
    'ಸಾಮಾನ್ಯವಾಗಿ ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್ ನಡೆಸುವ ಕಾರ್ಯವಿಧಾನ, ಇದರಲ್ಲಿ ಸಾಕ್ಷಿಯನ್ನು ಇತರ ಜನರ ಗುಂಪಿನಿಂದ ಒಬ್ಬ ಸಂಶಯಿತನನ್ನು ಗುರುತಿಸಲು ಕೇಳಲಾಗುತ್ತದೆ, ಅಪರಾಧದಲ್ಲಿ ಒಳಗೊಂಡ ವ್ಯಕ್ತಿಯಾಗಿ ಸಾಕ್ಷಿ ಅವರನ್ನು ಸರಿಯಾಗಿ ಗುರುತಿಸಬಹುದೇ ಎಂದು ಪರೀಕ್ಷಿಸಲು.',
  'dying-declaration':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿ ಸಾಯುವ ಮೊದಲು ನೀಡುವ, ಅವರ ಮರಣದ ಕಾರಣ ಅಥವಾ ಅದಕ್ಕೆ ಕಾರಣವಾದ ಸನ್ನಿವೇಶಗಳ ಬಗ್ಗೆ ಹೇಳಿಕೆ. ಸಾಮಾನ್ಯ ಹಿಯರ್‌ಸೇ ವಿರುದ್ಧದ ನಿಯಮಕ್ಕೆ ವಿನಾಯಿತಿಯಾಗಿ ನ್ಯಾಯಾಲಯಗಳು ಸಾಯುವ ಹೇಳಿಕೆಯನ್ನು ಪರಿಗಣಿಸುತ್ತವೆ ಮತ್ತು ಕೇವಲ ವಿಶ್ವಾಸಾರ್ಹ ಹೇಳಿಕೆಯ ಆಧಾರದ ಮೇಲೆ ಆರೋಪಿಗೆ ಶಿಕ್ಷೆ ವಿಧಿಸಬಹುದು.',
  'confession':
    'ಆರೋಪಿ ವ್ಯಕ್ತಿ ಒಂದು ಅಪರಾಧದಲ್ಲಿ ಸ್ವಂತ ತಪ್ಪನ್ನು ಒಪ್ಪಿಕೊಳ್ಳುವ ಹೇಳಿಕೆ, ಸಿವಿಲ್ ವಿಷಯದಲ್ಲಿ ಪಕ್ಷ ತಮ್ಮ ಸ್ವಂತ ಹಿತಾಸಕ್ತಿಗೆ ವಿರುದ್ಧವಾದ ಸಂಗತಿಯನ್ನು ಒಪ್ಪಿಕೊಳ್ಳುವ ಒಪ್ಪಿಗೆಗಿಂತ ಭಿನ್ನ. ಭಾರತೀಯ ಸಾಕ್ಷ್ಯ ಕಾಯಿದೆಯನ್ನು ಬದಲಿಸಿದ ಸಾಕ್ಷ್ಯ ಕಾನೂನು, ಭಾರತೀಯ ಸಾಕ್ಷ್ಯ ಅಧಿನಿಯಮ, 2023 (BSA) ಅಡಿಯಲ್ಲಿ, ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್ ಮುಂದೆ ಮಾಡಿದ್ದಕ್ಕೆ ವಿರುದ್ಧವಾಗಿ, ಕೇವಲ ಪೊಲೀಸರಿಗೆ ಮಾಡಿದ ಕಬೂಲಿಯನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ವಿಚಾರಣೆಯಲ್ಲಿ ಆರೋಪಿಯ ವಿರುದ್ಧ ಬಳಸಲಾಗುವುದಿಲ್ಲ.',
  'interested-witness':
    'ಪ್ರಕರಣದ ಫಲಿತಾಂಶದಲ್ಲಿ ಕೆಲವು ವ್ಯಕ್ತಿಗತ ಪಾಲು ಹೊಂದಿರುವ ಸಾಕ್ಷಿ, ಉದಾಹರಣೆಗೆ ಪಕ್ಷದ ಸಮೀಪ ಸಂಬಂಧಿ, ಕೇವಲ ಆ ಸಂಬಂಧದ ಕಾರಣ ತಿರಸ್ಕರಿಸುವ ಬದಲು ನ್ಯಾಯಾಲಯಗಳು ಹೆಚ್ಚಿನ ಜಾಗ್ರತೆಯಿಂದ ಅವರ ಸಾಕ್ಷ್ಯವನ್ನು ಪರೀಕ್ಷಿಸುತ್ತವೆ.',
  'proof-of-document':
    'ಸಾಮಾನ್ಯವಾಗಿ ಸಾಕ್ಷಿಯ ಮೂಲಕ, ಒಂದು ದಾಖಲೆ ನಿಜವಾಗಿದೆ ಮತ್ತು ಅದನ್ನು ಹೇಳಿದಂತೆ ಕಾರ್ಯಗತಗೊಳಿಸಲಾಗಿದೆ ಅಥವಾ ರಚಿಸಲಾಗಿದೆ ಎಂದು ಸ್ಥಾಪಿಸುವ ಪ್ರಕ್ರಿಯೆ, ನ್ಯಾಯಾಲಯ ಅದರ ವಿಷಯಗಳನ್ನು ಅವಲಂಬಿಸುವ ಮೊದಲು. ಕೇವಲ ದಾಖಲೆಯನ್ನು ನ್ಯಾಯಾಲಯದ ದಾಖಲೆಯ ಮೇಲೆ ಇಡುವುದರಿಂದ ಅದನ್ನು ಸ್ವತಃ ಸಾಬೀತುಪಡಿಸುವುದಿಲ್ಲ.',
  'chain-of-custody':
    'ಆಯುಧ ಅಥವಾ ಫೊರೆನ್ಸಿಕ್ ಸ್ಯಾಂಪಲ್‌ನಂತಹ ದೈಹಿಕ ವಸ್ತು ಅಥವಾ ಸ್ಯಾಂಪಲ್‌ನ್ನು ಅದನ್ನು ವಶಪಡಿಸಿಕೊಂಡ ಸಮಯದಿಂದ ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಹಾಜರುಪಡಿಸುವವರೆಗೆ ಯಾರು ನಿರ್ವಹಿಸಿದ್ದಾರೆ ಅಥವಾ ನಿಯಂತ್ರಣ ಹೊಂದಿದ್ದಾರೆ ಎಂಬುದರ ದಾಖಲಿತ ದಾಖಲೆ. ಮುರಿದ ಅಥವಾ ಸರಿಯಾಗಿ ದಾಖಲಿಸದ ಕಸ್ಟಡಿ ಸರಪಳಿ, ಪ್ರಯೋಗಾಲಯದಲ್ಲಿ ಪರೀಕ್ಷಿಸಲಾದ ಸ್ಯಾಂಪಲ್ ಮೂಲತಃ ವಶಪಡಿಸಿಕೊಂಡದ್ದೇ ಎಂಬ ಬಗ್ಗೆ ಸಂಶಯ ಹುಟ್ಟಿಸಬಹುದು.',
  'first-information-report':
    'ಪೊಲೀಸರು ಒಂದು ಅರಿಯಬಹುದಾದ ಅಪರಾಧದ ಬಗ್ಗೆ ಮೊದಲು ಮಾಹಿತಿ ಪಡೆದಾಗ ತಯಾರಿಸುವ ಲಿಖಿತ ದಾಖಲೆ, ಕ್ರಿಮಿನಲ್ ತನಿಖೆಯ ಔಪಚಾರಿಕ ಆರಂಭವನ್ನು ಗುರುತಿಸುತ್ತದೆ. ಇದನ್ನು CrPC ಬದಲಿಸಿದ ಸಂಹಿತೆಯಾದ ಭಾರತೀಯ ನಾಗರಿಕ ಸುರಕ್ಷಾ ಸಂಹಿತಾ, 2023 (BNSS) ಅಡಿಯಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ.',
  'chargesheet':
    'ತನಿಖೆಯ ಕೊನೆಯಲ್ಲಿ ಪೊಲೀಸರು ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್‌ಗೆ ಸಲ್ಲಿಸುವ ವರದಿ, ಸಂಗ್ರಹಿಸಿದ ಸಾಕ್ಷ್ಯವನ್ನು ವಿವರಿಸುತ್ತದೆ ಮತ್ತು, ಅದು ಒಂದು ಪ್ರಕರಣವನ್ನು ಬೆಂಬಲಿಸಿದರೆ, ವಿಚಾರಣೆಗೊಳಗಾಗಬೇಕಾದ ಆರೋಪಿ ವ್ಯಕ್ತಿಗಳನ್ನು ಹೆಸರಿಸುತ್ತದೆ. CrPC ಬದಲಿಸಿದ ಸಂಹಿತೆಯಾದ BNSS ಅಡಿಯಲ್ಲಿ, ಇದನ್ನು ಔಪಚಾರಿಕವಾಗಿ ಪೊಲೀಸ್ ವರದಿ ಅಥವಾ ಅಂತಿಮ ವರದಿ ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ.',
  'bail':
    'ಒಂದು ಅಪರಾಧದ ಆರೋಪಿ ವ್ಯಕ್ತಿಯನ್ನು ಕಸ್ಟಡಿಯಿಂದ ಬಿಡುಗಡೆ ಮಾಡುವುದು, ಸಾಮಾನ್ಯವಾಗಿ ಬಾಂಡ್ ಅಥವಾ ಜಾಮೀನಿನಂತಹ ಪರಿಸ್ಥಿತಿಗಳ ಮೇಲೆ, ವಿಚಾರಣೆ ಅಥವಾ ಮುಂದಿನ ಪ್ರಕ್ರಿಯೆಗಳು ಬಾಕಿ ಇರುವಾಗ. ಇದು ನಿರಪರಾಧ ಮುಕ್ತಿ ಅಥವಾ ಮುಗ್ಧತೆಯ ಅಂತಿಮ ತೀರ್ಮಾನ ಅಲ್ಲ, ಕೇವಲ ಪ್ರಕರಣ ಮುಂದುವರಿಯುತ್ತಿರುವಾಗ ಬಂಧನದಿಂದ ಬಿಡುಗಡೆ.',
  'anticipatory-bail':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿಯನ್ನು ವಾಸ್ತವವಾಗಿ ಬಂಧಿಸುವ ಮೊದಲೇ ಮುಂಚಿತವಾಗಿ ನೀಡಿದ ನ್ಯಾಯಾಲಯದ ಆದೇಶ, ಒಂದು ನಿರ್ದಿಷ್ಟ ಆರೋಪಕ್ಕಾಗಿ ಬಂಧಿಸಿದರೆ ಅವರನ್ನು ಜಾಮೀನಿನ ಮೇಲೆ ಬಿಡುಗಡೆ ಮಾಡಬೇಕೆಂದು ನಿರ್ದೇಶಿಸುತ್ತದೆ. ಸುಳ್ಳು ಅಥವಾ ಅನ್ಯಾಯವಾಗಿ ಬಂಧಿಸಬಹುದು ಎಂದು ನಂಬಲು ಕಾರಣವಿರುವ ವ್ಯಕ್ತಿಯನ್ನು ರಕ್ಷಿಸಲು ಇದನ್ನು ಉದ್ದೇಶಿಸಲಾಗಿದೆ.',
  'cognizable-offence':
    'ಸಾಮಾನ್ಯವಾಗಿ ಹೆಚ್ಚು ಗಂಭೀರವಾದ ಅಪರಾಧದ ವರ್ಗ, ಅಲ್ಲಿ ಪೊಲೀಸರು ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್‌ನಿಂದ ಮುಂಚಿತ ಅನುಮತಿ ಬೇಕಾಗದೆ FIR ದಾಖಲಿಸಿ ತನಿಖೆ ಆರಂಭಿಸಬಹುದು ಅಥವಾ ಆರೋಪಿಯನ್ನು ಬಂಧಿಸಬಹುದು.',
  'non-cognizable-offence':
    'ಸಾಮಾನ್ಯವಾಗಿ ಕಡಿಮೆ ಗಂಭೀರವಾದ ಅಪರಾಧದ ವರ್ಗ, ಅಲ್ಲಿ ಪೊಲೀಸರು ಮೊದಲು ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್‌ನಿಂದ ಅನುಮತಿ ಪಡೆಯದೆ ತನಿಖೆ ಮಾಡಲು ಅಥವಾ ಆರೋಪಿಯನ್ನು ಬಂಧಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಇಂತಹ ಪ್ರಕರಣದ ದೂರುದಾರ ಸಾಮಾನ್ಯವಾಗಿ ಕೇವಲ ಪೊಲೀಸ್ ಠಾಣೆಯಲ್ಲಿ FIR ದಾಖಲಿಸುವ ಬದಲು ನೇರವಾಗಿ ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್‌ರನ್ನು ಸಂಪರ್ಕಿಸಬೇಕು.',
  'summons':
    'ಒಂದು ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕದಂದು ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಹಾಜರಾಗಲು ಒಬ್ಬ ವ್ಯಕ್ತಿಗೆ ನಿರ್ದೇಶಿಸುವ ಔಪಚಾರಿಕ ನ್ಯಾಯಾಲಯದ ಆದೇಶ, ಆ ವ್ಯಕ್ತಿಯನ್ನು ಬಂಧಿಸುವುದು ಅಗತ್ಯವೆಂದು ನ್ಯಾಯಾಲಯ ಪರಿಗಣಿಸದಿದ್ದಾಗ ಬಳಸಲಾಗುತ್ತದೆ. ಸಮನ್ಸ್ ಅನ್ನು ಅಲಕ್ಷಿಸುವುದರಿಂದ, ವಾರಂಟ್ ಜಾರಿ ಮಾಡುವುದು ಸೇರಿದಂತೆ, ನ್ಯಾಯಾಲಯ ವಿಷಯವನ್ನು ಉಲ್ಬಣಗೊಳಿಸಬಹುದು.',
  'warrant':
    'ಪೊಲೀಸರಿಗೆ ಒಬ್ಬ ವ್ಯಕ್ತಿಯನ್ನು ಬಂಧಿಸಿ ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಹಾಜರುಪಡಿಸಲು ನಿರ್ದೇಶಿಸುವ, ನ್ಯಾಯಾಲಯ ನೀಡುವ ಲಿಖಿತ ಆದೇಶ. "ಜಾಮೀನು ಸಾಧ್ಯ" ವಾರಂಟ್ ವ್ಯಕ್ತಿಯನ್ನು ಬಂಧಿಸಿದ ಕೂಡಲೇ ಜಾಮೀನಿನ ಮೇಲೆ ಬಿಡುಗಡೆ ಮಾಡಲು ಅನುಮತಿಸುತ್ತದೆ, ಆದರೆ "ಜಾಮೀನು ಅಸಾಧ್ಯ" ವಾರಂಟ್, ಮೊದಲು ಅವರನ್ನು ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಹಾಜರುಪಡಿಸಬೇಕು.',
  'remand':
    'ಬಂಧಿಸಿದ ವ್ಯಕ್ತಿಯನ್ನು, ಹೆಚ್ಚಿನ ತನಿಖೆಗಾಗಿ ಪೊಲೀಸರೊಂದಿಗೆ ಅಥವಾ ನ್ಯಾಯಾಂಗ ಕಸ್ಟಡಿಗೆ, ತನಿಖೆ ಅಥವಾ ವಿಚಾರಣೆ ಮುಂದುವರಿಯುತ್ತಿರುವಾಗ ಸೀಮಿತ ಅವಧಿಗೆ ಕಸ್ಟಡಿಗೆ ಕಳುಹಿಸುವ ಆದೇಶ.',
  'discharge-criminal':
    'ಆರೋಪಿ ವ್ಯಕ್ತಿಯನ್ನು ವಿಚಾರಣೆಗೆ ಮೊದಲೇ ಕ್ರಿಮಿನಲ್ ಪ್ರಕರಣದಿಂದ ಬಿಡುಗಡೆ ಮಾಡುವ ಆದೇಶ, ಅವರ ವಿರುದ್ಧ ಮುಂದುವರಿಯಲು ಮೇಲ್ನೋಟಕ್ಕೆ ಸಹ ಸಾಕಷ್ಟು ಸಾಕ್ಷ್ಯವಿಲ್ಲ ಎಂದು ನ್ಯಾಯಾಲಯ ಕಂಡುಕೊಂಡಾಗ. ಡಿಸ್ಚಾರ್ಜ್, ಸಾಕ್ಷ್ಯದ ಮೇಲೆ ಪೂರ್ಣ ವಿಚಾರಣೆಯ ನಂತರ ಮಾತ್ರ ಬರುವ ನಿರಪರಾಧ ಮುಕ್ತಿಗಿಂತ ಭಿನ್ನ.',
  'acquittal':
    'ಪೂರ್ಣ ವಿಚಾರಣೆಯ ನಂತರ, ಆರೋಪಿ ಆರೋಪಿಸಲಾದ ಅಪರಾಧಕ್ಕೆ ದೋಷಿಯಲ್ಲ ಎಂಬ ನ್ಯಾಯಾಲಯದ ಅಂತಿಮ ತೀರ್ಮಾನ. ಇದು ಆರೋಪಿಯನ್ನು ಆ ಆರೋಪದಿಂದ ಮುಕ್ತಗೊಳಿಸುತ್ತದೆ ಮತ್ತು, ಸೀಮಿತ ವಿನಾಯಿತಿಗಳ ಹೊರತು, ಅದೇ ಅಪರಾಧಕ್ಕೆ ಅವರನ್ನು ಮತ್ತೆ ವಿಚಾರಣೆಗೆ ಒಳಪಡಿಸಲಾಗುವುದಿಲ್ಲ.',
  'complainant':
    'ಒಂದು ಅಪರಾಧ ನಡೆದಿದೆ ಎಂದು ಆರೋಪಿಸಿ ನ್ಯಾಯಾಲಯ ಅಥವಾ ಪೊಲೀಸ್ ಠಾಣೆಗೆ ಕ್ರಿಮಿನಲ್ ದೂರು ತರುವ ವ್ಯಕ್ತಿ, ಆರೋಪ ಮಾಡಲಾದ ಆರೋಪಿಗಿಂತ ಭಿನ್ನ.',
  'accused':
    'ಕ್ರಿಮಿನಲ್ ಆರೋಪ ಮಾಡಲಾದ ಮತ್ತು ಒಂದು ಅಪರಾಧಕ್ಕಾಗಿ ತನಿಖೆ, ಆರೋಪ, ಅಥವಾ ವಿಚಾರಣೆಗೆ ಒಳಪಡಿಸಲಾಗುತ್ತಿರುವ ವ್ಯಕ್ತಿ. ನ್ಯಾಯಾಲಯ ದೋಷಿ ಎಂದು ಸಾಬೀತುಪಡಿಸುವವರೆಗೆ ಆರೋಪಿಯನ್ನು ನಿರಪರಾಧಿ ಎಂದು ಭಾವಿಸಲಾಗುತ್ತದೆ.',
  'investigating-officer':
    'ಸಾಕ್ಷ್ಯ ಸಂಗ್ರಹಿಸುವುದು, ಸಾಕ್ಷಿಗಳ ಹೇಳಿಕೆ ದಾಖಲಿಸುವುದು, ಮತ್ತು ಅಂತಿಮವಾಗಿ ಚಾರ್ಜ್‌ಶೀಟ್ ದಾಖಲಿಸುವುದು ಅಥವಾ ಪ್ರಕರಣ ಮುಚ್ಚುವುದು ಸೇರಿದಂತೆ, ಕ್ರಿಮಿನಲ್ ಪ್ರಕರಣ ತನಿಖೆ ಮಾಡುವ ಹೊಣೆ ಹೊತ್ತ ಪೊಲೀಸ್ ಅಧಿಕಾರಿ.',
  'cognizance':
    'ಒಂದು ದೂರು, ಪೊಲೀಸ್ ವರದಿ, ಅಥವಾ ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್‌ರ ಸ್ವಂತ ಮಾಹಿತಿಯ ಆಧಾರದ ಮೇಲೆ, ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್ ಒಂದು ಅಪರಾಧವನ್ನು ನ್ಯಾಯಾಂಗ ಗಮನಕ್ಕೆ ತೆಗೆದುಕೊಂಡು ಪ್ರಕರಣ ಮುಂದುವರಿಸಲು ನಿರ್ಧರಿಸುವ ಔಪಚಾರಿಕ ಹಂತ. ಕಾಗ್ನಿಜನ್ಸ್ ತೆಗೆದುಕೊಳ್ಳುವವರೆಗೆ, ಒಂದು ವಿಷಯ ಔಪಚಾರಿಕವಾಗಿ ಆ ನ್ಯಾಯಾಲಯದ ಮುಂದಿನ ಪ್ರಕರಣವಾಗಿಲ್ಲ.',
  'framing-of-charge':
    'ಈವರೆಗಿನ ಲಭ್ಯ ಸಾಕ್ಷ್ಯದ ಆಧಾರದ ಮೇಲೆ, ಆರೋಪಿ ಮಾಡಿದ ಆರೋಪಿಸಲಾದ ನಿರ್ದಿಷ್ಟ ಅಪರಾಧ ಅಥವಾ ಅಪರಾಧಗಳನ್ನು ನ್ಯಾಯಾಲಯ ಲಿಖಿತವಾಗಿ ಔಪಚಾರಿಕವಾಗಿ ವಿವರಿಸುವ ಹಂತ. ವಿಚಾರಣೆ ಈ ಹೊಣೆಗೊಂಡ ಆರೋಪಗಳ ಆಧಾರದ ಮೇಲೆ ಮುಂದುವರಿಯುತ್ತದೆ, ಮತ್ತು ಆರೋಪಿಯನ್ನು ಅವುಗಳಿಗೆ ದೋಷಿ ಅಥವಾ ದೋಷಿಯಲ್ಲ ಎಂದು ಪ್ಲೀ ಮಾಡಲು ಕೇಳಲಾಗುತ್ತದೆ.',
  'compounding-of-offence':
    'ದೂರುದಾರ ಮತ್ತು ಆರೋಪಿ ಕೆಲವು ಕ್ರಿಮಿನಲ್ ಪ್ರಕರಣಗಳನ್ನು ತಮ್ಮ ನಡುವೆ ಬಗೆಹರಿಸುವ ಪ್ರಕ್ರಿಯೆ, ಅಗತ್ಯವಿದ್ದಲ್ಲಿ ನ್ಯಾಯಾಲಯದ ಅನುಮತಿಯೊಂದಿಗೆ, ಪೂರ್ಣ ವಿಚಾರಣೆ ಇಲ್ಲದೆ ಪ್ರಕರಣವನ್ನು ಅಂತ್ಯಗೊಳಿಸುತ್ತದೆ. ಕಾನೂನು ನಿರ್ದಿಷ್ಟವಾಗಿ ಅನುಮತಿಸುವ ಅಪರಾಧಗಳನ್ನು ಮಾತ್ರ ಈ ರೀತಿ ಬಗೆಹರಿಸಬಹುದು; ಗಂಭೀರ ಅಪರಾಧಗಳನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಮಾಡಲಾಗುವುದಿಲ್ಲ.',
  'zero-fir':
    'ಅರಿಯಬಹುದಾದ ಅಪರಾಧಕ್ಕಾಗಿ ಯಾವುದೇ ಪೊಲೀಸ್ ಠಾಣೆ ದಾಖಲಿಸುವ FIR, ಆ ಠಾಣೆಗೆ ಅಪರಾಧ ನಡೆದ ಸ್ಥಳದ ಮೇಲೆ ಪ್ರಾದೇಶಿಕ ಅಧಿಕಾರವ್ಯಾಪ್ತಿ ಇಲ್ಲದಿದ್ದರೂ. ಇದನ್ನು ನಂತರ ತನಿಖೆಗಾಗಿ ಸರಿಯಾದ ಅಧಿಕಾರವ್ಯಾಪ್ತಿ ಹೊಂದಿರುವ ಠಾಣೆಗೆ ವರ್ಗಾಯಿಸಲಾಗುತ್ತದೆ.',
  'quashing-of-fir':
    'ಹೈಕೋರ್ಟ್‌ನ ಅಂತರ್ಗತ ಅಧಿಕಾರಗಳನ್ನು ಬಳಸಿ, FIR ಅಥವಾ ನಡೆಯುತ್ತಿರುವ ಕ್ರಿಮಿನಲ್ ಪ್ರಕ್ರಿಯೆಗಳನ್ನು ರದ್ದುಗೊಳಿಸಬೇಕೆಂದು ಕೋರುವ ಮನವಿ, ಸಾಮಾನ್ಯವಾಗಿ ಅವು ಆಧಾರರಹಿತ, ಕಾನೂನು ಪ್ರಕ್ರಿಯೆಯ ದುರ್ಬಳಕೆ, ಅಥವಾ ವಿವಾದ ಈಗಾಗಲೇ ನಿಜವಾಗಿ ಪಕ್ಷಗಳ ನಡುವೆ ಬಗೆಹರಿದಿದೆ ಎಂಬ ಕಾರಣದ ಮೇಲೆ.',
  'plea-bargaining':
    'ಭಾರತೀಯ ನಾಗರಿಕ ಸುರಕ್ಷಾ ಸಂಹಿತಾ, 2023 (BNSS) ಅಡಿಯಲ್ಲಿನ ಪ್ರಕ್ರಿಯೆ, ಇದರಲ್ಲಿ ಆರೋಪಿ ದೋಷಿ ಎಂದು ಪ್ಲೀ ಮಾಡುವುದಕ್ಕೆ ಬದಲಾಗಿ ಕಡಿಮೆ ಶಿಕ್ಷೆಗೆ ಸಂಧಾನ ಮಾಡಲು ಅರ್ಜಿ ಹಾಕಬಹುದು, ಕೆಲವು ವರ್ಗದ ಅಪರಾಧಗಳಿಗೆ ಮಾತ್ರ ಲಭ್ಯ.',
  'default-bail':
    'ಪೊಲೀಸರು ತನಿಖೆ ಪೂರ್ಣಗೊಳಿಸಿ ಭಾರತೀಯ ನಾಗರಿಕ ಸುರಕ್ಷಾ ಸಂಹಿತಾ, 2023 (BNSS) ಅಡಿಯಲ್ಲಿ ಅನುಮತಿಸಿದ ಸಮಯದೊಳಗೆ ಚಾರ್ಜ್‌ಶೀಟ್ ದಾಖಲಿಸಲು ವಿಫಲರಾದಾಗ, ಆರೋಪದ ಗಂಭೀರತೆ ಏನೇ ಇರಲಿ, ಆರೋಪಿ ಹಕ್ಕಾಗಿ ಪಡೆಯುವ ಜಾಮೀನು.',
  'bail-bond':
    'ಜಾಮೀನಿನ ಮೇಲೆ ಬಿಡುಗಡೆಯಾದಾಗ ಆರೋಪಿ ಕಾರ್ಯಗತಗೊಳಿಸುವ ದಾಖಲೆ, ಅಗತ್ಯವಿದ್ದಾಗ ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಹಾಜರಾಗುವುದಾಗಿ ವಾಗ್ದಾನ ಮಾಡುತ್ತದೆ, ಹೆಚ್ಚಾಗಿ ಒಂದು ಅಥವಾ ಹೆಚ್ಚಿನ ಜಾಮೀನುದಾರರೊಂದಿಗೆ, ಅವರು ಆರೋಪಿಯನ್ನು ಹಾಜರುಪಡಿಸಲು ಅಥವಾ ಹಾಜರಾಗಲು ವಿಫಲವಾದರೆ ನಿರ್ದಿಷ್ಟ ಮೊತ್ತವನ್ನು ಕಳೆದುಕೊಳ್ಳಲು ವಾಗ್ದಾನ ಮಾಡುತ್ತಾರೆ.',
  'private-complaint':
    'ಪೊಲೀಸರ ಮೂಲಕ ಬದಲಾಗಿ, ಖಾಸಗಿ ವ್ಯಕ್ತಿ ನೇರವಾಗಿ ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್‌ ಮುಂದೆ ದಾಖಲಿಸುವ ಕ್ರಿಮಿನಲ್ ದೂರು, ಸಾಮಾನ್ಯವಾಗಿ ಅರಿಯಲಾಗದ ಅಪರಾಧಗಳಿಗೆ ಅಥವಾ ಪೊಲೀಸರು ಅರಿಯಬಹುದಾದ ಅಪರಾಧಕ್ಕೆ FIR ದಾಖಲಿಸಲು ನಿರಾಕರಿಸಿದಾಗ ಸಾಮಾನ್ಯವಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ.',
  'proclaimed-offender':
    'ಬಂಧನ ತಪ್ಪಿಸಲು ತಪ್ಪಿಸಿಕೊಂಡಿದ್ದಾರೆ ಅಥವಾ ಅಡಗಿಕೊಂಡಿದ್ದಾರೆ ಎಂದು ನ್ಯಾಯಾಲಯ ಔಪಚಾರಿಕವಾಗಿ ಘೋಷಿಸಿದ ವ್ಯಕ್ತಿ, ಇದರ ನಂತರ ನ್ಯಾಯಾಲಯ ಅವರ ಆಸ್ತಿಯನ್ನು ಜೋಡಿಸುವುದು ಸೇರಿದಂತೆ, ಅವರು ಹಾಜರಾಗುವವರೆಗೆ ಅವರ ವಿರುದ್ಧ ಹೆಚ್ಚಿನ ಕ್ರಮ ಕೈಗೊಳ್ಳಬಹುದು.',
  'conviction':
    'ವಿಚಾರಣೆಯ ನಂತರ, ಆರೋಪಿ ಆರೋಪಿಸಲಾದ ಅಪರಾಧಕ್ಕೆ ದೋಷಿ ಎಂಬ ನ್ಯಾಯಾಲಯದ ಅಂತಿಮ ತೀರ್ಮಾನ, ನ್ಯಾಯಾಲಯ ಶಿಕ್ಷೆ ವಿಧಿಸುವುದಕ್ಕೆ ಕಾರಣವಾಗುತ್ತದೆ. ಇದು ನಿರಪರಾಧ ಮುಕ್ತಿಗೆ ವಿರುದ್ಧ ಫಲಿತಾಂಶ.',
  'sentence':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿಯನ್ನು ಅಪರಾಧಕ್ಕೆ ದೋಷಿ ಎಂದು ಕಂಡುಕೊಂಡ ನಂತರ ನ್ಯಾಯಾಲಯ ವಿಧಿಸುವ ಶಿಕ್ಷೆ, ಉದಾಹರಣೆಗೆ ಜೈಲುವಾಸ ಅಥವಾ ದಂಡ. ಶಿಕ್ಷೆ ವಿಧಿಸುವ ಮೊದಲು, ನ್ಯಾಯಾಲಯಗಳು ಸಾಮಾನ್ಯವಾಗಿ ಸೂಕ್ತ ಶಿಕ್ಷೆಯ ಬಗ್ಗೆ ದೋಷಿ ವ್ಯಕ್ತಿಯನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಆಲಿಸುತ್ತವೆ.',
  'probation':
    'ಜೈಲುವಾಸದ ಶಿಕ್ಷೆಗೆ ಕಳುಹಿಸುವ ಬದಲು, ದೋಷಿ ವ್ಯಕ್ತಿಯನ್ನು ಉತ್ತಮ ನಡವಳಿಕೆಯ ಮೇಲೆ, ನ್ಯಾಯಾಲಯ ನಿಗದಿಪಡಿಸಿದ ಮೇಲ್ವಿಚಾರಣೆ ಮತ್ತು ಪರಿಸ್ಥಿತಿಗಳ ಮೇಲೆ ಬಿಡುಗಡೆ ಮಾಡುವ ಆದೇಶ. ಇದನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಮೊದಲ ಬಾರಿ ಅಪರಾಧಿಗಳಿಗೆ ಅಥವಾ ಕಡಿಮೆ ಗಂಭೀರ ಅಪರಾಧಗಳಿಗೆ ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ.',
  'status-report':
    'ನ್ಯಾಯಾಲಯದ ನಿರ್ದೇಶನದಂತೆ, ಪೊಲೀಸರು ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ದಾಖಲಿಸುವ ವರದಿ, ಪ್ರಕರಣದ ತನಿಖೆಯಲ್ಲಿ ಆಗಿರುವ ಪ್ರಗತಿಯ ಬಗ್ಗೆ ಅದನ್ನು ಅಪ್‌ಡೇಟ್ ಮಾಡುತ್ತದೆ.',
  'closure-report':
    'ತನಿಖೆಯ ಕೊನೆಯಲ್ಲಿ ಪೊಲೀಸರು ದಾಖಲಿಸುವ ವರದಿ, ಹೆಸರಿಸಲಾದ ಸಂಶಯಿತರ ವಿರುದ್ಧ ಯಾವುದೇ ಪ್ರಕರಣ ಇಲ್ಲ ಎಂದು ಹೇಳುತ್ತದೆ, ಮತ್ತು ವಿಷಯ ವಿಚಾರಣೆಗೆ ಮುಂದುವರಿಯಬಾರದು ಎಂದು. ಇದನ್ನು CrPC ಬದಲಿಸಿದ ಸಂಹಿತೆಯಾದ ಭಾರತೀಯ ನಾಗರಿಕ ಸುರಕ್ಷಾ ಸಂಹಿತಾ, 2023 (BNSS) ಅಡಿಯಲ್ಲಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್ ಅದನ್ನು ಸ್ವೀಕರಿಸುವ ಮೊದಲು ದೂರುದಾರರಿಗೆ ಆಲಿಸುವ ಹಕ್ಕಿದೆ.',
  'protest-petition':
    'ಮುಗಿಸಿದ ವರದಿಯನ್ನು ಪ್ರಶ್ನಿಸುತ್ತಾ, ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್ ಅದನ್ನು ಸ್ವೀಕರಿಸಬಾರದು ಮತ್ತು ಬದಲಿಗೆ ಅಪರಾಧವನ್ನು ಗಮನಿಸಿ ಪ್ರಕರಣ ಮುಂದುವರಿಸಬೇಕೆಂದು ಕೋರಿ, ದೂರುದಾರ ಮ್ಯಾಜಿಸ್ಟ್ರೇಟ್ ಮುಂದೆ ದಾಖಲಿಸುವ ಆಕ್ಷೇಪಣೆ.',
  'temporary-injunction':
    'ಮುಖ್ಯ ಪ್ರಕರಣ ಇನ್ನೂ ನಿರ್ಧರಿಸುತ್ತಿರುವಾಗ, ಒಂದು ವಿವಾದಿತ ಆಸ್ತಿಯನ್ನು ಮಾರಾಟ ಮಾಡುವಂತಹ ನಿರ್ದಿಷ್ಟ ಕ್ರಮವನ್ನು ಒಂದು ಪಕ್ಷ ಮಾಡುವುದನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ತಡೆಯುವ ನ್ಯಾಯಾಲಯದ ಆದೇಶ. ಅಂತಿಮ ನಿರ್ಧಾರ, ಈ ಮಧ್ಯೆ ತೆಗೆದುಕೊಂಡ ಕ್ರಮಗಳಿಂದ ಅರ್ಥಹೀನವಾಗದಂತೆ ಪರಿಸ್ಥಿತಿಯನ್ನು ಇದ್ದಂತೆ ಸಂರಕ್ಷಿಸಲು ಉದ್ದೇಶಿಸಲಾಗಿದೆ.',
  'permanent-injunction':
    'ಪ್ರಕರಣದ ಮುಕ್ತಾಯದಲ್ಲಿ ನೀಡಲಾದ ಅಂತಿಮ ನ್ಯಾಯಾಲಯದ ಆದೇಶ, ಒಂದು ಪಕ್ಷ ನಿರ್ದಿಷ್ಟ ಕ್ರಮ ಮಾಡುವುದನ್ನು ಶಾಶ್ವತವಾಗಿ ತಡೆಯುತ್ತದೆ. ತಾತ್ಕಾಲಿಕ ತಡೆಯಾಜ್ಞೆಗಿಂತ ಭಿನ್ನವಾಗಿ, ಇದು ತಾತ್ಕಾಲಿಕ ಕ್ರಮವಲ್ಲ ಆದರೆ ಪ್ರಕರಣದ ಮೇಲಿನ ನ್ಯಾಯಾಲಯದ ಅಂತಿಮ ನಿರ್ಧಾರದ ಭಾಗ.',
  'specific-performance':
    'ಒಪ್ಪಂದ ಮುರಿದಿದ್ದಕ್ಕೆ ಕೇವಲ ಪರಿಹಾರ ಪಾವತಿಸುವ ಬದಲು, ಒಂದು ಪಕ್ಷ ಒಪ್ಪಂದದ ಅಡಿಯಲ್ಲಿ ತಮ್ಮ ಕಡ್ಡಾಯಗಳನ್ನು ವಾಸ್ತವವಾಗಿ ಪೂರೈಸಲು ನಿರ್ದೇಶಿಸುವ ನ್ಯಾಯಾಲಯದ ಆದೇಶ, ಉದಾಹರಣೆಗೆ ನಿರ್ದಿಷ್ಟ ಆಸ್ತಿಯ ಮಾರಾಟ ಪೂರ್ಣಗೊಳಿಸುವುದು. ಹಣ ಮಾತ್ರ ಉಲ್ಲಂಘನೆಗೆ ಸಮರ್ಪಕವಾಗಿ ಸರಿದೂಗಿಸದಿದ್ದಾಗ ಮುಖ್ಯವಾಗಿ ನ್ಯಾಯಾಲಯಗಳು ಈ ಪರಿಹಾರ ನೀಡುತ್ತವೆ.',
  'damages':
    'ಒಪ್ಪಂದ ಉಲ್ಲಂಘನೆ ಅಥವಾ ಅಪಕೃತ್ಯದಂತಹ ತಪ್ಪಿನಿಂದ ಉಂಟಾದ ನಷ್ಟ ಅಥವಾ ಹಾನಿಗೆ ಪರಿಹಾರವಾಗಿ, ಒಂದು ಪಕ್ಷ ಇನ್ನೊಂದಕ್ಕೆ ಪಾವತಿಸಬೇಕೆಂದು ನ್ಯಾಯಾಲಯ ಆದೇಶಿಸುವ ಹಣದ ಮೊತ್ತ. ತಪ್ಪು ಸಂಭವಿಸಿರದಿದ್ದರೆ ಇರುತ್ತಿದ್ದ ಸ್ಥಾನದಲ್ಲಿ, ಹಣದಿಂದ ಸಾಧ್ಯವಾದ ಮಟ್ಟಿಗೆ, ನಷ್ಟಪಟ್ಟ ಪಕ್ಷವನ್ನು ಇಡಲು ಈ ಮೊತ್ತ ಉದ್ದೇಶಿಸಲಾಗಿದೆ.',
  'preliminary-decree':
    'ಪಕ್ಷಗಳ ಹಕ್ಕುಗಳನ್ನು ಒಂದು ವಿಷಯದ ಮೇಲೆ ನಿರ್ಧರಿಸುವ ಆದರೆ ಪ್ರಕರಣವನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಮುಚ್ಚುವ ಮೊದಲು ಲೆಕ್ಕಪರಿಶೋಧನೆ ಅಥವಾ ಆಸ್ತಿ ವಿಭಜನೆಯಂತಹ ಕೆಲವು ಮುಂದಿನ ಹಂತಗಳನ್ನು ಬಿಡುವ ಡಿಕ್ರಿ. ಆ ಉಳಿದ ಹಂತಗಳು ಮುಗಿದ ನಂತರ ಅಂತಿಮ ಡಿಕ್ರಿ ಅನುಸರಿಸುತ್ತದೆ.',
  'final-decree':
    'ಪ್ರಕರಣವನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಇತ್ಯರ್ಥಗೊಳಿಸುವ ಡಿಕ್ರಿ, ನೇರವಾಗಿ ಅಥವಾ ಪ್ರಾಥಮಿಕ ಡಿಕ್ರಿಯ ನಂತರ, ಆಸ್ತಿಯ ನಿಖರ ವಿಭಜನೆಯಂತಹ ಎಲ್ಲಾ ಉಳಿದ ಪ್ರಶ್ನೆಗಳನ್ನು ಪರಿಹರಿಸಿದ ನಂತರ ನೀಡಲಾಗುತ್ತದೆ.',
  'execution-of-decree':
    'ಪ್ರಕರಣ ಗೆದ್ದ ಪಕ್ಷ, ನ್ಯಾಯಾಲಯದ ಡಿಕ್ರಿಯನ್ನು ವಾಸ್ತವವಾಗಿ ಜಾರಿಗೊಳಿಸುವ ಕಾನೂನು ಪ್ರಕ್ರಿಯೆ, ಉದಾಹರಣೆಗೆ ಸೋತ ಪಕ್ಷದ ಆಸ್ತಿಯನ್ನು ವಶಪಡಿಸುವ ಅಥವಾ ಬಾಕಿ ಇರುವ ಹಣ ವಸೂಲಿ ಮಾಡುವ ಮೂಲಕ. ಪ್ರಕರಣ ಗೆಲ್ಲುವುದರಿಂದ ಪರಿಹಾರ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಲಭ್ಯವಾಗುವುದಿಲ್ಲ; ಅದನ್ನು ಪ್ರಾಕ್ಟೀಸ್‌ನಲ್ಲಿ ಜಾರಿಗೊಳಿಸಲು ಜಾರಿ ಪ್ರಕ್ರಿಯೆಗಳು ಹೆಚ್ಚಾಗಿ ಬೇಕಾಗುತ್ತವೆ.',
  'review-civil':
    'ತೀರ್ಪು ಅಥವಾ ಆದೇಶ ನೀಡಿದ ಅದೇ ನ್ಯಾಯಾಲಯಕ್ಕೆ ಮಾಡಿದ ಮನವಿ, ಸ್ವಂತ ನಿರ್ಧಾರವನ್ನು ಮರುಪರಿಶೀಲಿಸಬೇಕೆಂದು ಕೋರುತ್ತದೆ, ಸಾಮಾನ್ಯವಾಗಿ ದಾಖಲೆಯಲ್ಲಿ ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣುವ ಸಂಗತಿ ಅಥವಾ ಕಾನೂನು ದೋಷ, ಅಥವಾ ಹೊಸದಾಗಿ ಕಂಡುಬಂದ ಸಾಕ್ಷ್ಯದ ಕಾರಣ. ಇದು ಉನ್ನತ ನ್ಯಾಯಾಲಯ ಆಲಿಸುವ ಮೇಲ್ಮನವಿಗಿಂತ ಮತ್ತು ಕೆಳ ನ್ಯಾಯಾಲಯ ಅಧಿಕಾರವ್ಯಾಪ್ತಿಯೊಳಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸಿದೆಯೇ ಎಂದು ಪರೀಕ್ಷಿಸುವ ಮರುಪರಿಶೀಲನೆಗಿಂತ ಕಿರಿದಾಗಿದೆ.',
  'revision-civil':
    'ಒಂದು ಪ್ರಕರಣದಲ್ಲಿ ಕೆಳ ನ್ಯಾಯಾಲಯ ತನ್ನ ಅಧಿಕಾರವ್ಯಾಪ್ತಿಯೊಳಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸಿದೆಯೇ ಮತ್ತು ಸರಿಯಾದ ಕಾರ್ಯವಿಧಾನ ಅನುಸರಿಸಿದೆಯೇ ಎಂದು ಪರೀಕ್ಷಿಸಲು ಉನ್ನತ ನ್ಯಾಯಾಲಯಕ್ಕೆ ಮಾಡಿದ ಅರ್ಜಿ, ಸಂಗತಿಗಳ ಮೇಲಿನ ಅದರ ಸಂಶೋಧನೆಗಳ ಸರಿಯಾದಿಕೆಯನ್ನು ಮರುಪರಿಶೀಲಿಸುವ ಬದಲು. ನಿರ್ಧಾರದ ಹುರುಳಿನಲ್ಲಿಯೂ ಹೋಗಬಹುದಾದ ಮೇಲ್ಮನವಿಗಿಂತ ಇದರ ವ್ಯಾಪ್ತಿ ಹೆಚ್ಚು ಸೀಮಿತವಾಗಿದೆ.',
  'appeal':
    'ಅದರ ಹುರುಳಿನ ಮೇಲೆ, ಸಂಗತಿ ಮತ್ತು ಕಾನೂನಿನ ಅದರ ಸಂಶೋಧನೆಗಳು ಸೇರಿದಂತೆ, ಕೆಳ ನ್ಯಾಯಾಲಯದ ನಿರ್ಧಾರವನ್ನು ಮರುಪರಿಶೀಲಿಸಿ ಬದಲಾಯಿಸಬೇಕೆಂದು ಉನ್ನತ ನ್ಯಾಯಾಲಯಕ್ಕೆ ಮಾಡಿದ ಮನವಿ. ಇದು ಮುಖ್ಯವಾಗಿ ಕೆಳ ನ್ಯಾಯಾಲಯ ಅಧಿಕಾರವ್ಯಾಪ್ತಿಯೊಳಗೆ ಉಳಿದಿದೆಯೇ ಮತ್ತು ಸರಿಯಾದ ಕಾರ್ಯವಿಧಾನ ಅನುಸರಿಸಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸುವ ಮರುಪರಿಶೀಲನೆಗಿಂತ, ಮತ್ತು ಸ್ವಂತ ನಿರ್ಧಾರವನ್ನು ಸ್ಪಷ್ಟ ದೋಷಕ್ಕಾಗಿ ಮರುಪರಿಶೀಲಿಸಲು ಅದೇ ನ್ಯಾಯಾಲಯವನ್ನು ಕೋರುವ ಮರುಪರಿಶೀಲನೆಗಿಂತ ವಿಶಾಲವಾಗಿದೆ.',
  'suit-for-recovery':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿ ಇನ್ನೊಬ್ಬರಿಗೆ ಬಾಕಿ ಇರುವ ಹಣದ ಮೊತ್ತ ವಸೂಲಿ ಮಾಡಲು ದಾಖಲಿಸುವ ಸಿವಿಲ್ ಪ್ರಕರಣ, ಉದಾಹರಣೆಗೆ ಪಾವತಿಯಾಗದ ಸಾಲ, ಒಪ್ಪಂದದ ಅಡಿಯಲ್ಲಿ ಪಾವತಿಯಾಗದ ಬಾಕಿ, ಅಥವಾ ಮಾರಾಟ ಮಾಡಿದ ಸರಕುಗಳ ಬೆಲೆ.',
  'declaratory-suit':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿ ನ್ಯಾಯಾಲಯವನ್ನು ತಮ್ಮ ಕಾನೂನು ಹಕ್ಕು ಅಥವಾ ಸ್ಥಿತಿಯನ್ನು, ಉದಾಹರಣೆಗೆ ಆಸ್ತಿಯ ಮೇಲಿನ ಅವರ ಹಕ್ಕನ್ನು, ಔಪಚಾರಿಕವಾಗಿ ಘೋಷಿಸಬೇಕೆಂದು ಕೇಳುವ ಸಿವಿಲ್ ಪ್ರಕರಣ, ಹೊಂದಾಣಿಕೆ ಅಥವಾ ಸ್ವಾಧೀನ ವಸೂಲಿಯಂತಹ ಹೆಚ್ಚಿನ ಪರಿಹಾರವನ್ನೂ ಆದೇಶಿಸಬೇಕೆಂದು ಕೇಳುವ ಬದಲು.',
  'partition-suit':
    'ಆಸ್ತಿಯ ಸಹ-ಮಾಲೀಕ, ಹೆಚ್ಚಾಗಿ ಕುಟುಂಬ ಸದಸ್ಯರಲ್ಲಿ, ಆಸ್ತಿಯನ್ನು ವಿಭಜಿಸಿ ಪ್ರತಿ ಮಾಲೀಕರ ಪ್ರತ್ಯೇಕ ಪಾಲನ್ನು ಗುರುತಿಸಬೇಕೆಂದು ನ್ಯಾಯಾಲಯವನ್ನು ಕೋರಿ ದಾಖಲಿಸುವ ಸಿವಿಲ್ ಪ್ರಕರಣ.',
  'restitution':
    'ಮೇಲ್ಮನವಿಯಲ್ಲಿ ನಂತರ ಹಿಂತೆಗೆದುಕೊಂಡ ಅಥವಾ ಬದಲಾಯಿಸಲಾದ ಡಿಕ್ರಿ ಅಥವಾ ಆದೇಶಕ್ಕೆ ಮೊದಲು ಇದ್ದ ಸ್ಥಾನಕ್ಕೆ ಒಂದು ಪಕ್ಷವನ್ನು ಪುನಃಸ್ಥಾಪಿಸುವ ಆದೇಶ, ಸಾಮಾನ್ಯವಾಗಿ ಅದರ ಅಡಿಯಲ್ಲಿ ಪಡೆದ ಹಣ ಅಥವಾ ಆಸ್ತಿಯನ್ನು ಇತರ ಪಕ್ಷ ಹಿಂತಿರುಗಿಸಬೇಕೆಂದು ಬೇಡುವ ಮೂಲಕ.',
  'set-off-and-counterclaim':
    'ಸೆಟ್-ಆಫ್, ವಾದಿ ಪ್ರತಿವಾದಿಗೆ ಬಾಕಿ ಇರುವ ಪ್ರತ್ಯೇಕ ಸಾಲವನ್ನು ಸೂಚಿಸುವ ಮೂಲಕ, ಪ್ರತಿವಾದಿಗೆ ವಾದಿಗೆ ಬಾಕಿ ಇರುವುದನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಅಥವಾ ರದ್ದುಗೊಳಿಸಲು ಅನುಮತಿ ನೀಡುತ್ತದೆ. ಪ್ರತಿ-ಹಕ್ಕು ಇನ್ನೂ ಮುಂದೆ ಹೋಗುತ್ತದೆ, ಅದೇ ಪ್ರಕರಣದಲ್ಲಿ ಪ್ರತ್ಯೇಕ ದಾವೆ ದಾಖಲಿಸುವ ಬದಲು, ಪ್ರತಿವಾದಿಗೆ ವಾದಿಯ ವಿರುದ್ಧ ಅವರ ಸ್ವಂತ ಸ್ವತಂತ್ರ ಹಕ್ಕನ್ನು ಎತ್ತಲು ಅನುಮತಿಸುತ್ತದೆ.',
  'mesne-profits':
    'ಇನ್ನೊಬ್ಬರ ಆಸ್ತಿಯನ್ನು ಅನ್ಯಾಯವಾಗಿ ಆಕ್ರಮಿಸಿ ಬಳಸಿದ್ದಕ್ಕೆ ಒಬ್ಬ ವ್ಯಕ್ತಿ ಪಾವತಿಸಬೇಕೆಂದು ನ್ಯಾಯಾಲಯ ಆದೇಶಿಸುವ ಪರಿಹಾರ, ಆ ಅನ್ಯಾಯದ ಸ್ವಾಧೀನದ ಅವಧಿಯಲ್ಲಿ ಅವರು ಪಡೆದ ಲಾಭ ಅಥವಾ ಪ್ರಯೋಜನ, ಅಥವಾ ನಿಜವಾದ ಮಾಲೀಕ ಕಳೆದುಕೊಂಡದ್ದರ ಆಧಾರದ ಮೇಲೆ ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ.',
  'rejection-of-plaint':
    'ಪ್ಲೇಯಿಂಟ್ ಸ್ವತಃ ಮೂಲಭೂತ ದೋಷದಿಂದ ಬಳಲುತ್ತಿದೆ ಎಂಬ ಕಾರಣದಿಂದ, ಉದಾಹರಣೆಗೆ ಯಾವುದೇ ವಾದಹೇತು ಬಹಿರಂಗಪಡಿಸದಿರುವುದು ಅಥವಾ ಸಾಕಷ್ಟು ಸ್ಟ್ಯಾಂಪ್ ಮಾಡದಿರುವುದು, ಪೂರ್ಣ ವಿಚಾರಣೆಗೆ ಹೋಗದೆ, ದಾವೆಯನ್ನು ಮುಂದುವರಿಸಲು ನ್ಯಾಯಾಲಯ ನಿರಾಕರಿಸುವ ಆದೇಶ. ವಿಚಾರಣೆಯ ನಂತರದ ವಜಾಗೊಳಿಕೆಗಿಂತ ಭಿನ್ನವಾಗಿ, ಕೆಲವು ಸಂದರ್ಭಗಳಲ್ಲಿ ಇದು ಅದೇ ವಾದಹೇತುವಿನ ಮೇಲೆ ಹೊಸ ದಾವೆ ದಾಖಲಿಸಲು ವಾದಿಯನ್ನು ಮುಕ್ತಗೊಳಿಸುತ್ತದೆ.',
  'return-of-plaint':
    'ನ್ಯಾಯಾಲಯ ದಾವೆ ವಿಚಾರಣೆ ಮಾಡಲು ಅಧಿಕಾರವ್ಯಾಪ್ತಿ ಹೊಂದಿಲ್ಲ ಎಂದು ಕಂಡುಕೊಂಡಾಗ ನೀಡಲಾದ, ಸರಿಯಾದ ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಹಾಜರುಪಡಿಸಲು ಪ್ಲೇಯಿಂಟ್ ಅನ್ನು ವಾದಿಗೆ ಹಿಂತಿರುಗಿಸುವ ಆದೇಶ. ವಾದಿ ನಂತರ ಅದೇ ಪ್ಲೇಯಿಂಟ್ ಅನ್ನು ಸರಿಯಾದ ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಮರು ದಾಖಲಿಸಬಹುದು.',
  'mandatory-injunction':
    'ಕೇವಲ ಒಬ್ಬ ಪಕ್ಷ ಏನನ್ನಾದರೂ ಮಾಡುವುದನ್ನು ತಡೆಯುವ ಬದಲು, ಅನಧಿಕೃತ ನಿರ್ಮಾಣ ತೆಗೆಯುವಂತಹ, ಅಥವಾ ಕೆಡವಲಾದ ರಚನೆಯನ್ನು ಪುನಃಸ್ಥಾಪಿಸುವಂತಹ, ಒಂದು ನಿರ್ದಿಷ್ಟ ಕೃತ್ಯವನ್ನು ಸಕ್ರಿಯವಾಗಿ ಮಾಡಲು ಒಂದು ಪಕ್ಷಕ್ಕೆ ನಿರ್ದೇಶಿಸುವ ನ್ಯಾಯಾಲಯದ ಆದೇಶ. ಕೇವಲ ಪಕ್ಷ ಕಾರ್ಯನಿರ್ವಹಿಸುವುದನ್ನು ತಡೆಯುವ ನಿಷೇಧಾತ್ಮಕ ತಡೆಯಾಜ್ಞೆಯಿಂದ ಇದನ್ನು ಪ್ರತ್ಯೇಕಿಸಲಾಗಿದೆ.',
  'interpleader-suit':
    'ಇಬ್ಬರು ಅಥವಾ ಹೆಚ್ಚಿನ ಇತರ ಜನರು ಹಕ್ಕು ಸಾಧಿಸುತ್ತಿರುವ ಹಣ ಅಥವಾ ಆಸ್ತಿಯನ್ನು ಹಿಡಿದಿರುವ ವ್ಯಕ್ತಿ ದಾಖಲಿಸುವ ದಾವೆ, ಅವರಲ್ಲಿ ಯಾರ ಮೇಲೂ ವಿವಾದಿಸುವ ಯಾವುದೇ ವ್ಯಕ್ತಿಗತ ಹಿತಾಸಕ್ತಿ ಇಲ್ಲದೆ, ಪ್ರತಿಸ್ಪರ್ಧಿ ಹಕ್ಕುದಾರರಲ್ಲಿ ಯಾರಿಗೆ ಅದು ನಿಜವಾಗಿ ಸೇರಿದೆ ಎಂದು ನಿರ್ಧರಿಸಬೇಕೆಂದು ನ್ಯಾಯಾಲಯವನ್ನು ಕೋರುತ್ತದೆ.',
  'garnishee-order':
    'ಜಾರಿ ಪ್ರಕ್ರಿಯೆಗಳಲ್ಲಿ, ತೀರ್ಪು-ಋಣಿಗೆ ಹಣ ಬಾಕಿ ಇರುವ, ಅಥವಾ ಅವರಿಗೆ ಸೇರಿದ ಹಣ ಹಿಡಿದಿರುವ, ಬ್ಯಾಂಕ್‌ನಂತಹ ಮೂರನೇ ಪಕ್ಷಕ್ಕೆ, ಆ ಮೊತ್ತವನ್ನು ತೀರ್ಪು-ಋಣಿಗೆ ಬದಲು ನೇರವಾಗಿ ಡಿಕ್ರಿ-ಹೊಂದಿರುವವರಿಗೆ ಪಾವತಿಸಲು ನಿರ್ದೇಶಿಸುವ ಆದೇಶ.',
  'attachment-before-judgment':
    'ಪ್ರತಿವಾದಿ ಅವರ ವಿರುದ್ಧ ಅಂತಿಮವಾಗಿ ನೀಡಬಹುದಾದ ಯಾವುದೇ ಡಿಕ್ರಿಯನ್ನು ವಿಫಲಗೊಳಿಸಲು ತಮ್ಮ ಆಸ್ತಿಗಳನ್ನು ವಿಲೇವಾರಿ ಮಾಡುವ ಅಥವಾ ತೆಗೆದುಹಾಕುವ ಸಾಧ್ಯತೆ ಇದೆ ಎಂದು ನ್ಯಾಯಾಲಯ ತೃಪ್ತಿಗೊಂಡಾಗ, ದಾವೆ ಇನ್ನೂ ಬಾಕಿಯಿರುವಾಗ ಪ್ರತಿವಾದಿಯ ಆಸ್ತಿಯನ್ನು ಜೋಡಿಸುವ ಆದೇಶ.',
  'costs':
    'ಕೋರ್ಟ್ ಫೀ ಮತ್ತು ಕಾನೂನು ವೆಚ್ಚಗಳಂತಹ ದಾವೆಯ ವೆಚ್ಚಗಳು, ಇವುಗಳನ್ನು ನ್ಯಾಯಾಲಯ ಪ್ರಕರಣದಲ್ಲಿ ತನ್ನ ಅಂತಿಮ ನಿರ್ಧಾರದ ಭಾಗವಾಗಿ, ಸಾಮಾನ್ಯವಾಗಿ ಸೋತ ಪಕ್ಷದಿಂದ ಗೆದ್ದ ಪಕ್ಷಕ್ಕೆ, ಒಂದು ಪಕ್ಷ ಇನ್ನೊಂದಕ್ಕೆ ಪಾವತಿಸಬೇಕೆಂದು ನಿರ್ದೇಶಿಸಬಹುದು.',
  'decree-holder-and-judgment-debtor':
    'ಡಿಕ್ರಿ-ಹೊಂದಿರುವವರು ನ್ಯಾಯಾಲಯ ಡಿಕ್ರಿ ನೀಡಿದ ಪಕ್ಷ ಮತ್ತು ಅದನ್ನು ಜಾರಿಗೊಳಿಸುವ ಹಕ್ಕು ಹೊಂದಿದ್ದಾರೆ. ತೀರ್ಪು-ಋಣಿ ಡಿಕ್ರಿ ನೀಡಲಾದ ಪಕ್ಷ ಮತ್ತು ಇದರ ಫಲಿತಾಂಶದ ಕಡ್ಡಾಯವನ್ನು, ಸಾಮಾನ್ಯವಾಗಿ ಹಣ ಪಾವತಿಸಲು ಅಥವಾ ಆಸ್ತಿಯನ್ನು ಹಸ್ತಾಂತರಿಸಲು, ಹೊಂದಿದ್ದಾರೆ.',
  'consent-decree':
    'ಪ್ರಕರಣದ ಎರಡೂ ಪಕ್ಷಗಳು ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿ ಒಪ್ಪಿಕೊಂಡ ಹೊಂದಾಣಿಕೆಯ ನಿಯಮಗಳ ಪ್ರಕಾರ ನ್ಯಾಯಾಲಯ ನೀಡಿದ ಡಿಕ್ರಿ, ಹುರುಳಿನ ಮೇಲೆ ವಿವಾದಿತ ವಿಚಾರಣೆಯ ನಂತರ ಬದಲಿಗೆ. ಒಮ್ಮೆ ನೀಡಿದ ನಂತರ, ಸೀಮಿತ ಸಂದರ್ಭಗಳನ್ನು ಹೊರತುಪಡಿಸಿ, ಆಧಾರವಾಗಿರುವ ನಿರ್ಧಾರ ತಪ್ಪಾಗಿತ್ತು ಎಂಬ ಕಾರಣದ ಮೇಲೆ ಇದನ್ನು ಮೇಲ್ಮನವಿಯಲ್ಲಿ ಸಾಮಾನ್ಯವಾಗಿ ಪ್ರಶ್ನಿಸಲಾಗುವುದಿಲ್ಲ.',
  'abatement-of-suit':
    'ಪ್ರಕರಣದ ಸ್ವಯಂಚಾಲಿತ ಅಂತ್ಯ, ಅಥವಾ ಒಂದು ನಿರ್ದಿಷ್ಟ ಪಕ್ಷಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ಅದರ ಒಂದು ಭಾಗ, ಹೆಚ್ಚಾಗಿ ಒಂದು ಪಕ್ಷ ಸತ್ತಿದ್ದು ಮತ್ತು ಅವರ ಕಾನೂನು ವಾರಸುದಾರರನ್ನು ಕಾನೂನು ಅನುಮತಿಸಿದ ಸಮಯದೊಳಗೆ ದಾಖಲೆಗೆ ತರಲಾಗಿಲ್ಲ ಎಂಬ ಕಾರಣದಿಂದ.',
  'liquidated-damages':
    'ಒಪ್ಪಂದದ ಪಕ್ಷಗಳು ಮುಂಚಿತವಾಗಿ ಒಪ್ಪಿಕೊಳ್ಳುವ ನಿರ್ದಿಷ್ಟ ಹಣದ ಮೊತ್ತ, ಅವರಲ್ಲಿ ಒಬ್ಬರು ಅದನ್ನು ಉಲ್ಲಂಘಿಸಿದರೆ ಪರಿಹಾರವಾಗಿ ಪಾವತಿಸಲಾಗುತ್ತದೆ, ಉಲ್ಲಂಘನೆ ಸಂಭವಿಸಿದ ನಂತರ ನ್ಯಾಯಾಲಯ ನಿರ್ಣಯಿಸಬೇಕಾದ ಅಲಿಕ್ವಿಡೇಟೆಡ್ ಹಾನಿಗಿಂತ ಭಿನ್ನ.',
  'receiver':
    'ವಿವಾದದ ವಿಷಯವಾಗಿರುವ ಆಸ್ತಿಯನ್ನು ತಾತ್ಕಾಲಿಕವಾಗಿ ಕಸ್ಟಡಿಗೆ ತೆಗೆದುಕೊಳ್ಳಲು, ನಿರ್ವಹಿಸಲು, ಅಥವಾ ಸಂರಕ್ಷಿಸಲು ನ್ಯಾಯಾಲಯ ನೇಮಿಸುವ ವ್ಯಕ್ತಿ, ಪ್ರಕರಣ ನಿರ್ಧರಿಸುತ್ತಿರುವಾಗ ಅದು ವ್ಯರ್ಥವಾಗದಂತೆ, ಹಾನಿಯಾಗದಂತೆ, ಅಥವಾ ತಪ್ಪಾಗಿ ನಿರ್ವಹಿಸದಂತೆ.',
  'original-application':
    'ಒಂದು ಬ್ಯಾಂಕ್ ಅಥವಾ ಹಣಕಾಸು ಸಂಸ್ಥೆ, ಸಾಲಗಾರ ಬಾಕಿ ಇರುವ ಹಣವನ್ನು ವಸೂಲಿ ಮಾಡಲು ಸಾಲ ವಸೂಲಿ ನ್ಯಾಯಮಂಡಳಿಯ (DRT) ಮುಂದೆ ದಾಖಲಿಸುವ ಮುಖ್ಯ ಪ್ರಕರಣ ದಾಖಲೆ, ಸಿವಿಲ್ ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಪ್ಲೇಯಿಂಟ್ ವಹಿಸುವ ಪಾತ್ರವನ್ನೇ ಹೋಲುತ್ತದೆ.',
  'securitisation-application':
    'ಸಾಲಗಾರ ಅಥವಾ ಇತರ ಬಾಧಿತ ವ್ಯಕ್ತಿ, SARFAESI ಕಾಯಿದೆಯ ಅಡಿಯಲ್ಲಿ ಭದ್ರತೆಯ ಆಸ್ತಿಯನ್ನು ವಶಪಡಿಸಿಕೊಳ್ಳಲು ಅಥವಾ ಮಾರಾಟ ಮಾಡಲು ಸಾಲದಾತ ಕೈಗೊಂಡ ಕ್ರಮಗಳನ್ನು ಪ್ರಶ್ನಿಸಿ, ಸಾಲ ವಸೂಲಿ ನ್ಯಾಯಮಂಡಳಿಯ ಮುಂದೆ ದಾಖಲಿಸುವ ಅರ್ಜಿ.',
  'sarfaesi':
    'ಸೆಕ್ಯುರಿಟೈಸೇಶನ್ ಮತ್ತು ಹಣಕಾಸು ಆಸ್ತಿಗಳ ಪುನರ್ನಿರ್ಮಾಣ ಮತ್ತು ಭದ್ರತಾ ಹಿತಾಸಕ್ತಿ ಜಾರಿ ಕಾಯಿದೆ, 2002ಕ್ಕೆ ಸಂಕ್ಷಿಪ್ತ ಹೆಸರು. ಸಾಲಗಾರ ಡಿಫಾಲ್ಟ್ ಮಾಡಿದಾಗ, ಬ್ಯಾಂಕ್‌ಗಳು ಮತ್ತು ಕೆಲವು ಹಣಕಾಸು ಸಂಸ್ಥೆಗಳಿಗೆ, ಮೊದಲು ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಮೊಕದ್ದಮೆ ಹೂಡದೆ, ಸಾಲಕ್ಕೆ ಭದ್ರತೆಯಾಗಿ ಒತ್ತೆ ಇಟ್ಟ ಆಸ್ತಿಯನ್ನು ನೇರವಾಗಿ ವಶಪಡಿಸಿಕೊಳ್ಳಲು ಮತ್ತು ಮಾರಾಟ ಮಾಡಲು ಇದು ಅನುಮತಿಸುತ್ತದೆ.',
  'recovery-certificate':
    'ಒರಿಜಿನಲ್ ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಸಾಲದಾತನ ಪರವಾಗಿ ನಿರ್ಧರಿಸಿದ ನಂತರ, ಸಾಲ ವಸೂಲಿ ನ್ಯಾಯಮಂಡಳಿ ನೀಡುವ ಪ್ರಮಾಣಪತ್ರ, ಸಾಲಗಾರನಿಂದ ಬಾಕಿ ಮೊತ್ತವನ್ನು, ಅವರ ಆಸ್ತಿಯನ್ನು ಜೋಡಿಸಿ ಮಾರಾಟ ಮಾಡುವುದು ಸೇರಿದಂತೆ, ವಸೂಲಿ ಮಾಡಲು ಅಧಿಕಾರ ನೀಡುತ್ತದೆ.',
  'debt-recovery-officer':
    'ರಿಕವರಿ ಸರ್ಟಿಫಿಕೇಟ್ ನೀಡಿದ ನಂತರ ವಾಸ್ತವವಾಗಿ ವಸೂಲಿ ಪ್ರಕ್ರಿಯೆ ನಡೆಸುವ, ಸಾಲ ವಸೂಲಿ ನ್ಯಾಯಮಂಡಳಿಗೆ ಜೋಡಿಸಿದ ಅಧಿಕಾರಿ, ಉದಾಹರಣೆಗೆ ಸಾಲಗಾರನ ಆಸ್ತಿಯನ್ನು ಜೋಡಿಸಿ ಹರಾಜು ಮಾಡುವುದು.',
  'cirp':
    'ಇನ್ಸಾಲ್ವೆನ್ಸಿ ಮತ್ತು ಬ್ಯಾಂಕ್ರಪ್ಟ್ಸಿ ಕೋಡ್ ಅಡಿಯಲ್ಲಿ ನಡೆಸುವ ಪ್ರಕ್ರಿಯೆ, ಸಾಲ ಡಿಫಾಲ್ಟ್ ಮಾಡಿದ ಕಂಪನಿಯನ್ನು ನೇಮಕಗೊಂಡ ರೆಸಲ್ಯೂಶನ್ ಪ್ರೊಫೆಷನಲ್ ಸ್ವಾಧೀನಪಡಿಸಿಕೊಳ್ಳುತ್ತಾರೆ, ಅವರು ಸಾಲದಾತರೊಂದಿಗೆ ಕೆಲಸ ಮಾಡಿ ಕಂಪನಿಯನ್ನು ರೆಸಲ್ಯೂಶನ್ ಪ್ಲಾನ್ ಅಡಿಯಲ್ಲಿ ಪುನರುಜ್ಜೀವನಗೊಳಿಸುತ್ತಾರೆ ಅಥವಾ ಲಿಕ್ವಿಡೇಶನ್‌ನ ಕಡೆಗೆ ಕೊಂಡೊಯ್ಯುತ್ತಾರೆ.',
  'miscellaneous-application':
    'NCLT ಅಥವಾ NCLAT ಮುಂದೆ ದಾಖಲಿಸುವ ಅರ್ಜಿ, ಸಂಪೂರ್ಣ ಹೊಸ ಹಕ್ಕು ಎತ್ತುವ ಬದಲು, ಬಾಕಿ ಇರುವ ಪ್ರಕರಣಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ನಿರ್ದಿಷ್ಟ ನಿರ್ದೇಶನ ಅಥವಾ ಪರಿಹಾರ ಕೋರುತ್ತದೆ, ಉದಾಹರಣೆಗೆ ಕಾರ್ಯವಿಧಾನದ ಸ್ಪಷ್ಟೀಕರಣ ಕೋರುವುದು.',
  'resolution-plan':
    'ಕಾರ್ಪೊರೇಟ್ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ರೆಸಲ್ಯೂಶನ್ ಪ್ರಕ್ರಿಯೆಯ ಸಮಯದಲ್ಲಿ, ಭವಿಷ್ಯದ ಖರೀದಿದಾರ ಅಥವಾ ಹೂಡಿಕೆದಾರ ಸಲ್ಲಿಸುವ ಯೋಜನೆ, ಹಣಕಾಸಿನ ತೊಂದರೆಯಲ್ಲಿರುವ ಕಂಪನಿಯನ್ನು ಹೇಗೆ ಪುನರುಜ್ಜೀವನಗೊಳಿಸಲಾಗುವುದು ಮತ್ತು ಅದರ ಸಾಲದಾತರಿಗೆ ಹೇಗೆ ಪಾವತಿಸಲಾಗುವುದು ಎಂದು ಸೂಚಿಸುತ್ತದೆ. ಇದನ್ನು ಜಾರಿಗೆ ಬರುವ ಮೊದಲು ಕಮಿಟಿ ಆಫ್ ಕ್ರೆಡಿಟರ್ಸ್ ಮತ್ತು ನಂತರ NCLT ಅನುಮೋದಿಸಬೇಕು.',
  'committee-of-creditors':
    'ಮುಖ್ಯವಾಗಿ ಕಂಪನಿಯ ಹಣಕಾಸು ಸಾಲದಾತರಿಂದ ಕೂಡಿದ ಸಂಸ್ಥೆ, ಕಾರ್ಪೊರೇಟ್ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ರೆಸಲ್ಯೂಶನ್ ಪ್ರಕ್ರಿಯೆಯ ಸಮಯದಲ್ಲಿ ರಚಿಸಲಾಗುತ್ತದೆ, ಯಾವ ರೆಸಲ್ಯೂಶನ್ ಪ್ಲಾನ್ ಅನುಮೋದಿಸಬೇಕು ಅಥವಾ ಕಂಪನಿಯನ್ನು ಬದಲಿಗೆ ಲಿಕ್ವಿಡೇಟ್ ಮಾಡಬೇಕೆ ಎಂಬಂತಹ ಪ್ರಮುಖ ವಿಷಯಗಳನ್ನು ನಿರ್ಧರಿಸುತ್ತದೆ.',
  'operational-creditor':
    'ಸರಕು ಅಥವಾ ಸೇವೆಗಳನ್ನು ಪೂರೈಸಿದ್ದಕ್ಕೆ ಕಂಪನಿ ಹಣ ಬಾಕಿ ಇರುವ ಸಾಲದಾತ, ಉದಾಹರಣೆಗೆ ಮಾರಾಟಗಾರ ಅಥವಾ ಪೂರೈಕೆದಾರ, ಸಾಲ ಅಥವಾ ಮುಂಗಡವಾಗಿ ನೀಡಿದ ಹಣಕ್ಕೆ ಕಂಪನಿ ಬಾಕಿ ಇರುವ ಫೈನಾನ್ಷಿಯಲ್ ಕ್ರೆಡಿಟರ್‌ಗಿಂತ ಭಿನ್ನ.',
  'financial-creditor':
    'ಹಣ ಸಾಲ ನೀಡಿದ್ದರಿಂದ ಅಥವಾ ಅಂತಹ ಹಣಕಾಸಿನ ವ್ಯವಸ್ಥೆಯಿಂದ ಉಂಟಾಗುವ ಸಾಲವನ್ನು ಕಂಪನಿ ಬಾಕಿ ಇರುವ ಸಾಲದಾತ, ಉದಾಹರಣೆಗೆ ಬ್ಯಾಂಕ್ ಸಾಲ ಅಥವಾ ಡಿಬೆಂಚರ್‌ಗಳು, ಸರಕು ಅಥವಾ ಸೇವೆಗಳಿಗೆ ಬಾಕಿ ಇರುವ ಆಪರೇಷನಲ್ ಕ್ರೆಡಿಟರ್‌ಗಿಂತ ಭಿನ್ನ.',
  'consumer-complaint':
    'ಮಾರಾಟಗಾರ ಅಥವಾ ಸೇವಾ ಪೂರೈಕೆದಾರರಿಂದ ಸೇವೆಯಲ್ಲಿ ಕೊರತೆ, ಸರಕುಗಳಲ್ಲಿ ದೋಷ, ಅಥವಾ ಅನ್ಯಾಯದ ವ್ಯಾಪಾರ ಪ್ರಾಕ್ಟೀಸ್ ಆರೋಪಿಸಿ, ಗ್ರಾಹಕ ಆಯೋಗದ ಮುಂದೆ ಗ್ರಾಹಕ ದಾಖಲಿಸುವ ದಾಖಲೆ, ಪರಿಹಾರ ಅಥವಾ ಇನ್ನೊಂದು ಪರಿಹಾರ ಕೋರುತ್ತದೆ.',
  'opposite-party':
    'ಗ್ರಾಹಕ ಗ್ರಾಹಕ ಆಯೋಗದ ಮುಂದೆ ದೂರು ದಾಖಲಿಸುವ ಮಾರಾಟಗಾರ, ತಯಾರಕ, ಅಥವಾ ಸೇವಾ ಪೂರೈಕೆದಾರ, ಸಾಮಾನ್ಯ ಸಿವಿಲ್ ಪ್ರಕರಣದಲ್ಲಿ ಪ್ರತಿವಾದಿಗೆ ಸಮನಾಗಿ.',
  'deficiency-in-service':
    'ಭರವಸೆ ಮಾಡಿದ ಅಥವಾ ಕಾನೂನಿನಿಂದ ಅಗತ್ಯಪಡಿಸಿದ ಗುಣಮಟ್ಟ, ಸ್ವರೂಪ, ಅಥವಾ ವಿಧಾನಕ್ಕೆ ಹೋಲಿಸಿದರೆ ಸೇವೆಯಲ್ಲಿನ ಕೊರತೆ, ಅಪೂರ್ಣತೆ, ಅಥವಾ ಅಸಮರ್ಪಕತೆ. ಗ್ರಾಹಕ ಆಯೋಗದ ಮುಂದೆ ಗ್ರಾಹಕ ದೂರು ದಾಖಲಿಸಬಹುದಾದ ಮುಖ್ಯ ಆಧಾರಗಳಲ್ಲಿ ಇದು ಒಂದು.',
  'unfair-trade-practice':
    'ಮಾರಾಟಗಾರ ಅಥವಾ ಸೇವಾ ಪೂರೈಕೆದಾರ ಸರಕು ಅಥವಾ ಸೇವೆಗಳನ್ನು ಉತ್ತೇಜಿಸಲು ಅಥವಾ ಮಾರಾಟ ಮಾಡಲು ಬಳಸುವ ತಪ್ಪುದಾರಿಗೊಳಿಸುವ ಅಥವಾ ಮೋಸದ ವಿಧಾನ, ಉದಾಹರಣೆಗೆ ಸುಳ್ಳು ಜಾಹೀರಾತು ಅಥವಾ ಉತ್ಪನ್ನದ ಗುಣಮಟ್ಟವನ್ನು ತಪ್ಪಾಗಿ ಪ್ರಸ್ತುತಪಡಿಸುವುದು. ಹೆಚ್ಚಿನ ನಿರ್ದಿಷ್ಟ ನಷ್ಟ ಅನುಭವಿಸಿದ್ದನ್ನು ತೋರಿಸುವ ಅಗತ್ಯವಿಲ್ಲದೆಯೂ ಗ್ರಾಹಕ ಇದರ ಬಗ್ಗೆ ಗ್ರಾಹಕ ಆಯೋಗದ ಮುಂದೆ ದೂರು ನೀಡಬಹುದು.',
  'consumer-commission-hierarchy':
    'ಗ್ರಾಹಕ ದೂರುಗಳನ್ನು ಆಲಿಸುವ ಗ್ರಾಹಕ ಆಯೋಗಗಳ ಮೂರು-ಹಂತದ ವ್ಯವಸ್ಥೆ, ಹಕ್ಕಿನ ಮೌಲ್ಯದ ಆಧಾರದ ಮೇಲೆ ಸಂಘಟಿಸಲಾಗಿದೆ. ಜಿಲ್ಲಾ ಆಯೋಗಗಳು ₹50 ಲಕ್ಷದವರೆಗಿನ ಹಕ್ಕುಗಳನ್ನು ನಿಭಾಯಿಸುತ್ತವೆ, ರಾಜ್ಯ ಆಯೋಗಗಳು ₹50 ಲಕ್ಷ ಮತ್ತು ₹2 ಕೋಟಿ ನಡುವಿನ ಹಕ್ಕುಗಳನ್ನು ಮತ್ತು ಜಿಲ್ಲಾ ಆಯೋಗಗಳಿಂದ ಮೇಲ್ಮನವಿಗಳನ್ನು ನಿಭಾಯಿಸುತ್ತವೆ, ಮತ್ತು ರಾಷ್ಟ್ರೀಯ ಆಯೋಗ ₹2 ಕೋಟಿಗಿಂತ ಹೆಚ್ಚಿನ ಹಕ್ಕುಗಳನ್ನು ಮತ್ತು ರಾಜ್ಯ ಆಯೋಗಗಳಿಂದ ಮೇಲ್ಮನವಿಗಳನ್ನು ನಿಭಾಯಿಸುತ್ತದೆ.',
  'special-leave-petition':
    'ಸಂವಿಧಾನದ 136ನೇ ವಿಧಿಯ ಅಡಿಯಲ್ಲಿ, ದೇಶದ ಯಾವುದೇ ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯ ತೀರ್ಪು ಅಥವಾ ಆದೇಶದ ವಿರುದ್ಧ ಮೇಲ್ಮನವಿಗೆ ವಿಶೇಷ ಅನುಮತಿ ಕೋರಿ ಸುಪ್ರೀಂ ಕೋರ್ಟ್ ಮುಂದೆ ದಾಖಲಿಸುವ ಅರ್ಜಿ. ಮೊದಲು ಸುಪ್ರೀಂ ಕೋರ್ಟ್‌ನ ವಿವೇಚನಾ ಅನುಮತಿ ಬೇಕಾಗಿರುವುದರಿಂದ, ಸಾಮಾನ್ಯವಾಗಿ ಹಕ್ಕಾಗಿರುವ ಸಾಮಾನ್ಯ ಮೇಲ್ಮನವಿಗಿಂತ ಇದು ಪ್ರತ್ಯೇಕ ಹಂತವಾಗಿದೆ.',
  'debts-recovery-appellate-tribunal':
    'ಸಾಲ ವಸೂಲಿ ನ್ಯಾಯಮಂಡಳಿ (DRT) ನೀಡಿದ ಆದೇಶಗಳ ವಿರುದ್ಧ, ಉದಾಹರಣೆಗೆ ಒರಿಜಿನಲ್ ಅಪ್ಲಿಕೇಶನ್‌ಗಳು ಅಥವಾ ಸೆಕ್ಯುರಿಟೈಸೇಶನ್ ಅಪ್ಲಿಕೇಶನ್‌ಗಳಲ್ಲಿ, ಮೇಲ್ಮನವಿಗಳನ್ನು ಆಲಿಸುವ ಮೇಲ್ಮನವಿ ನ್ಯಾಯಮಂಡಳಿ.',
  'pre-deposit':
    'ಮೇಲ್ಮನವಿ ನ್ಯಾಯಮಂಡಳಿ ದಾಖಲಿಸುವ ಮೊದಲು, ಮುಖ್ಯವಾಗಿ DRT, NCLT, ಅಥವಾ SARFAESI ಆದೇಶದ ವಿರುದ್ಧ, ಒಂದು ಪಕ್ಷ ಪಾವತಿಸಬೇಕಾದ ಹಣದ ಮೊತ್ತ, ಮೇಲ್ಮನವಿ ದಾಖಲಾಗಲು ಅಥವಾ ಆಲಿಸಲ್ಪಡಲು ಅಗತ್ಯ, ಸಾಮಾನ್ಯವಾಗಿ ವಿವಾದಿತ ಮೊತ್ತದ ಶೇಕಡಾವಾರು ಆಗಿ ನಿಗದಿಪಡಿಸಲಾಗುತ್ತದೆ.',
  'national-company-law-tribunal':
    'ಕಂಪನಿ ವಿವಾದಗಳು, ವಿಲೀನಗಳು, ಮತ್ತು ಕಾರ್ಪೊರೇಟ್ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ರೆಸಲ್ಯೂಶನ್ ಪ್ರಕ್ರಿಯೆ ಸೇರಿದಂತೆ, ಕಂಪನಿ ಕಾನೂನು ಮತ್ತು ಇನ್ಸಾಲ್ವೆನ್ಸಿ ವಿಷಯಗಳನ್ನು ನಿರ್ಧರಿಸುವ ವಿಶೇಷ ನ್ಯಾಯಮಂಡಳಿ.',
  'national-company-law-appellate-tribunal':
    'ನ್ಯಾಷನಲ್ ಕಂಪನಿ ಲಾ ಟ್ರಿಬ್ಯೂನಲ್ ನೀಡಿದ ಆದೇಶಗಳ ವಿರುದ್ಧ ಮೇಲ್ಮನವಿಗಳನ್ನು ಆಲಿಸುವ ಮೇಲ್ಮನವಿ ನ್ಯಾಯಮಂಡಳಿ.',
  'corporate-debtor':
    'ಸಾಲ ಡಿಫಾಲ್ಟ್ ಮಾಡಿದ ಕಾರಣ, ಕಾರ್ಪೊರೇಟ್ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ರೆಸಲ್ಯೂಶನ್ ಪ್ರಕ್ರಿಯೆ ಪ್ರಾರಂಭಿಸಲಾದ ಕಂಪನಿ.',
  'resolution-professional':
    'ಕಾರ್ಪೊರೇಟ್ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ರೆಸಲ್ಯೂಶನ್ ಪ್ರಕ್ರಿಯೆಯ ಸಮಯದಲ್ಲಿ ಕಂಪನಿಯ ವ್ಯವಹಾರಗಳನ್ನು ನಡೆಸಲು ನೇಮಿಸಿದ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ಪ್ರೊಫೆಷನಲ್, ಸಾಲದಾತರ ಹಕ್ಕುಗಳನ್ನು ಆಹ್ವಾನಿಸಿ ಪರಿಶೀಲಿಸುವುದು, ಮತ್ತು ರೆಸಲ್ಯೂಶನ್ ಪ್ಲಾನ್ ತಯಾರಿಕೆಯನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡುವುದು ಸೇರಿದಂತೆ. ಪ್ರಕ್ರಿಯೆಯ ಆರಂಭಿಕ ಭಾಗದಲ್ಲಿ, ಈ ಪಾತ್ರವನ್ನು ತಾತ್ಕಾಲಿಕ ಆಧಾರದಲ್ಲಿ ಹೊಂದಲಾಗುತ್ತದೆ.',
  'moratorium-ibc':
    'ಕಂಪನಿ ವಿರುದ್ಧ ಕಾರ್ಪೊರೇಟ್ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ರೆಸಲ್ಯೂಶನ್ ಪ್ರಕ್ರಿಯೆ ಅಂಗೀಕರಿಸಲ್ಪಟ್ಟ ಕೂಡಲೇ ಜಾರಿಗೆ ಬರುವ, ವಸೂಲಿ ದಾವೆಗಳು ಮತ್ತು ಭದ್ರತೆಯ ಜಾರಿ ಸೇರಿದಂತೆ, ಹೆಚ್ಚಿನ ಕಾನೂನು ಪ್ರಕ್ರಿಯೆಗಳನ್ನು ದಾಖಲಿಸುವ ಅಥವಾ ಮುಂದುವರಿಸುವ ಸ್ವಯಂಚಾಲಿತ ಘನೀಕರಣ. ಪ್ರಕ್ರಿಯೆ ನಡೆಯುತ್ತಿರುವಾಗ ಇದು ಜಾರಿಯಲ್ಲಿರುತ್ತದೆ.',
  'liquidator':
    'ಕಾರ್ಪೊರೇಟ್ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ರೆಸಲ್ಯೂಶನ್ ಪ್ರಕ್ರಿಯೆ ಅನುಮೋದಿತ ರೆಸಲ್ಯೂಶನ್ ಪ್ಲಾನ್‌ಗೆ ಕಾರಣವಾಗದಿದ್ದ ಕಾರಣ, ಕಂಪನಿಯನ್ನು ಲಿಕ್ವಿಡೇಶನ್‌ಗೆ ಆದೇಶಿಸಿದ ನಂತರ, ಅದರ ಆಸ್ತಿಗಳನ್ನು ಮಾರಾಟ ಮಾಡಿ ಆದಾಯವನ್ನು ಅದರ ಸಾಲದಾತರಲ್ಲಿ ಹಂಚಲು ನೇಮಿಸಿದ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ಪ್ರೊಫೆಷನಲ್.',
  'possession-notice-sarfaesi':
    'ಸಾಲಗಾರ ಡಿಫಾಲ್ಟ್ ಮಾಡಿದ ನಂತರ, SARFAESI ಕಾಯಿದೆಯ ಅಡಿಯಲ್ಲಿ ಬ್ಯಾಂಕ್ ಅಥವಾ ಹಣಕಾಸು ಸಂಸ್ಥೆ ಹೊರಪಡಿಸುವ ನೋಟಿಸ್, ಸಾಲಕ್ಕೆ ಭದ್ರತೆಯಾಗಿ ಒತ್ತೆ ಇಟ್ಟ ಆಸ್ತಿಯ ಸ್ವಾಧೀನವನ್ನು ಸಾಲದಾತ ವಹಿಸಿಕೊಂಡಿದ್ದಾರೆ ಎಂದು ತಿಳಿಸುತ್ತದೆ.',
  'division-bench':
    'ಎರಡು ಅಥವಾ ಹೆಚ್ಚಿನ ನ್ಯಾಯಾಧೀಶರಿಂದ ಕೂಡಿದ ಹೈಕೋರ್ಟ್ ಅಥವಾ ಸುಪ್ರೀಂ ಕೋರ್ಟ್‌ನ ಪೀಠ, ಏಕ ನ್ಯಾಯಾಧೀಶರ ಪೀಠಕ್ಕಿಂತ ಭಿನ್ನ. ಏಕ ನ್ಯಾಯಾಧೀಶರ ಆದೇಶದ ವಿರುದ್ಧ ಮೇಲ್ಮನವಿಗಳಂತಹ ಕೆಲವು ವಿಷಯಗಳನ್ನು ಡಿವಿಷನ್ ಬೆಂಚ್ ಆಲಿಸಬೇಕು.',
  'adjudicating-authority':
    'ಇನ್ಸಾಲ್ವೆನ್ಸಿ ಮತ್ತು ಬ್ಯಾಂಕ್ರಪ್ಟ್ಸಿ ಕೋಡ್ ಅಡಿಯಲ್ಲಿನ ವಿಷಯಗಳನ್ನು ನಿರ್ಧರಿಸುವಾಗ, ಉದಾಹರಣೆಗೆ ಕಾರ್ಪೊರೇಟ್ ಇನ್ಸಾಲ್ವೆನ್ಸಿ ರೆಸಲ್ಯೂಶನ್ ಪ್ರಕ್ರಿಯೆ ಆರಂಭಿಸುವ ಅರ್ಜಿಯನ್ನು ಅಂಗೀಕರಿಸುವುದು ಅಥವಾ ತಿರಸ್ಕರಿಸುವುದು, ನ್ಯಾಷನಲ್ ಕಂಪನಿ ಲಾ ಟ್ರಿಬ್ಯೂನಲ್ ವಹಿಸುವ ಪಾತ್ರ.',
  'board-resolution':
    'ಸರಿಯಾಗಿ ಕರೆಯಲಾದ ಸಭೆಯಲ್ಲಿ ಕಂಪನಿಯ ನಿರ್ದೇಶಕ ಮಂಡಳಿ ಅಂಗೀಕರಿಸುವ ಔಪಚಾರಿಕ ಲಿಖಿತ ನಿರ್ಧಾರ, ಉದಾಹರಣೆಗೆ ಬ್ಯಾಂಕ್ ಖಾತೆ ತೆರೆಯುವುದು, ಅಧಿಕಾರಿಯನ್ನು ನೇಮಿಸುವುದು, ಅಥವಾ ವಹಿವಾಟನ್ನು ಅನುಮೋದಿಸುವುದರಂತಹ ನಿರ್ದಿಷ್ಟ ವಿಷಯದ ಮೇಲೆ ಅವರ ಅನುಮೋದನೆಯನ್ನು ದಾಖಲಿಸುತ್ತದೆ.',
  'memorandum-of-association':
    'ಕಂಪನಿ ಸ್ಥಾಪನೆಯಾಗುವಾಗ ದಾಖಲಿಸುವ ಮೂಲಭೂತ ದಾಖಲೆ, ಅದರ ಹೆಸರು, ನೋಂದಾಯಿತ ಕಚೇರಿ, ಉದ್ದೇಶಗಳು ಅಥವಾ ಗುರಿ, ಮತ್ತು ಅದಕ್ಕೆ ಅನುಮತಿ ಇರುವ ಚಟುವಟಿಕೆಗಳ ವ್ಯಾಪ್ತಿಯನ್ನು ವ್ಯಾಖ್ಯಾನಿಸುತ್ತದೆ. ಈ ದಾಖಲೆ ಅನುಮತಿಸುವುದರ ಹೊರತಾಗಿ ಕಂಪನಿ ಸಾಮಾನ್ಯವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸಲಾಗುವುದಿಲ್ಲ.',
  'articles-of-association':
    'ಕಂಪನಿಯನ್ನು ಹೇಗೆ ನಡೆಸಲಾಗುತ್ತದೆ ಎಂಬ ಆಂತರಿಕ ನಿಯಮಗಳನ್ನು ವಿವರಿಸುವ ದಾಖಲೆ, ಷೇರುದಾರರ ಹಕ್ಕುಗಳು, ನಿರ್ದೇಶಕರ ಅಧಿಕಾರಗಳು, ಮತ್ತು ಸಭೆಗಳನ್ನು ಹೇಗೆ ನಡೆಸಲಾಗುತ್ತದೆ ಎಂಬಂತಹ ವಿಷಯಗಳನ್ನು ಒಳಗೊಳ್ಳುತ್ತದೆ. ಇದು ಮೆಮೊರಾಂಡಮ್ ಆಫ್ ಅಸೋಸಿಯೇಶನ್‌ನೊಂದಿಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ ಆದರೆ ಕಂಪನಿಯ ಉದ್ದೇಶಕ್ಕಿಂತ ಆಂತರಿಕ ನಿರ್ವಹಣೆಯನ್ನು ನಿಭಾಯಿಸುತ್ತದೆ.',
  'share-transfer-deed':
    'ಕಂಪನಿಯ ಷೇರುಗಳನ್ನು ಒಬ್ಬ ಷೇರುದಾರರಿಂದ ಇನ್ನೊಬ್ಬರಿಗೆ ಔಪಚಾರಿಕವಾಗಿ ವರ್ಗಾಯಿಸಲು ಬಳಸುವ ನಿಗದಿತ ಫಾರ್ಮ್, ಫಾರ್ಮ್ SH-4. ಕಂಪನಿ ವರ್ಗಾವಣೆಯನ್ನು ನೋಂದಾಯಿಸುವ ಮೊದಲು ಇದನ್ನು ಸರಿಯಾಗಿ ಸ್ಟ್ಯಾಂಪ್ ಮಾಡಿ ವರ್ಗಾಹಕ ಮತ್ತು ಗ್ರಾಹಕ ಇಬ್ಬರೂ ಕಾರ್ಯಗತಗೊಳಿಸಬೇಕು.',
  'llp-agreement':
    'ಲಿಮಿಟೆಡ್ ಲಯಬಿಲಿಟಿ ಪಾರ್ಟ್ನರ್‌ಶಿಪ್‌ನ ಪಾರ್ಟ್ನರ್‌ಗಳ ನಡುವಿನ ಒಪ್ಪಂದ, ಮತ್ತು ಪಾರ್ಟ್ನರ್‌ಗಳು ಹಾಗೂ LLP ಸ್ವತಃ ನಡುವೆ, ಪ್ರತಿ ಪಾರ್ಟ್ನರ್‌ನ ಬಂಡವಾಳ ಕೊಡುಗೆ, ಲಾಭ-ಹಂಚಿಕೆ ಅನುಪಾತ, ಮತ್ತು ನಿರ್ವಹಣೆ ಹಕ್ಕುಗಳು ಮತ್ತು ಕಡ್ಡಾಯಗಳಂತಹ ವಿಷಯಗಳನ್ನು ಹೊಂದಿಸುತ್ತದೆ.',
  'registrar-of-companies':
    'ಕಾರ್ಪೊರೇಟ್ ವ್ಯವಹಾರಗಳ ಸಚಿವಾಲಯದ ಅಡಿಯಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುವ ಸರ್ಕಾರಿ ಅಧಿಕಾರಿ, ಒಂದು ನಿರ್ದಿಷ್ಟ ರಾಜ್ಯ ಅಥವಾ ಪ್ರದೇಶದಲ್ಲಿ ಕಂಪನಿಗಳು ಮತ್ತು LLPಗಳನ್ನು ನೋಂದಾಯಿಸಲು ಮತ್ತು ಅವುಗಳ ಮುಂದುವರಿಯುವ ಅನುಸರಣೆ ಫೈಲಿಂಗ್‌ಗಳ ಮೇಲ್ವಿಚಾರಣೆಗೆ ಹೊಣೆಗಾರ.',
  'director-identification-number':
    'ಭಾರತದಲ್ಲಿ ಕಂಪನಿಯ ನಿರ್ದೇಶಕರಾಗಿ ನೇಮಕಗೊಳ್ಳುವ ಮೊದಲು ಪ್ರತಿ ವ್ಯಕ್ತಿ ಪಡೆಯಬೇಕಾದ ವಿಶಿಷ್ಟ ಗುರುತಿನ ಸಂಖ್ಯೆ. ಈ ವ್ಯಕ್ತಿ ನಿರ್ದೇಶಕರಾಗಿರುವ ಎಲ್ಲಾ ಕಂಪನಿಗಳಲ್ಲಿ ಇದು ಅವರ ಜೊತೆ ಇರುತ್ತದೆ.',
  'winding-up':
    'ಕಂಪನಿಯನ್ನು ಮುಚ್ಚುವ ಕಾನೂನು ಪ್ರಕ್ರಿಯೆ, ಅದರ ಆಸ್ತಿಗಳನ್ನು ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ, ಅದರ ಸಾಲಗಳನ್ನು ಪಾವತಿಸಲಾಗುತ್ತದೆ, ಮತ್ತು ಯಾವುದೇ ಹೆಚ್ಚುವರಿಯನ್ನು ಅದರ ಷೇರುದಾರರಲ್ಲಿ ಹಂಚಲಾಗುತ್ತದೆ, ಕಂಪನಿ ಅಂತಿಮವಾಗಿ ವಿಸರ್ಜಿಸಿ ರಿಜಿಸ್ಟರ್‌ನಿಂದ ತೆಗೆದುಹಾಕುವ ಮೊದಲು.',
  'e-form':
    'ಕಾರ್ಪೊರೇಟ್ ವ್ಯವಹಾರಗಳ ಸಚಿವಾಲಯದ ಆನ್‌ಲೈನ್ ಪೋರ್ಟಲ್ ಮೂಲಕ ರಿಜಿಸ್ಟ್ರಾರ್ ಆಫ್ ಕಂಪನೀಸ್‌ಗೆ ದಾಖಲಿಸುವ ಎಲೆಕ್ಟ್ರಾನಿಕ್ ಫಾರ್ಮ್, ನಿರ್ದೇಶಕರನ್ನು ನೇಮಿಸುವುದು, ನೋಂದಾಯಿತ ಕಚೇರಿಯನ್ನು ಬದಲಾಯಿಸುವುದು, ಅಥವಾ ವಾರ್ಷಿಕ ಆದಾಯವನ್ನು ದಾಖಲಿಸುವಂತಹ ಸಾಮಾನ್ಯ ಅನುಸರಣೆ ಫೈಲಿಂಗ್‌ಗಳಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ.',
  'statutory-register':
    'ಕಂಪನಿ ಕಾನೂನುಬದ್ಧವಾಗಿ ನಿರ್ವಹಿಸಬೇಕಾದ ದಾಖಲೆ, ಅದರ ಷೇರುದಾರರ ಪಟ್ಟಿ, ನಿರ್ದೇಶಕರು, ಅಥವಾ ಅದರ ಆಸ್ತಿಗಳ ಮೇಲಿನ ಚಾರ್ಜ್‌ಗಳಂತಹ ನಿರ್ದಿಷ್ಟ ಮಾಹಿತಿಯನ್ನು ಹೊಂದಿದೆ. ಈ ರಿಜಿಸ್ಟರ್‌ಗಳನ್ನು ಅಪ್‌ಡೇಟ್ ಆಗಿ ಇಡಬೇಕು ಮತ್ತು ಕಾನೂನು ಅನುಮತಿಸುವ ಸಂದರ್ಭಗಳಲ್ಲಿ ಪರಿಶೀಲನೆಗೆ ತೆರೆದಿರುತ್ತದೆ.',
  'annual-general-meeting':
    'ಹೆಚ್ಚಿನ ಕಂಪನಿಗಳು ಪ್ರತಿ ಹಣಕಾಸು ವರ್ಷದಲ್ಲಿ ಒಮ್ಮೆ ನಡೆಸಬೇಕಾದ ಸಭೆ, ಷೇರುದಾರರು ಕಂಪನಿಯ ವಾರ್ಷಿಕ ಖಾತೆಗಳನ್ನು ಪರಿಶೀಲಿಸುತ್ತಾರೆ, ಡಿವಿಡೆಂಡ್ ಅನುಮೋದಿಸುತ್ತಾರೆ, ಮತ್ತು ನಿರ್ದೇಶಕರು ಮತ್ತು ಆಡಿಟರ್‌ಗಳನ್ನು ನೇಮಿಸುವಂತಹ ವಿಷಯಗಳನ್ನು ನಿಭಾಯಿಸುತ್ತಾರೆ.',
  'extraordinary-general-meeting':
    'ವಾರ್ಷಿಕ ಸಾಮಾನ್ಯ ಸಭೆಯ ಹೊರತಾಗಿ ನಡೆಸುವ ಕಂಪನಿಯ ಷೇರುದಾರರ ಯಾವುದೇ ಸಭೆ, ಮುಂದಿನ ವಾರ್ಷಿಕ ಸಭೆಯವರೆಗೆ ಕಾಯಲಾಗದ ತುರ್ತು ಅಥವಾ ನಿರ್ದಿಷ್ಟ ವಿಷಯಗಳನ್ನು ನಿರ್ಧರಿಸಲು ಕರೆಯಲಾಗುತ್ತದೆ.',
  'authorised-share-capital':
    'ಕಂಪನಿ ಷೇರುದಾರರಿಗೆ ನೀಡಲು ಅನುಮತಿ ಹೊಂದಿರುವ ಷೇರುಗಳ ಗರಿಷ್ಠ ಮೌಲ್ಯ, ಅದರ ಮೆಮೊರಾಂಡಮ್ ಆಫ್ ಅಸೋಸಿಯೇಶನ್‌ನಲ್ಲಿ ಹೇಳಿದಂತೆ. ಈ ಮಿತಿಗಿಂತ ಹೆಚ್ಚಿನ ಷೇರುಗಳನ್ನು ನೀಡುವ ಮೊದಲು ಕಂಪನಿ ಈ ಮಿತಿಯನ್ನು ಔಪಚಾರಿಕವಾಗಿ ಹೆಚ್ಚಿಸಬೇಕು.',
  'paid-up-share-capital':
    'ಷೇರುದಾರರು ಈವರೆಗೆ ಅವರಿಗೆ ನೀಡಲಾದ ಷೇರುಗಳಿಗೆ ಬದಲಾಗಿ ಕಂಪನಿಗೆ ವಾಸ್ತವವಾಗಿ ಪಾವತಿಸಿದ ಹಣದ ಮೊತ್ತ. ಇದು ಅಧಿಕೃತ ಷೇರು ಬಂಡವಾಳಕ್ಕಿಂತ ಕಡಿಮೆಯಾಗಬಹುದು, ಅದು ಕೇವಲ ಕಂಪನಿ ನೀಡಲು ಅನುಮತಿ ಇರುವ ಮೇಲಿನ ಮಿತಿ.',
  'certificate-of-incorporation':
    'ಕಂಪನಿ ಕಾನೂನುಬದ್ಧವಾಗಿ ರಚಿಸಲ್ಪಟ್ಟು ನೋಂದಾಯಿಸಲ್ಪಟ್ಟಿದೆ ಎಂದು ದೃಢೀಕರಿಸುವ, ರಿಜಿಸ್ಟ್ರಾರ್ ಆಫ್ ಕಂಪನೀಸ್ ನೀಡುವ ಅಧಿಕೃತ ಪ್ರಮಾಣಪತ್ರ. ಕಂಪನಿ ಕಾನೂನುಬದ್ಧವಾಗಿ, ತನ್ನ ಸ್ಥಾಪಕರಿಂದ ಪ್ರತ್ಯೇಕ ಘಟಕವಾಗಿ, ಈ ಪ್ರಮಾಣಪತ್ರದ ದಿನಾಂಕದಿಂದ ಅಸ್ತಿತ್ವಕ್ಕೆ ಬರುತ್ತದೆ.',
  'registered-office':
    'ರಿಜಿಸ್ಟ್ರಾರ್ ಆಫ್ ಕಂಪನೀಸ್‌ನ ದಾಖಲೆಯಲ್ಲಿ ಇರುವ ಕಂಪನಿಯ ಅಧಿಕೃತ ವಿಳಾಸ, ಕಾನೂನು ನೋಟಿಸ್‌ಗಳು ಮತ್ತು ಅಧಿಕೃತ ಸಂವಹನಗಳನ್ನು ಸ್ವೀಕರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ. ಇದು ಕಂಪನಿಯ ಮುಖ್ಯ ವ್ಯಾಪಾರ ಸ್ಥಳವಾಗಿರಬೇಕಾಗಿಲ್ಲ, ಆದರೆ ಕಂಪನಿ ಅಲ್ಲಿ ಸಂವಹನಗಳನ್ನು ಸ್ವೀಕರಿಸಲು ಸಾಧ್ಯವಾಗಬೇಕು.',
  'scheme-of-arrangement':
    'ಕಂಪನಿ ಮತ್ತು ಅದರ ಷೇರುದಾರರು ಅಥವಾ ಸಾಲದಾತರ ನಡುವಿನ ಜೋಡಣೆ, ವಿಲೀನ, ವಿಭಜನೆ, ಅಥವಾ ಸಾಲಗಳ ಮೇಲಿನ ಹೊಂದಾಣಿಕೆಯಂತಹ ಉದ್ದೇಶಗಳಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ, ನ್ಯಾಷನಲ್ ಕಂಪನಿ ಲಾ ಟ್ರಿಬ್ಯೂನಲ್ ಅನುಮೋದಿಸುತ್ತದೆ, ಮಂಜೂರಾದ ನಂತರ ಎಲ್ಲಾ ಪಕ್ಷಗಳ ಮೇಲೆ ಬಂಧಕವಾಗುತ್ತದೆ.',
  'private-company':
    'ಅದರ ಷೇರುಗಳನ್ನು ಸಾರ್ವಜನಿಕರಿಗೆ ಮುಕ್ತವಾಗಿ ನೀಡಲಾಗದ ಮತ್ತು ಅದರ ಆರ್ಟಿಕಲ್ಸ್ ಷೇರು ವರ್ಗಾವಣೆಯ ಹಕ್ಕನ್ನು ನಿರ್ಬಂಧಿಸುವ ಕಂಪನಿ, ಇದರ ಷೇರುಗಳನ್ನು ಮುಕ್ತವಾಗಿ ವ್ಯಾಪಾರ ಮಾಡಬಹುದಾದ, ಪಟ್ಟಿ ಮಾಡಿದ್ದರೆ ಸ್ಟಾಕ್ ಎಕ್ಸ್‌ಚೇಂಜ್‌ನಲ್ಲಿ ಖರೀದಿ ಮಾರಾಟ ಮಾಡಬಹುದಾದ ಪಬ್ಲಿಕ್ ಕಂಪನಿಗಿಂತ ಭಿನ್ನ.',
  'one-person-company':
    'ಒಂದೇ ವ್ಯಕ್ತಿ ರಚಿಸಿ ನಡೆಸಬಹುದಾದ ಕಂಪನಿಯ ಪ್ರಕಾರ, ಅವರು ಅದರ ಏಕೈಕ ಷೇರುದಾರರಾಗಿದ್ದರೂ, ವ್ಯವಹಾರಕ್ಕೆ ಪ್ರತ್ಯೇಕ ಕಾನೂನು ಘಟಕ ಮತ್ತು ಸೀಮಿತ ಹೊಣೆಗಾರಿಕೆಯ ಪ್ರಯೋಜನವನ್ನು ನೀಡುತ್ತದೆ.',
  'shareholder':
    'ಕಂಪನಿಯಲ್ಲಿ ಷೇರುಗಳನ್ನು ಹೊಂದಿರುವ ಮತ್ತು ಅಷ್ಟರ ಮಟ್ಟಿಗೆ ಅದರ ಮಾಲೀಕರಲ್ಲಿ ಒಬ್ಬರಾಗಿರುವ ವ್ಯಕ್ತಿ, ಸಾಮಾನ್ಯ ಸಭೆಗಳಲ್ಲಿ ಮತ ಚಲಾಯಿಸುವ ಮತ್ತು ಡಿವಿಡೆಂಡ್ ಪಡೆಯುವ ಹಕ್ಕುಗಳೊಂದಿಗೆ. ಕಂಪನಿಯ ಮೆಂಬರ್ ಎಂದೂ ಕರೆಯಲಾಗುತ್ತದೆ.',
  'director':
    'ಕಂಪನಿಯ ವ್ಯವಹಾರಗಳನ್ನು ನಿರ್ವಹಿಸಲು ಮತ್ತು ಅದರ ಪರವಾಗಿ ನಿರ್ಧಾರಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಲು ಮಂಡಳಿಗೆ ನೇಮಿಸಿದ ವ್ಯಕ್ತಿ, ಸದ್ಭಾವನೆಯಿಂದ ಮತ್ತು ಕಂಪನಿಯ ಹಿತಾಸಕ್ತಿಯಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುವ ಕಡ್ಡಾಯಗಳನ್ನು ಹೊಂದಿದೆ. ಕೇವಲ ಮಂಡಳಿ ಸಭೆಗಳಿಗೆ ಹಾಜರಾಗುವುದಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ನಿರ್ದಿಷ್ಟ ದಿನನಿತ್ಯದ ಕಾರ್ಯಗತ ಜವಾಬ್ದಾರಿಗಳನ್ನು ನೀಡಲಾದ ವ್ಯಕ್ತಿಯನ್ನು ಮ್ಯಾನೇಜಿಂಗ್ ಡೈರೆಕ್ಟರ್ ಅಥವಾ ಹೋಲ್-ಟೈಮ್ ಡೈರೆಕ್ಟರ್ ಎಂದು ಕರೆಯಲಾಗುತ್ತದೆ.',
  'company-secretary':
    'ಕಂಪನಿ ಕಾನೂನಿನ ಅನುಸರಣೆಗೆ ಹೊಣೆಗಾರ ಅರ್ಹ ವೃತ್ತಿಪರ, ಸ್ಟ್ಯಾಟ್ಯೂಟರಿ ರಿಜಿಸ್ಟರ್‌ಗಳನ್ನು ನಿರ್ವಹಿಸುವುದು, ಸಭೆಗಳನ್ನು ಸಂಘಟಿಸುವುದು, ಮತ್ತು ರಿಜಿಸ್ಟ್ರಾರ್ ಆಫ್ ಕಂಪನೀಸ್‌ಗೆ ಫೈಲಿಂಗ್‌ಗಳನ್ನು ಸಕಾಲಕ್ಕೆ ಮಾಡುವುದನ್ನು ಖಚಿತಪಡಿಸುವುದು ಸೇರಿದಂತೆ.',
  'auditor':
    'ಕಂಪನಿಯ ಆರ್ಥಿಕ ಹೇಳಿಕೆಗಳನ್ನು ಮತ್ತು ಲೆಕ್ಕಪತ್ರ ದಾಖಲೆಗಳನ್ನು ಪರೀಕ್ಷಿಸಲು, ಮತ್ತು ಅವು ಕಂಪನಿಯ ಹಣಕಾಸಿನ ಸ್ಥಿತಿಯ ನಿಜವಾದ ಮತ್ತು ನ್ಯಾಯಯುತ ಚಿತ್ರಣ ನೀಡುತ್ತವೆಯೇ ಎಂದು ಷೇರುದಾರರಿಗೆ ವರದಿ ಮಾಡಲು ಕಂಪನಿ ನೇಮಿಸಿದ ಸ್ವತಂತ್ರ, ಅರ್ಹ ವೃತ್ತಿಪರ.',
  'charge-company':
    'ಕಂಪನಿಯ ಆಸ್ತಿಗಳ ಮೇಲೆ, ಉದಾಹರಣೆಗೆ ಅದರ ಆಸ್ತಿ ಅಥವಾ ಪಡೆಯಬೇಕಾದ ಹಣ, ಸಾಲಕ್ಕೆ ಭದ್ರತೆಯಾಗಿ ಸಾಲದಾತನ ಪರವಾಗಿ ರಚಿಸಲಾದ ಹಕ್ಕು. ಇದು ಇತರರ ವಿರುದ್ಧ ಜಾರಿಗೊಳ್ಳಲು, ಕಂಪನಿ ಅದನ್ನು ನಿಗದಿತ ಸಮಯದೊಳಗೆ ರಿಜಿಸ್ಟ್ರಾರ್ ಆಫ್ ಕಂಪನೀಸ್‌ನೊಂದಿಗೆ ನೋಂದಾಯಿಸಬೇಕು.',
  'dividend':
    'ಕಂಪನಿ ತನ್ನ ಲಾಭದ ಭಾಗವನ್ನು ತನ್ನ ಷೇರುದಾರರಿಗೆ ವಿತರಿಸುವುದು, ಸಾಮಾನ್ಯವಾಗಿ ಅವರು ಹೊಂದಿರುವ ಷೇರುಗಳ ಅನುಪಾತದಲ್ಲಿ, ಸಾಮಾನ್ಯ ಸಭೆಯಲ್ಲಿ ಘೋಷಿಸಿದ ನಂತರ, ಅಥವಾ ಮಧ್ಯಂತರ ಡಿವಿಡೆಂಡ್‌ಗಾಗಿ, ಮಂಡಳಿಯಿಂದ.',
  'quorum':
    'ಮಂಡಳಿ ಸಭೆ, ವಾರ್ಷಿಕ ಸಾಮಾನ್ಯ ಸಭೆ, ಅಥವಾ ಅಸಾಧಾರಣ ಸಾಮಾನ್ಯ ಸಭೆಯಂತಹ ಸಭೆಯನ್ನು ಸಿಂಧುವಾಗಿ ನಡೆಸಲು ಮತ್ತು ಅದರ ನಿರ್ಧಾರಗಳು ಬಂಧಕವಾಗಲು ಹಾಜರಿರಬೇಕಾದ ಕಡಿಮೆ ಪಕ್ಷ ಮೆಂಬರ್‌ಗಳು ಅಥವಾ ನಿರ್ದೇಶಕರ ಸಂಖ್ಯೆ.',
  'proxy':
    'ಷೇರುದಾರರು ಸ್ವತಃ ಹಾಜರಾಗಲು ಅಸಮರ್ಥರಾದಾಗ, ಸಹಿ ಮಾಡಿದ ದಾಖಲೆಯ ಮೂಲಕ, ಸಾಮಾನ್ಯ ಸಭೆಗೆ ಹಾಜರಾಗಿ ಅವರ ಪರವಾಗಿ ಮತ ಚಲಾಯಿಸಲು ಅಧಿಕಾರ ಪಡೆದ ವ್ಯಕ್ತಿ.',
  'striking-off':
    'ರಿಜಿಸ್ಟ್ರಾರ್ ಆಫ್ ಕಂಪನೀಸ್ ನಿಷ್ಕ್ರಿಯ ಕಂಪನಿಯ ಹೆಸರನ್ನು ರಿಜಿಸ್ಟರ್‌ನಿಂದ ತೆಗೆದುಹಾಕುವ ಪ್ರಕ್ರಿಯೆ, ಕಂಪನಿಯ ಸ್ವಂತ ಫಾಸ್ಟ್-ಟ್ರ್ಯಾಕ್ ಎಕ್ಸಿಟ್ ಅರ್ಜಿಯ ಮೇಲೆ, ಅಥವಾ ಅದು ವ್ಯಾಪಾರ ನಡೆಸುತ್ತಿಲ್ಲ ಎಂದು ಕಂಡುಕೊಂಡಾಗ ರಿಜಿಸ್ಟ್ರಾರ್‌ನ ಸ್ವಂತ ಉಪಕ್ರಮದ ಮೇಲೆ.',
  'oppression-and-mismanagement':
    'ಷೇರುದಾರರಿಗೆ, ಮುಖ್ಯವಾಗಿ ಅಲ್ಪಸಂಖ್ಯಾತ ಷೇರುದಾರರಿಗೆ, ಕಂಪನಿಯ ವ್ಯವಹಾರಗಳನ್ನು ಅವರಿಗೆ ದಬ್ಬಾಳಿಕೆ ಅಥವಾ ಕಂಪನಿಯ ಸ್ವಂತ ಹಿತಾಸಕ್ತಿಗೆ ಹಾನಿಕಾರಕ ವಿಧಾನದಲ್ಲಿ ನಡೆಸಲಾಗುತ್ತಿದ್ದಲ್ಲಿ, ನ್ಯಾಷನಲ್ ಕಂಪನಿ ಲಾ ಟ್ರಿಬ್ಯೂನಲ್ ಅನ್ನು ಸಂಪರ್ಕಿಸಲು ಲಭ್ಯವಿರುವ ಪರಿಹಾರ.',
  'shareholders-agreement':
    'ಕಂಪನಿಯ ಕೆಲವು ಅಥವಾ ಎಲ್ಲಾ ಷೇರುದಾರರ ನಡುವಿನ ಖಾಸಗಿ ಒಪ್ಪಂದ, ಷೇರುಗಳನ್ನು ಹೇಗೆ ವರ್ಗಾಯಿಸಬಹುದು, ನಿರ್ದೇಶಕರನ್ನು ನೇಮಿಸುವ ಹಕ್ಕುಗಳು, ಮತ್ತು ಡೆಡ್‌ಲಾಕ್ ಉಂಟಾದರೆ ಏನಾಗುತ್ತದೆ ಎಂಬಂತಹ ವಿಷಯಗಳನ್ನು ಹೊಂದಿಸುತ್ತದೆ, ಆರ್ಟಿಕಲ್ಸ್ ಆಫ್ ಅಸೋಸಿಯೇಶನ್‌ನಲ್ಲಿ ದಾಖಲಿಸಿದ್ದನ್ನು ಮೀರಿ.',
  'sale-deed':
    'ಮಾರಾಟಗಾರನಿಂದ ಖರೀದಿದಾರನಿಗೆ ಬೆಲೆಗೆ ಬದಲಾಗಿ ಸ್ಥಿರ ಆಸ್ತಿಯ ಮಾಲೀಕತ್ವವನ್ನು ಔಪಚಾರಿಕವಾಗಿ ವರ್ಗಾಯಿಸುವ ಕಾನೂನು ದಾಖಲೆ. ಮಾಲೀಕತ್ವ ವರ್ಗಾವಣೆಯಲ್ಲಿ ಕಾನೂನುಬದ್ಧವಾಗಿ ಪರಿಣಾಮಕಾರಿಯಾಗಲು ಇದನ್ನು ಸರಿಯಾಗಿ ಸ್ಟ್ಯಾಂಪ್ ಮಾಡಿ ನೋಂದಾಯಿಸಬೇಕು.',
  'gift-deed':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿಯಿಂದ ಇನ್ನೊಬ್ಬರಿಗೆ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿ ಮತ್ತು ಯಾವುದೇ ಪಾವತಿ ಇಲ್ಲದೆ ಆಸ್ತಿಯ ಮಾಲೀಕತ್ವವನ್ನು ವರ್ಗಾಯಿಸುವ ಕಾನೂನು ದಾಖಲೆ. ಮಾರಾಟ ಪತ್ರದಂತೆ, ಕಾನೂನು ಪರಿಣಾಮ ಪಡೆಯಲು ಇದನ್ನು ಸರಿಯಾಗಿ ಸ್ಟ್ಯಾಂಪ್ ಮಾಡಿ ನೋಂದಾಯಿಸಬೇಕು.',
  'lease-deed':
    'ಆಸ್ತಿಯ ಮಾಲೀಕತ್ವವನ್ನು ವರ್ಗಾಯಿಸದೆ, ಬಾಡಿಗೆಗೆ ಬದಲಾಗಿ, ಒಪ್ಪಿದ ಅವಧಿಗೆ ಇನ್ನೊಬ್ಬ ವ್ಯಕ್ತಿಯ ಆಸ್ತಿಯನ್ನು ಆಕ್ರಮಿಸಿ ಬಳಸುವ ಹಕ್ಕನ್ನು ಒಂದು ವ್ಯಕ್ತಿಗೆ ನೀಡುವ ಕಾನೂನು ದಾಖಲೆ.',
  'mortgage-deed':
    'ಒಬ್ಬ ಆಸ್ತಿ ಮಾಲೀಕ ತಮ್ಮ ಆಸ್ತಿಯನ್ನು ಸಾಲ ಅಥವಾ ಇತರ ಸಾಲಕ್ಕೆ ಭದ್ರತೆಯಾಗಿ ಒತ್ತೆ ಇಡುವ ಕಾನೂನು ದಾಖಲೆ, ಸಾಲ ಮರುಪಾವತಿಸದಿದ್ದರೆ ಆ ಆಸ್ತಿಯ ಮೇಲೆ ಸಾಲದಾತನಿಗೆ ಕೆಲವು ಹಕ್ಕುಗಳನ್ನು ನೀಡುತ್ತದೆ, ಅದರ ಸ್ವಾಧೀನವನ್ನು ಕಡ್ಡಾಯವಾಗಿ ಬಿಟ್ಟುಕೊಡದೆ.',
  'general-power-of-attorney':
    'ಒಂದು ನಿರ್ದಿಷ್ಟ ಕಾರ್ಯಕ್ಕೆ ಸೀಮಿತವಾಗುವ ಬದಲು, ಆಸ್ತಿ ನಿರ್ವಹಣೆ, ಬ್ಯಾಂಕ್ ಖಾತೆಗಳ ನಿರ್ವಹಣೆ, ಮತ್ತು ಕಾನೂನು ವ್ಯವಹಾರಗಳನ್ನು ನಿಭಾಯಿಸುವಂತಹ ವ್ಯಾಪಕ ಶ್ರೇಣಿಯ ವಿಷಯಗಳಾದ್ಯಂತ, ಒಬ್ಬ ವ್ಯಕ್ತಿಯ ಪರವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸಲು ಇನ್ನೊಬ್ಬ ವ್ಯಕ್ತಿಗೆ ಅಧಿಕಾರ ನೀಡುವ ದಾಖಲೆ.',
  'special-power-of-attorney':
    'ಸಾಮಾನ್ಯ ವ್ಯವಹಾರಗಳಿಗೆ ಬದಲಾಗಿ, ನಿರ್ದಿಷ್ಟ ಆಸ್ತಿಯನ್ನು ಮಾರಾಟ ಮಾಡುವಂತಹ, ಕೇವಲ ಒಂದು ನಿರ್ದಿಷ್ಟ ಕಾರ್ಯ ಅಥವಾ ವಹಿವಾಟಿಗಾಗಿ, ಒಬ್ಬ ವ್ಯಕ್ತಿಯ ಪರವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸಲು ಇನ್ನೊಬ್ಬ ವ್ಯಕ್ತಿಗೆ ಅಧಿಕಾರ ನೀಡುವ ದಾಖಲೆ.',
  'stamp-duty':
    'ಸಾಮಾನ್ಯವಾಗಿ ಆಸ್ತಿಯ ಮೌಲ್ಯ ಅಥವಾ ವಹಿವಾಟು ಮೊತ್ತದ ಶೇಕಡಾವಾರು, ಮಾರಾಟ ಪತ್ರ ಅಥವಾ ಗುತ್ತಿಗೆ ಪತ್ರದಂತಹ ಕೆಲವು ದಾಖಲೆಗಳನ್ನು ಕಾರ್ಯಗತಗೊಳಿಸುವಾಗ ರಾಜ್ಯ ಸರ್ಕಾರಕ್ಕೆ ಪಾವತಿಸಬೇಕಾದ ತೆರಿಗೆ. ಸರಿಯಾದ ಸ್ಟ್ಯಾಂಪ್ ಡ್ಯೂಟಿ ಪಾವತಿಸದೆ, ಅಂತಹ ದಾಖಲೆಗಳನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಮಾನ್ಯ ಸಾಕ್ಷ್ಯವಾಗಿ ಬಳಸಲಾಗುವುದಿಲ್ಲ ಅಥವಾ ನೋಂದಾಯಿಸಲಾಗುವುದಿಲ್ಲ.',
  'registration-of-document':
    'ಮಾರಾಟ ಪತ್ರ ಅಥವಾ ದಾನ ಪತ್ರದಂತಹ ದಾಖಲೆಯನ್ನು ಸರ್ಕಾರದ ಸಬ್-ರಿಜಿಸ್ಟ್ರಾರ್ ಕಚೇರಿಯಲ್ಲಿ ದಾಖಲಿಸುವ ಔಪಚಾರಿಕ ಪ್ರಕ್ರಿಯೆ. ನೋಂದಣಿ ವಹಿವಾಟಿನ ಸಾರ್ವಜನಿಕ ದಾಖಲೆಯನ್ನು ಸೃಷ್ಟಿಸುತ್ತದೆ ಮತ್ತು, ಅನೇಕ ಪ್ರಕಾರದ ಆಸ್ತಿ ದಾಖಲೆಗಳಿಗೆ, ವರ್ಗಾವಣೆಯನ್ನು ಮಾನ್ಯಗೊಳಿಸಲು ಕಾನೂನುಬದ್ಧವಾಗಿ ಅಗತ್ಯವಾಗಿದೆ.',
  'encumbrance':
    'ಆಸ್ತಿಗೆ ಜೋಡಿಸಲಾದ ಹಕ್ಕು, ಹೊಣೆಗಾರಿಕೆ, ಅಥವಾ ನಿರ್ಬಂಧ, ಉದಾಹರಣೆಗೆ ಬಾಕಿ ಇರುವ ಅಡಮಾನ ಅಥವಾ ಬಾಕಿ ಇರುವ ಕಾನೂನು ವಿವಾದ, ಅದನ್ನು ಮುಕ್ತವಾಗಿ ಮಾರಾಟ ಮಾಡುವ ಅಥವಾ ವರ್ಗಾಯಿಸುವ ಮಾಲೀಕನ ಸಾಮರ್ಥ್ಯವನ್ನು ಬಾಧಿಸಬಹುದು.',
  'title-deed':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿಯ ಆಸ್ತಿಯ ಮಾಲೀಕತ್ವದ ಕಾನೂನು ಪುರಾವೆಯಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುವ ದಾಖಲೆ, ಉದಾಹರಣೆಗೆ ಅವರ ಹೆಸರಿನಲ್ಲಿರುವ ಮಾರಾಟ ಪತ್ರ ಅಥವಾ ದಾನ ಪತ್ರ. ಆಸ್ತಿ ಒಳಗೊಂಡ ಯಾವುದೇ ವಹಿವಾಟಿಗೆ ಮೊದಲು, ಆಸ್ತಿಯನ್ನು ಕಾನೂನುಬದ್ಧವಾಗಿ ಯಾರು ಹೊಂದಿದ್ದಾರೆ ಎಂದು ಖಚಿತಪಡಿಸಲು ಇದನ್ನು ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.',
  'consideration-in-a-deed':
    'ಡೀಡ್‌ನ ಅಡಿಯಲ್ಲಿ ವರ್ಗಾಯಿಸಲಾದ ಆಸ್ತಿ ಅಥವಾ ಹಕ್ಕಿಗೆ ಬದಲಾಗಿ ವಿನಿಮಯ ಮಾಡಿದ ಬೆಲೆ, ಪಾವತಿ, ಅಥವಾ ಪ್ರಯೋಜನ, ಉದಾಹರಣೆಗೆ ಆಸ್ತಿಗೆ ಪಾವತಿಸಿದ ಮಾರಾಟ ಬೆಲೆ. ಒಂದು ಡೀಡ್ ಒಳಗೊಂಡಿರುವ ಪ್ರತಿಫಲವನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಹೇಳಬೇಕು, ಅಥವಾ, ದಾನ ಪತ್ರದ ಸಂದರ್ಭದಲ್ಲಿ, ಯಾವುದೇ ಪ್ರತಿಫಲ ನೀಡಲಾಗಿಲ್ಲ ಎಂದು ಸ್ಪಷ್ಟವಾಗಿ ಹೇಳಬೇಕು.',
  'encumbrance-certificate':
    'ಒಂದು ನಿರ್ದಿಷ್ಟ ಅವಧಿಯಲ್ಲಿ ಆಸ್ತಿಗೆ ಅಡಮಾನಗಳು ಅಥವಾ ಬಾಕಿ ಇರುವ ಹೊಣೆಗಾರಿಕೆಗಳಂತಹ ಯಾವುದೇ ದಾಖಲಿತ ಹಕ್ಕುಭಾರಗಳಿವೆಯೇ ಎಂದು ದೃಢೀಕರಿಸುವ, ಸಬ್-ರಿಜಿಸ್ಟ್ರಾರ್ ಕಚೇರಿ ನೀಡುವ ಅಧಿಕೃತ ಪ್ರಮಾಣಪತ್ರ. ಮಾರಾಟಗಾರನಿಗೆ ಸ್ಪಷ್ಟ, ಮಾರಾಟ ಮಾಡಬಹುದಾದ ಹಕ್ಕು ಇದೆ ಎಂದು ಖಚಿತಪಡಿಸಲು ಆಸ್ತಿ ಖರೀದಿಸುವ ಮೊದಲು ಇದನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.',
  'mutation-of-property':
    'ಮಾರಾಟ ಅಥವಾ ಉತ್ತರಾಧಿಕಾರದ ನಂತರ ಆಸ್ತಿಯ ಮಾಲೀಕತ್ವದಲ್ಲಿ ಬದಲಾವಣೆಯನ್ನು ಪ್ರತಿಬಿಂಬಿಸಲು ಸರ್ಕಾರಿ ಕಂದಾಯ ದಾಖಲೆಗಳನ್ನು ಅಪ್‌ಡೇಟ್ ಮಾಡುವ ಪ್ರಕ್ರಿಯೆ. ಮ್ಯುಟೇಶನ್ ಸ್ವತಃ ಮಾಲೀಕತ್ವವನ್ನು ವರ್ಗಾಯಿಸುವುದಿಲ್ಲ, ಅದು ಮಾರಾಟ ಪತ್ರ ಅಥವಾ ಇತರ ದಾಖಲೆಯ ಮೂಲಕ ಸಂಭವಿಸುತ್ತದೆ, ಆದರೆ ಇದು ಆಸ್ತಿ ತೆರಿಗೆಯಂತಹ ಉದ್ದೇಶಗಳಿಗೆ ಅಧಿಕೃತ ಭೂ ದಾಖಲೆಗಳನ್ನು ಪ್ರಚಲಿತವಾಗಿ ಇಡುತ್ತದೆ.',
  'easement':
    'ಒಂದು ಆಸ್ತಿಯ ಮಾಲೀಕ, ಇನ್ನೊಬ್ಬ ವ್ಯಕ್ತಿಯ ಪಕ್ಕದ ಆಸ್ತಿಯನ್ನು ಸೀಮಿತ ಉದ್ದೇಶಕ್ಕಾಗಿ ಬಳಸುವ ಹಕ್ಕು, ಉದಾಹರಣೆಗೆ ರಸ್ತೆಗೆ ಪ್ರವೇಶಿಸಲು ಹಾದಿಯ ಹಕ್ಕು, ಅಥವಾ ಬೆಳಕು ಅಥವಾ ಗಾಳಿ ಪಡೆಯುವ ಹಕ್ಕು.',
  'lien':
    'ಇನ್ನೊಬ್ಬರ ಆಸ್ತಿಯನ್ನು ಹೊಂದಿರುವ, ಅಥವಾ ಅದಕ್ಕೆ ಸಂಬಂಧಿಸಿ ಹಣ ಬಾಕಿ ಇರುವ ವ್ಯಕ್ತಿ, ಸಾಲ ಅಥವಾ ಹಕ್ಕು ಇತ್ಯರ್ಥವಾಗುವವರೆಗೆ ಆ ಆಸ್ತಿಯ ಸ್ವಾಧೀನವನ್ನು ಉಳಿಸಿಕೊಳ್ಳುವ ಹಕ್ಕು.',
  'conveyance':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿಯಿಂದ ಇನ್ನೊಬ್ಬರಿಗೆ ಆಸ್ತಿಯ ಮಾಲೀಕತ್ವವನ್ನು ವರ್ಗಾಯಿಸುವ ಸಾಮಾನ್ಯ ಕಾನೂನು ಪದ, ಮತ್ತು ಆ ವರ್ಗಾವಣೆ ನಡೆಸುವ ಮಾರಾಟ ಪತ್ರದಂತಹ ದಾಖಲೆಗೂ ಬಳಸಲಾಗುತ್ತದೆ.',
  'relinquishment-deed':
    'ಆಸ್ತಿಯ ಸಹ-ಮಾಲೀಕ, ಇತರ ಒಬ್ಬ ಅಥವಾ ಹೆಚ್ಚಿನ ಸಹ-ಮಾಲೀಕರ ಪರವಾಗಿ ಅದರಲ್ಲಿ ತಮ್ಮ ಪಾಲನ್ನು ಬಿಟ್ಟುಕೊಡುವ ದಾಖಲೆ, ಹೆಚ್ಚಾಗಿ ಸಂಬಂಧಿಕರಲ್ಲಿ ಉತ್ತರಾಧಿಕಾರವಾಗಿ ಬಂದ ಕುಟುಂಬ ಆಸ್ತಿಯನ್ನು ಇತ್ಯರ್ಥಗೊಳಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.',
  'will':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿ ತಮ್ಮ ಮರಣದ ನಂತರ ತಮ್ಮ ಆಸ್ತಿಯನ್ನು ಹೇಗೆ ಹಂಚಬೇಕು ಎಂದು ವಿವರಿಸುವ ಕಾನೂನು ದಾಖಲೆ. ಇದು ಸಾಮಾನ್ಯವಾಗಿ ರಚಿಸಿದವರ ಮರಣದ ಮೇಲೆ ಮಾತ್ರ ಜಾರಿಗೆ ಬರುತ್ತದೆ ಮತ್ತು ಅದಕ್ಕೆ ಮೊದಲು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಅವರು ಅದನ್ನು ಬದಲಾಯಿಸಬಹುದು ಅಥವಾ ರದ್ದುಗೊಳಿಸಬಹುದು.',
  'probate':
    'ಒಂದು ಇಚ್ಛಾಪತ್ರ ನಿಜವಾದ ಮತ್ತು ಮಾನ್ಯವಾಗಿದೆ ಎಂದು ದೃಢೀಕರಿಸುವ, ಮತ್ತು ಅದರಲ್ಲಿ ಹೆಸರಿಸಲಾದ ಎಕ್ಸಿಕ್ಯೂಟರ್‌ಗೆ ಮೃತರ ಆಸ್ತಿಯನ್ನು ಅದಕ್ಕೆ ಅನುಗುಣವಾಗಿ ನಿರ್ವಹಿಸಲು ಅಧಿಕಾರ ನೀಡುವ, ಸಕ್ಷಮ ನ್ಯಾಯಾಲಯ ನೀಡುವ ಪ್ರಮಾಣಪತ್ರ.',
  'succession-certificate':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿ ಇಚ್ಛಾಪತ್ರವಿಲ್ಲದೆ ಮೃತರಾದಾಗ, ಮೃತರಿಗೆ ಬಾಕಿ ಇರುವ ಬ್ಯಾಂಕ್ ಬಾಕಿ ಅಥವಾ ಷೇರುಗಳಂತಹ ಸಾಲಗಳು ಮತ್ತು ಸೆಕ್ಯುರಿಟಿಗಳನ್ನು ಸಂಗ್ರಹಿಸಲು, ಮತ್ತು ಮಾನ್ಯ ರಸೀದಿ ನೀಡಲು ಅಥವಾ ಅವುಗಳನ್ನು ವರ್ಗಾಯಿಸಲು, ಹೊಂದಿರುವವರಿಗೆ ಅಧಿಕಾರ ನೀಡುವ, ನ್ಯಾಯಾಲಯ ನೀಡುವ ಪ್ರಮಾಣಪತ್ರ.',
  'letters-of-administration':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿ ಇಚ್ಛಾಪತ್ರವಿಲ್ಲದೆ ಅಥವಾ ಎಕ್ಸಿಕ್ಯೂಟರ್ ಹೆಸರಿಸದೆ ಮೃತರಾದಾಗ, ಮೃತರ ಆಸ್ತಿಯನ್ನು ಸಂಗ್ರಹಿಸಲು, ನಿರ್ವಹಿಸಲು, ಮತ್ತು ಹಂಚಲು ಆಡಳಿತಾಧಿಕಾರಿಯನ್ನು ನೇಮಿಸುವ, ನ್ಯಾಯಾಲಯ ನೀಡುವ ಅಧಿಕಾರ.',
  'legal-heir-certificate':
    'ಮೃತ ವ್ಯಕ್ತಿಯ ಕಾನೂನು ವಾರಸುದಾರರನ್ನು ಗುರುತಿಸುವ, ಕಂದಾಯ ಅಥವಾ ಪಾಲಿಕೆ ಪ್ರಾಧಿಕಾರ ನೀಡುವ ಪ್ರಮಾಣಪತ್ರ, ಸಾಮಾನ್ಯವಾಗಿ ಯುಟಿಲಿಟಿ ಸಂಪರ್ಕಗಳ ವರ್ಗಾವಣೆ ಅಥವಾ ಸಣ್ಣ ಬಾಕಿಗಳ ಕ್ಲೈಮ್‌ನಂತಹ ಸರಳ ಉದ್ದೇಶಗಳಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ, ದೊಡ್ಡ ಅಥವಾ ವಿವಾದಿತ ಹಕ್ಕುಗಳಿಗೆ ಉತ್ತರಾಧಿಕಾರ ಪ್ರಮಾಣಪತ್ರಕ್ಕೆ ವೇಗದ ಪರ್ಯಾಯವಾಗಿ.',
  'khata-patta':
    'ಸ್ಥಳೀಯ ಪಾಲಿಕೆ ಅಥವಾ ಕಂದಾಯ ಪ್ರಾಧಿಕಾರ ನಿರ್ವಹಿಸುವ ದಾಖಲೆ, ಖಾತಾ ಅಥವಾ ಪಟ್ಟಾದಂತಹ ವಿವಿಧ ರಾಜ್ಯಗಳಲ್ಲಿ ವಿವಿಧ ಹೆಸರುಗಳಿಂದ ಗುರುತಿಸಲಾಗುತ್ತದೆ, ಆಸ್ತಿ ತೆರಿಗೆ ಮೌಲ್ಯಮಾಪನದಂತಹ ಉದ್ದೇಶಗಳಿಗೆ ಒಂದು ನಿರ್ದಿಷ್ಟ ಆಸ್ತಿಯ ವಿರುದ್ಧ ಒಬ್ಬ ವ್ಯಕ್ತಿಯ ಹೆಸರನ್ನು ತೋರಿಸುತ್ತದೆ. ಇದು ಈ ಪ್ರಾಧಿಕಾರಗಳ ಸ್ವಂತ ಸ್ವಾಧೀನ ಅಥವಾ ತೆರಿಗೆ ಹೊಣೆಗಾರಿಕೆಯ ಗುರುತಿಸುವಿಕೆಯ ದಾಖಲೆಯಾಗಿದೆ, ಸ್ವತಃ ಮಾಲೀಕತ್ವದ ಪುರಾವೆಯಲ್ಲ.',
  'adverse-possession':
    'ನಿಜವಾದ ಮಾಲೀಕನ ಅನುಮತಿ ಇಲ್ಲದೆ, ಇನ್ನೊಬ್ಬರ ಆಸ್ತಿಯನ್ನು ಬಹಿರಂಗ, ನಿರಂತರ, ಮತ್ತು ಪ್ರತಿಕೂಲ ಸ್ವಾಧೀನದಲ್ಲಿ ಸಾಕಷ್ಟು ಅವಧಿಗೆ ಹೊಂದಿದ್ದ ವ್ಯಕ್ತಿ, ಅದಕ್ಕೆ ಕಾನೂನು ಹಕ್ಕು ಪಡೆದು ಮೂಲ ಮಾಲೀಕನ ಹಕ್ಕನ್ನು ಸೋಲಿಸಬಹುದಾದ ಕಾನೂನು ಸಿದ್ಧಾಂತ.',
  'benami-transaction':
    'ಆಸ್ತಿಯನ್ನು ಒಬ್ಬ ವ್ಯಕ್ತಿಯ ಹೆಸರಿನಲ್ಲಿ ಖರೀದಿಸುವ, ಆದರೆ ಅದರ ಹಣವನ್ನು ವಾಸ್ತವವಾಗಿ ಅದರ ಪ್ರಯೋಜನಗಳನ್ನು ಅನುಭವಿಸುವ ಇನ್ನೊಬ್ಬ ವ್ಯಕ್ತಿ ಪಾವತಿಸುವ ವಹಿವಾಟು, ದಾಖಲೆಗಳಲ್ಲಿ ಹೆಸರಿಸಲಾದ ವ್ಯಕ್ತಿ ಕೇವಲ ನಿಜವಾದ ಖರೀದಿದಾರನಿಗಾಗಿ ಅದನ್ನು ಹೊಂದಿದ್ದಾರೆ. ಅಂತಹ ವಹಿವಾಟುಗಳನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ನಿಷೇಧಿಸಲಾಗಿದೆ ಮತ್ತು ಕಾನೂನು ಗುರುತಿಸುವ ಸೀಮಿತ ವಿನಾಯಿತಿಗಳಿಗೆ ಒಳಪಟ್ಟು, ಸರ್ಕಾರ ಆಸ್ತಿಯನ್ನು ಮುಟ್ಟುಗೋಲು ಹಾಕಿಕೊಳ್ಳಬಹುದು.',
  'landlord-and-tenant':
    'ಭೂಮಾಲೀಕ ಆಸ್ತಿಯ ಮಾಲೀಕ, ಗುತ್ತಿಗೆ ಅಥವಾ ಬಾಡಿಗೆ ಒಪ್ಪಂದದ ಅಡಿಯಲ್ಲಿ, ಮಾಲೀಕತ್ವವನ್ನು ವರ್ಗಾಯಿಸದೆ, ಬಾಡಿಗೆಗೆ ಬದಲಾಗಿ ಒಪ್ಪಿದ ಅವಧಿಗೆ ಇನ್ನೊಬ್ಬ ವ್ಯಕ್ತಿ, ಬಾಡಿಗೆದಾರ, ಅದನ್ನು ಆಕ್ರಮಿಸಿ ಬಳಸಲು ಅನುಮತಿಸುತ್ತಾರೆ.',
  'mortgagor-and-mortgagee':
    'ಅಡಮಾನದಾರ (ಮಾರ್ಟ್‌ಗೇಜರ್) ಅಡಮಾನ ಪತ್ರದ ಅಡಿಯಲ್ಲಿ ಸಾಲಕ್ಕೆ ಭದ್ರತೆಯಾಗಿ ತಮ್ಮ ಆಸ್ತಿಯನ್ನು ಒತ್ತೆ ಇಡುವ ಮಾಲೀಕ. ಅಡಮಾನಗ್ರಾಹಕ (ಮಾರ್ಟ್‌ಗೇಜಿ) ಆ ಭದ್ರತೆಯನ್ನು ಯಾರ ಪರವಾಗಿ ಸೃಷ್ಟಿಸಲಾಗಿದೆಯೋ ಆ ಸಾಲದಾತ, ಮತ್ತು ಅಡಮಾನದಾರ ಸಾಲ ಮರುಪಾವತಿಸಲು ವಿಫಲರಾದರೆ ಆಸ್ತಿಯ ಮೇಲೆ ತಮ್ಮ ಹಕ್ಕುಗಳನ್ನು ಜಾರಿಗೊಳಿಸಬಹುದು.',
  'attestation':
    'ಇಚ್ಛಾಪತ್ರ ಅಥವಾ ಕೆಲವು ಡೀಡ್‌ಗಳಂತಹ ದಾಖಲೆಗೆ, ವ್ಯಕ್ತಿ ಅದನ್ನು ಕಾರ್ಯಗತಗೊಳಿಸಿದ್ದನ್ನು ಮತ್ತು ಸಹಿ ನಿಜವಾಗಿದೆ ಎಂದು ದೃಢೀಕರಿಸುವ ಸಾಕ್ಷಿಗಳ ಸಹಿ. ಕೆಲವು ದಾಖಲೆಗಳು ಅಗತ್ಯವಿರುವ ಸಂಖ್ಯೆಯ ಸಾಕ್ಷಿಗಳಿಂದ ಪ್ರಮಾಣೀಕರಿಸಲ್ಪಟ್ಟರೆ ಮಾತ್ರ ಕಾನೂನುಬದ್ಧವಾಗಿ ಮಾನ್ಯವಾಗಿವೆ.',
  'circle-rate':
    'ರಾಜ್ಯ ಸರ್ಕಾರ ಅಧಿಸೂಚಿಸಿದಂತೆ, ಒಂದು ನಿರ್ದಿಷ್ಟ ಪ್ರದೇಶದಲ್ಲಿರುವ ಆಸ್ತಿ ಪ್ರತಿ ಯುನಿಟ್ ಪ್ರದೇಶಕ್ಕೆ ಅಧಿಕೃತವಾಗಿ ಹೊಂದಿದೆ ಎಂದು ಭಾವಿಸಲಾದ ಕನಿಷ್ಠ ಮೌಲ್ಯ, ಪಕ್ಷಗಳ ನಡುವೆ ಒಪ್ಪಿದ ವಾಸ್ತವ ಮಾರಾಟ ಬೆಲೆ ಕಡಿಮೆಯಿದ್ದರೂ, ಸ್ಟ್ಯಾಂಪ್ ಡ್ಯೂಟಿ ಲೆಕ್ಕಹಾಕಲು ಕೆಳಮಿತಿಯಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ.',
  'res-judicata':
    'ಸಕ್ಷಮ ನ್ಯಾಯಾಲಯ ಒಮ್ಮೆ ಅದೇ ಪಕ್ಷಗಳ ನಡುವೆ ಒಂದು ವಿಷಯವನ್ನು ಅಂತಿಮವಾಗಿ ನಿರ್ಧರಿಸಿದ ನಂತರ, ಅದನ್ನು ಮತ್ತೆ ಮೊಕದ್ದಮೆ ಮಾಡುವುದನ್ನು ತಡೆಯುವ ನಿಯಮ. ಈಗಾಗಲೇ ನಿರ್ಣಾಯಕವಾಗಿ ಬಗೆಹರಿದ ವಿಷಯಗಳ ಅಂತ್ಯವಿಲ್ಲದ ಮರು-ಮೊಕದ್ದಮೆಯನ್ನು ಇದು ತಡೆಯುತ್ತದೆ.',
  'sub-judice':
    'ಪ್ರಸ್ತುತ ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಬಾಕಿ ಇರುವ ಮತ್ತು ಇನ್ನೂ ನಿರ್ಧರಿಸದ ವಿಷಯ. sub judice ವಿಷಯದ ಬಗ್ಗೆ ಸಾರ್ವಜನಿಕವಾಗಿ ಕಾಮೆಂಟ್ ಮಾಡುವುದು ಅಥವಾ ಮುಂಚಿತವಾಗಿ ತೀರ್ಪು ನೀಡುವುದು ಕೆಲವೊಮ್ಮೆ ನ್ಯಾಯಾಂಗ ನಿಂದನೆಗೆ ಸಮನಾಗಬಹುದು.',
  'ultra-vires':
    'ಅದನ್ನು ಮಾಡುವ ವ್ಯಕ್ತಿ ಅಥವಾ ಸಂಸ್ಥೆಯ ಕಾನೂನು ಅಧಿಕಾರ ಅಥವಾ ಅಧಿಕಾರವ್ಯಾಪ್ತಿಯ ಹೊರತಾಗಿ ಮಾಡಿದ ಕೃತ್ಯ, ಉದಾಹರಣೆಗೆ ಕಂಪನಿ ತನ್ನ ಮೆಮೊರಾಂಡಮ್ ಆಫ್ ಅಸೋಸಿಯೇಶನ್‌ನಲ್ಲಿ ಹೇಳಿದ ಉದ್ದೇಶಗಳ ಹೊರತಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುವುದು, ಅಥವಾ ಸರ್ಕಾರಿ ಪ್ರಾಧಿಕಾರ ಕಾನೂನು ನೀಡಿದ ಅಧಿಕಾರಗಳನ್ನು ಮೀರುವುದು. ಒಂದು ultra vires ಕೃತ್ಯವನ್ನು ಸಾಮಾನ್ಯವಾಗಿ ಅಮಾನ್ಯವೆಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ.',
  'mens-rea':
    'ಉದ್ದೇಶ ಅಥವಾ ಜ್ಞಾನದಂತಹ ಅಪರಾಧಿ ಮಾನಸಿಕ ಸ್ಥಿತಿ, ಒಂದು ಕೃತ್ಯ ಅಪರಾಧವೆಂದು ಪರಿಗಣಿಸಲ್ಪಡಲು ಒಬ್ಬ ವ್ಯಕ್ತಿ ಅದನ್ನು ಮಾಡುವಾಗ ಸಾಮಾನ್ಯವಾಗಿ ಹೊಂದಿರಬೇಕಾಗುತ್ತದೆ. ಹೆಚ್ಚಿನ ಕ್ರಿಮಿನಲ್ ಅಪರಾಧಗಳಿಗೆ, ಅಭಿಯೋಜನೆ ಅಪರಾಧಿ ಕೃತ್ಯ ಮತ್ತು ಈ ಅಪರಾಧಿ ಮನಸ್ಸನ್ನು ಎರಡನ್ನೂ ಸಾಬೀತುಪಡಿಸಬೇಕು.',
  'actus-reus':
    'ಅಪರಾಧವನ್ನು ರಚಿಸುವ ದೈಹಿಕ ಕೃತ್ಯ ಅಥವಾ ನಡವಳಿಕೆ, ಅದರ ಹಿಂದಿನ ಮಾನಸಿಕ ಸ್ಥಿತಿಯಾದ mens rea ಗಿಂತ ಭಿನ್ನ. ಹೆಚ್ಚಿನ ಅಪರಾಧಗಳಿಗೆ, ಆರೋಪಿ ವಾಸ್ತವವಾಗಿ ಈ ಅಪರಾಧಿ ಕೃತ್ಯವನ್ನು ಮಾಡಿದ್ದಾರೆ ಎಂದು ಅಭಿಯೋಜನೆ ಸಾಬೀತುಪಡಿಸಬೇಕು.',
  'audi-alteram-partem':
    'ಮೊದಲು ಆಲಿಸಲ್ಪಡಲು ಮತ್ತು ತಮ್ಮ ಪಕ್ಷವನ್ನು ಮಂಡಿಸಲು ನ್ಯಾಯಸಮ್ಮತ ಅವಕಾಶ ನೀಡದೆ ಯಾರನ್ನೂ ತೀರ್ಪು ನೀಡಬಾರದು ಅಥವಾ ಶಿಕ್ಷಿಸಬಾರದು ಎಂಬ ತತ್ವ. ನ್ಯಾಯಾಲಯಗಳು ಮತ್ತು ನ್ಯಾಯಮಂಡಳಿಗಳು ಅನುಸರಿಸುವ ಸ್ವಾಭಾವಿಕ ನ್ಯಾಯದ ಮೂಲ ನಿಯಮಗಳಲ್ಲಿ ಒಂದು.',
  'caveat-emptor':
    'ಖರೀದಿಯನ್ನು ಪೂರ್ಣಗೊಳಿಸುವ ಮೊದಲು ಖರೀದಿಸುತ್ತಿರುವ ವಸ್ತುವಿನ ಗುಣಮಟ್ಟ ಮತ್ತು ಸ್ಥಿತಿಯನ್ನು ಪರಿಶೀಲಿಸುವ ಹೊಣೆ ಖರೀದಿದಾರನದ್ದಾಗಿದೆ ಎಂಬ ತತ್ವ. ಮಾರಾಟಗಾರರ ಮೇಲೂ ಕಡ್ಡಾಯಗಳನ್ನು ಹೇರುವ ಗ್ರಾಹಕ ಸಂರಕ್ಷಣೆ ಕಾನೂನಿನಿಂದ ಭಾರತದಲ್ಲಿ ಇದರ ಅನ್ವಯವನ್ನು ಗಣನೀಯವಾಗಿ ಸಂಕುಚಿತಗೊಳಿಸಲಾಗಿದೆ.',
  'bona-fide':
    'ಪ್ರಾಮಾಣಿಕವಾಗಿ, ಸದ್ಭಾವನೆಯಿಂದ, ಮತ್ತು ಮೋಸ ಮಾಡುವ ಯಾವುದೇ ಉದ್ದೇಶವಿಲ್ಲದೆ ಮಾಡಿದ. ವಿವಾದಗಳನ್ನು ನಿರ್ಧರಿಸುವಾಗ, ವಿಶೇಷವಾಗಿ ಪ್ರಾಮಾಣಿಕತೆ ಅಥವಾ ನಿಜವಾದ ನಂಬಿಕೆ ಫಲಿತಾಂಶವನ್ನು ಬಾಧಿಸುವಲ್ಲಿ, ಒಂದು ಪಕ್ಷದ ನಡವಳಿಕೆ bona fide ಆಗಿತ್ತೇ ಎಂದು ನ್ಯಾಯಾಲಯಗಳು ಹೆಚ್ಚಾಗಿ ಪರಿಗಣಿಸುತ್ತವೆ.',
  'mala-fide':
    'bona fide ನಡವಳಿಕೆಗೆ ವಿರುದ್ಧವಾಗಿ, ಅಪ್ರಾಮಾಣಿಕ ಅಥವಾ ಅಸಮರ್ಪಕ ಉದ್ದೇಶದಿಂದ, ದುರ್ಭಾವನೆಯಿಂದ ಮಾಡಿದ. ವ್ಯಕ್ತಿಗತ ದ್ವೇಷ ತೀರಿಸಲು ಮಾಡಿದ ಅಧಿಕೃತ ನಿರ್ಧಾರದಂತಹ, mala fide ಆಗಿ ತೆಗೆದುಕೊಂಡ ಕ್ರಮ, ಅದು ತಾಂತ್ರಿಕವಾಗಿ ಆ ವ್ಯಕ್ತಿಯ ಅಧಿಕಾರದಲ್ಲಿದ್ದರೂ, ನ್ಯಾಯಾಲಯ ರದ್ದುಗೊಳಿಸಬಹುದು.',
  'prima-facie':
    'ಅದರ ಮುಖಭಾಗದಲ್ಲಿ, ಅಥವಾ ಲಭ್ಯ ವಸ್ತುಗಳ ಮೊದಲ ನೋಟದ ಆಧಾರದ ಮೇಲೆ, ವಿಷಯವನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ವಿವರವಾಗಿ ಪರಿಶೀಲಿಸುವ ಮೊದಲು. ನೋಟಿಸ್ ನೀಡುವುದು ಅಥವಾ ಮಧ್ಯಂತರ ಆದೇಶ ನೀಡುವಂತಹ ಕೆಲವು ಹಂತಗಳನ್ನು ಕೈಗೊಳ್ಳುವ ಮೊದಲು, ಒಂದು prima facie ಪ್ರಕರಣ ಇದೆ ಎಂದು ನ್ಯಾಯಾಲಯ ಹೆಚ್ಚಾಗಿ ತೃಪ್ತರಾಗಬೇಕಾಗುತ್ತದೆ.',
  'suo-motu':
    'ಯಾರೂ ಕ್ರಮ ಕೈಗೊಳ್ಳಬೇಕೆಂದು ಔಪಚಾರಿಕ ಮನವಿ ಅಥವಾ ದೂರು ದಾಖಲಿಸದೆ, ನ್ಯಾಯಾಲಯ ಅಥವಾ ಪ್ರಾಧಿಕಾರ ತನ್ನ ಸ್ವಂತ ಉಪಕ್ರಮದ ಮೇಲೆ ತೆಗೆದುಕೊಳ್ಳುವ ಕ್ರಮ.',
  'obiter-dicta':
    'ಪ್ರಕರಣ ನಿರ್ಧರಿಸಲು ಅಗತ್ಯವಲ್ಲದ, ನ್ಯಾಯಾಧೀಶರು ತೀರ್ಪಿನಲ್ಲಿ ಮಾಡುವ ಟಿಪ್ಪಣಿಗಳು ಅಥವಾ ಅವಲೋಕನಗಳು, ನಿರ್ಧಾರದ ಬಂಧಕ ಭಾಗವನ್ನು ವಾಸ್ತವವಾಗಿ ರಚಿಸುವ ತರ್ಕವಾದ ratio decidendi ಗಿಂತ ಭಿನ್ನ. Obiter dicta ನಂತರದ ಪ್ರಕರಣಗಳಲ್ಲಿ ಪ್ರಭಾವಶಾಲಿಯಾಗಬಹುದು ಆದರೆ ಪೂರ್ವನಿದರ್ಶನವಾಗಿ ಬಂಧಕವಲ್ಲ.',
  'ratio-decidendi':
    'ಒಂದು ಪ್ರಕರಣದಲ್ಲಿ ತನ್ನ ನಿರ್ಧಾರ ತಲುಪಲು ನ್ಯಾಯಾಲಯ ಅವಲಂಬಿಸುವ ಮೂಲ ಕಾನೂನು ತರ್ಕ ಮತ್ತು ತತ್ವ, ಪ್ರಾಸಂಗಿಕ ಟಿಪ್ಪಣಿಗಳಾದ obiter dicta ಗಿಂತ ಭಿನ್ನ. ತೀರ್ಪಿನಲ್ಲಿ ಪ್ರತಿ ಹೇಳಿಕೆಯಲ್ಲ, ಈ ತರ್ಕವೇ, ನಂತರದ ಪ್ರಕರಣಗಳಿಗೆ ಬಂಧಕ ಪೂರ್ವನಿದರ್ಶನವನ್ನು ರಚಿಸುತ್ತದೆ.',
  'ab-initio':
    'ಆರಂಭದಿಂದಲೇ. ಒಪ್ಪಂದ ಅಥವಾ ನೇಮಕಾತಿಯಂತಹ ಒಂದು ವಿಷಯ, ನ್ಯಾಯಾಲಯ ನಂತರ ಹಾಗೆ ಘೋಷಿಸಿದಾಗಿನಿಂದ ಮಾತ್ರವಲ್ಲ, ಅದನ್ನು ಸೃಷ್ಟಿಸಿದ ಕ್ಷಣದಿಂದಲೇ ಅಮಾನ್ಯ ಅಥವಾ ನಿರಾಕೃತ ಎಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ ಎಂದು ವಿವರಿಸಲು ಹೆಚ್ಚಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ.',
  'in-personam':
    'ಒಂದು ನಿರ್ದಿಷ್ಟ ವ್ಯಕ್ತಿಯ ವಿರುದ್ಧ ನಿರ್ದೇಶಿಸಲಾದ, ಕೇವಲ ಆ ವ್ಯಕ್ತಿಗೆ ಬಂಧಕವಾಗಿರುವ ಹಕ್ಕು ಅಥವಾ ನ್ಯಾಯಾಲಯದ ಆದೇಶ, ಪ್ರಪಂಚದಾದ್ಯಂತ ನಿರ್ದೇಶಿಸಲಾದ in rem ಹಕ್ಕಿಗೆ ವಿರುದ್ಧ.',
  'in-rem':
    'ಆಸ್ತಿ ಅಥವಾ ಸ್ಥಿತಿಯಂತಹ ವಸ್ತುವಿಗೆ ಸಂಬಂಧಿಸಿದ, ಪ್ರಪಂಚದಾದ್ಯಂತ ಬಂಧಕವಾಗಿರುವ ಹಕ್ಕು ಅಥವಾ ನ್ಯಾಯಾಲಯದ ಆದೇಶ, ಕೇವಲ ಒಂದು ನಿರ್ದಿಷ್ಟ ವ್ಯಕ್ತಿಗೆ ಬಂಧಕವಾಗಿರುವ in personam ಹಕ್ಕಿಗೆ ವಿರುದ್ಧ.',
  'per-incuriam':
    'ಜಾಗ್ರತೆಯ ಕೊರತೆಯಿಂದ ನೀಡಿದ ನಿರ್ಧಾರ, ಸಾಮಾನ್ಯವಾಗಿ ನ್ಯಾಯಾಲಯ ಅನ್ವಯಿಸಬೇಕಾಗಿದ್ದ ಬಂಧಕ ಪೂರ್ವನಿದರ್ಶನ ಅಥವಾ ಸಂಬಂಧಿತ ಶಾಸನಬದ್ಧ ನಿಬಂಧನೆಯನ್ನು ಕಡೆಗಣಿಸಿದ ಕಾರಣ. per incuriam ಎಂದು ಕಂಡುಬರುವ ತೀರ್ಪನ್ನು ಆ ಅಂಶದ ಮೇಲೆ ಬಂಧಕ ಪೂರ್ವನಿದರ್ಶನವೆಂದು ಪರಿಗಣಿಸಲಾಗುವುದಿಲ್ಲ.',
  'stare-decisis':
    'ಪ್ರತಿ ಸಮಾನ ಪ್ರಕರಣವನ್ನು ಹೊಸದಾಗಿ ನಿರ್ಧರಿಸುವ ಬದಲು, ನ್ಯಾಯಾಲಯಗಳು ಹಿಂದಿನ ನಿರ್ಧಾರಗಳು, ವಿಶೇಷವಾಗಿ ಉನ್ನತ ನ್ಯಾಯಾಲಯಗಳ ನಿರ್ಧಾರಗಳು, ಹಾಕಿದ ಪೂರ್ವನಿದರ್ಶನಗಳನ್ನು ಅನುಸರಿಸಬೇಕು ಎಂಬ ತತ್ವ. ಕಾನೂನನ್ನು ಅನ್ವಯಿಸುವ ವಿಧಾನದಲ್ಲಿ ಇದು ಸ್ಥಿರತೆ ಮತ್ತು ಊಹನೀಯತೆಯನ್ನು ಉತ್ತೇಜಿಸುತ್ತದೆ.',
  'habeas-corpus':
    'ಸಂವಿಧಾನದ 32ನೇ ಅಥವಾ 226ನೇ ವಿಧಿಯ ಅಡಿಯಲ್ಲಿ ನೀಡಿದ ರಿಟ್, ಒಬ್ಬ ವ್ಯಕ್ತಿಯನ್ನು ಕಸ್ಟಡಿಯಲ್ಲಿ ಹಿಡಿದಿರುವ ವ್ಯಕ್ತಿ ಅಥವಾ ಪ್ರಾಧಿಕಾರಕ್ಕೆ, ಆ ವ್ಯಕ್ತಿಯನ್ನು ನ್ಯಾಯಾಲಯದ ಮುಂದೆ ಹಾಜರುಪಡಿಸಿ ಬಂಧನವನ್ನು ಸಮರ್ಥಿಸಬೇಕೆಂದು ನಿರ್ದೇಶಿಸುತ್ತದೆ. ಅಕ್ರಮ ಅಥವಾ ಮನಬಂದಂತೆ ಬಂಧನದ ವಿರುದ್ಧ ಇದು ಪ್ರಾಥಮಿಕ ಪರಿಹಾರವಾಗಿದೆ.',
  'mandamus':
    'ಸಂವಿಧಾನದ 32ನೇ ಅಥವಾ 226ನೇ ವಿಧಿಯ ಅಡಿಯಲ್ಲಿ ನೀಡಿದ ರಿಟ್, ಸಾರ್ವಜನಿಕ ಪ್ರಾಧಿಕಾರ ಅಥವಾ ಅಧಿಕಾರಿಗೆ, ಅವರು ನಿರ್ವಹಿಸಲು ವಿಫಲರಾದ ಅಥವಾ ನಿರಾಕರಿಸಿದ ಸಾರ್ವಜನಿಕ ಕರ್ತವ್ಯವನ್ನು ನಿರ್ವಹಿಸಬೇಕೆಂದು ನಿರ್ದೇಶಿಸುತ್ತದೆ.',
  'certiorari':
    'ಸಂವಿಧಾನದ 32ನೇ ಅಥವಾ 226ನೇ ವಿಧಿಯ ಅಡಿಯಲ್ಲಿ ನೀಡಿದ ರಿಟ್, ಇದರ ಮೂಲಕ ಉನ್ನತ ನ್ಯಾಯಾಲಯ ಕೆಳ ನ್ಯಾಯಾಲಯ ಅಥವಾ ನ್ಯಾಯಮಂಡಳಿಯಿಂದ ಪ್ರಕರಣದ ದಾಖಲೆಯನ್ನು ಕೇಳುತ್ತದೆ ಮತ್ತು ಅದನ್ನು ಅಧಿಕಾರವ್ಯಾಪ್ತಿ ಇಲ್ಲದೆ ಅಥವಾ ಸ್ವಾಭಾವಿಕ ನ್ಯಾಯದ ಉಲ್ಲಂಘನೆಯಲ್ಲಿ ನೀಡಲಾಗಿದ್ದರೆ ಆ ಆದೇಶವನ್ನು ರದ್ದುಗೊಳಿಸುತ್ತದೆ.',
  'quo-warranto':
    'ಸಂವಿಧಾನದ 32ನೇ ಅಥವಾ 226ನೇ ವಿಧಿಯ ಅಡಿಯಲ್ಲಿ ನೀಡಿದ ರಿಟ್, ಒಬ್ಬ ವ್ಯಕ್ತಿ ಸಾರ್ವಜನಿಕ ಹುದ್ದೆಯನ್ನು ಹೊಂದಿರುವ ಅಧಿಕಾರವನ್ನು ಪ್ರಶ್ನಿಸುತ್ತದೆ, ಮತ್ತು ಅವರು ಕಾನೂನು ಹಕ್ಕಿಲ್ಲದೆ ಅದನ್ನು ಆಕ್ರಮಿಸಿದ್ದಾರೆ ಎಂದು ಕಂಡುಬಂದರೆ ಅದರಿಂದ ಅವರನ್ನು ತೆಗೆದುಹಾಕುತ್ತದೆ.',
  'amicus-curiae':
    'ಒಂದು ಪ್ರಕರಣಕ್ಕೆ ಪಕ್ಷವಲ್ಲದ ವ್ಯಕ್ತಿ ಅಥವಾ ಸಂಸ್ಥೆ, ಪ್ರಕರಣಕ್ಕೆ ಸಂಬಂಧಿತ ಮಾಹಿತಿ, ಪರಿಣತಿ, ಅಥವಾ ವಾದಗಳನ್ನು ನೀಡುವ ಮೂಲಕ ಸಹಾಯ ಮಾಡಲು ನ್ಯಾಯಾಲಯ ಅನುಮತಿಸುತ್ತದೆ, ಸಾಮಾನ್ಯವಾಗಿ ಸಾರ್ವಜನಿಕ ಮಹತ್ವದ ವಿಷಯದ ಮೇಲೆ.',
  'de-facto':
    'ಅದನ್ನು ಔಪಚಾರಿಕವಾಗಿ ಅಥವಾ ಕಾನೂನುಬದ್ಧವಾಗಿ ಗುರುತಿಸಲಾಗಿದೆಯೋ ಇಲ್ಲವೋ, ಪ್ರಾಕ್ಟೀಸ್ ಅಥವಾ ವಾಸ್ತವದಲ್ಲಿ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ. ಕಾನೂನಿನಿಂದ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ ಎಂದರ್ಥ "de jure" ಗೆ ಹೆಚ್ಚಾಗಿ ವಿರುದ್ಧವಾಗಿ ಹೋಲಿಸಲಾಗುತ್ತದೆ.',
  'de-jure':
    'ಅದು ಪ್ರಾಕ್ಟೀಸ್‌ನಲ್ಲಿ ವಾಸ್ತವವಾಗಿ ನಡೆಯುತ್ತಿರುವುದನ್ನು ಪ್ರತಿಬಿಂಬಿಸುತ್ತದೆಯೋ ಇಲ್ಲವೋ, ಕಾನೂನಿನಿಂದ ಅಥವಾ ಕಾನೂನು ಹಕ್ಕಿನ ವಿಷಯವಾಗಿ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ. ವಾಸ್ತವದಲ್ಲಿ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ ಎಂದರ್ಥ "de facto" ಗೆ ಹೆಚ್ಚಾಗಿ ವಿರುದ್ಧವಾಗಿ ಹೋಲಿಸಲಾಗುತ್ತದೆ.',
  'inter-alia':
    'ಇತರ ವಿಷಯಗಳ ಜೊತೆಗೆ. ಒಂದು ಪಟ್ಟಿ ಅಥವಾ ಹೇಳಿಕೆ ಸಂಪೂರ್ಣವಲ್ಲ ಎಂದು ಸೂಚಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ - ನಿರ್ದಿಷ್ಟವಾಗಿ ಹೇಳಿದವುಗಳ ಹೊರತಾಗಿ ಇತರ ವಿಷಯಗಳು ಅಸ್ತಿತ್ವದಲ್ಲಿವೆ ಎಂದು.',
  'ipso-facto':
    'ಆ ಸಂಗತಿಯಿಂದಲೇ, ಒಂದು ನಿರ್ದಿಷ್ಟ ಫಲಿತಾಂಶ ಅಥವಾ ಪರಿಣಾಮವನ್ನು ತರಲು ಇನ್ನೇನೂ ಅಗತ್ಯವಿಲ್ಲದೆ.',
  'quid-pro-quo':
    'ಸಮಾನ ಮೌಲ್ಯದ ಬೇರೆ ಏನನ್ನಾದರೂ ಬದಲಾಗಿ ನೀಡಿದ ಅಥವಾ ಮಾಡಿದ ಸಂಗತಿ. ಉದಾಹರಣೆಗೆ, ಒಪ್ಪಂದ ಕಾನೂನಿನಲ್ಲಿ ಒಪ್ಪಂದದ ಪಕ್ಷಗಳ ನಡುವೆ ಹಾದುಹೋಗುವ ಪ್ರತಿಫಲವನ್ನು ವಿವರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.',
  'status-quo':
    'ಒಂದು ನಿರ್ದಿಷ್ಟ ಸಮಯದಲ್ಲಿರುವ ಅಸ್ತಿತ್ವದ ಸ್ಥಿತಿ. ಪ್ರಕರಣ ಬಾಕಿಯಿರುವಾಗ ಯಾವುದೇ ಪಕ್ಷ ಅಸ್ತಿತ್ವದ ಪರಿಸ್ಥಿತಿಯನ್ನು ಬದಲಾಯಿಸುವುದನ್ನು ತಡೆಯಲು, ನ್ಯಾಯಾಲಯಗಳು ಹೆಚ್ಚಾಗಿ "status quo ಉಳಿಸಿಕೊಳ್ಳಲು" ಮಧ್ಯಂತರ ಆದೇಶಗಳನ್ನು ನೀಡುತ್ತವೆ.',
  'pari-passu':
    'ಸಮಾನ ಆಧಾರದ ಮೇಲೆ, ಆದ್ಯತೆ ಇಲ್ಲದೆ. ಸಾಲದಾತರು ಅಥವಾ ಹಕ್ಕುದಾರರಿಗೆ ಅನುಪಾತಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಪಾವತಿಸಿದ ಅಥವಾ ನಡೆಸಿದ ಸ್ಥಳದಲ್ಲಿ ಮುಖ್ಯವಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ, ಇತರರ ಮೇಲೆ ಯಾರಿಗೂ ಆದ್ಯತೆ ನೀಡದೆ.',
  'res-ipsa-loquitur':
    'ವಸ್ತು ಸ್ವತಃ ಮಾತನಾಡುತ್ತದೆ. ಮುಖ್ಯವಾಗಿ ನಿರ್ಲಕ್ಷ್ಯ ಪ್ರಕರಣಗಳಲ್ಲಿ ಅನ್ವಯಿಸಲಾಗುತ್ತದೆ, ಅಲ್ಲಿ ಅಪಘಾತದ ಸನ್ನಿವೇಶಗಳು ಅಸಡ್ಡೆಯನ್ನು ಎಷ್ಟು ಸ್ಪಷ್ಟವಾಗಿ ಸೂಚಿಸುತ್ತವೆ ಎಂದರೆ, ಅದು ನಿಖರವಾಗಿ ಹೇಗೆ ಸಂಭವಿಸಿತು ಎಂಬ ಹೆಚ್ಚಿನ ಪುರಾವೆ ಅಗತ್ಯವಿಲ್ಲದೆ, ಆ ಸಂಗತಿಗಳನ್ನೇ ನಿರ್ಲಕ್ಷ್ಯದ ಸಾಕ್ಷ್ಯವೆಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ.',
  'ejusdem-generis':
    'ಶಾಸನ ಅರ್ಥೈಸುವಿಕೆಯ ನಿಯಮ: ಒಂದು ಕಾನೂನು ನಿರ್ದಿಷ್ಟ ವಸ್ತುಗಳನ್ನು ಸಾಮಾನ್ಯ ಪದಗಳ ನಂತರ ಪಟ್ಟಿ ಮಾಡಿದಾಗ, ಆ ಸಾಮಾನ್ಯ ಪದಗಳನ್ನು ಪಟ್ಟಿ ಮಾಡಿದ ವಸ್ತುಗಳಂತೆ ಅದೇ ಪ್ರಕಾರದ ವಿಷಯಗಳಿಗೆ ಸೀಮಿತವಾಗಿ ಓದಲಾಗುತ್ತದೆ, ಯಾವುದನ್ನೇ ಆದರೂ ಒಳಗೊಳ್ಳುವಂತೆ ಅಲ್ಲ.',
  'noscitur-a-sociis':
    'ಶಾಸನ ಅರ್ಥೈಸುವಿಕೆಯ ನಿಯಮ: ಒಂದು ಕಾನೂನಿನಲ್ಲಿ ಅಸ್ಪಷ್ಟ ಪದ ಅಥವಾ ಪದಗುಚ್ಛದ ಅರ್ಥವನ್ನು, ಅದರ ಸುತ್ತಲಿನ ಪದಗಳನ್ನು ನೋಡುವ ಮೂಲಕ ಅರ್ಥಮಾಡಿಕೊಳ್ಳಬಹುದು, ಏಕೆಂದರೆ ಒಂದು ಪದವನ್ನು ಅದರ ಸಹವಾಸದಿಂದ ತಿಳಿಯಲಾಗುತ್ತದೆ.',
  'doli-incapax':
    'ಅಪರಾಧ ಮಾಡಲು ಅಸಮರ್ಥ. ಮುಖ್ಯವಾಗಿ ಚಿಕ್ಕ ಮಕ್ಕಳಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ, ಒಂದು ನಿರ್ದಿಷ್ಟ ವಯಸ್ಸಿನ ಕೆಳಗೆ ತಮ್ಮ ಕೃತ್ಯಗಳಿಗೆ ಕ್ರಿಮಿನಲ್ ಹೊಣೆಗಾರರಾಗಲು ಅಗತ್ಯವಾದ ತಿಳುವಳಿಕೆ ಹೊಂದಿಲ್ಲ ಎಂದು ಕಾನೂನು ಭಾವಿಸುತ್ತದೆ.',
  'uberrima-fides':
    'ಅತ್ಯುನ್ನತ ಸದ್ಭಾವನೆ. ಕೆಲವು ಒಪ್ಪಂದಗಳು, ಮುಖ್ಯವಾಗಿ ವಿಮಾ ಒಪ್ಪಂದಗಳು, ಹೆಚ್ಚಿನ ಒಪ್ಪಂದಗಳಿಗೆ ಅನ್ವಯಿಸುವ ತಪ್ಪಾಗಿ ಪ್ರಸ್ತುತಪಡಿಸಬಾರದ ಸಾಮಾನ್ಯ ಕಡ್ಡಾಯವನ್ನು ಮೀರಿ, ಪ್ರತಿ ಪಕ್ಷ ಎಲ್ಲಾ ಪ್ರಾಮುಖ್ಯ ಸಂಗತಿಗಳನ್ನು ಇತರರಿಗೆ ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿ ಬಹಿರಂಗಪಡಿಸಬೇಕೆಂದು ಬೇಡುತ್ತವೆ.',
  'de-novo':
    'ಹೊಸದಾಗಿ, ಅಥವಾ ಹೊಸದಾಗಿ ಆರಂಭಿಸುವುದು. ಒಂದು "de novo" ವಿಚಾರಣೆ ಅಥವಾ ಟ್ರಯಲ್ ಎಂದರೆ, ಕೇವಲ ದೋಷಗಳಿಗಾಗಿ ಮರುಪರಿಶೀಲಿಸುವ ಬದಲು, ಹಿಂದಿನ ಪ್ರಕ್ರಿಯೆ ನಡೆದಿರಲಿಲ್ಲ ಎಂಬಂತೆ, ವಿಷಯವನ್ನು ಮೊದಲಿನಿಂದ ಮತ್ತೆ ಆಲಿಸಲಾಗುತ್ತದೆ.',
  'functus-officio':
    'ತನ್ನ ಕರ್ತವ್ಯ ಅಥವಾ ಅಧಿಕಾರವನ್ನು ಪೂರೈಸಿ, ಆದ್ದರಿಂದ ಆ ವಿಷಯದಲ್ಲಿ ಮುಂದೆ ಕಾರ್ಯನಿರ್ವಹಿಸಲು ಇನ್ನು ಅಧಿಕಾರ ಹೊಂದಿಲ್ಲ. ಉದಾಹರಣೆಗೆ, ಈಗಾಗಲೇ ಅಂತಿಮ ಡಿಕ್ರಿ ನೀಡಿದ ನ್ಯಾಯಾಲಯ, ಹೆಚ್ಚಿನ ವಿಷಯಗಳಲ್ಲಿ, ಆ ಪ್ರಕರಣಕ್ಕೆ ಸಂಬಂಧಿಸಿ functus officio ಆಗಿದೆ.',
  'sui-generis':
    'ತನ್ನದೇ ಪ್ರಕಾರದ, ಅಥವಾ ಅನನ್ಯ - ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ವರ್ಗ ಅಥವಾ ವರ್ಗೀಕರಣಕ್ಕೆ ಸಮರ್ಪಕವಾಗಿ ಹೊಂದಿಕೊಳ್ಳದ, ಮತ್ತು ಆದ್ದರಿಂದ ತನ್ನದೇ ಪ್ರತ್ಯೇಕ ಕಾನೂನು ಚಿಕಿತ್ಸೆಯ ಅಗತ್ಯವಿರುವ.',
  'lis-pendens':
    'ಬಾಕಿ ಇರುವ ದಾವೆ ಅಥವಾ ಮೊಕದ್ದಮೆ. lis pendens ಸಿದ್ಧಾಂತದ ಅಡಿಯಲ್ಲಿ, ನಡೆಯುತ್ತಿರುವ ಪ್ರಕರಣದ ವಿಷಯವಸ್ತುವಾಗಿರುವ ಆಸ್ತಿಯನ್ನು, ಆ ಪ್ರಕರಣದ ಇತರ ಪಕ್ಷದ ಹಕ್ಕುಗಳನ್ನು ಬಾಧಿಸುವ ವಿಧಾನದಲ್ಲಿ ವರ್ಗಾಯಿಸಲಾಗುವುದಿಲ್ಲ.',
  'pendente-lite':
    'ಮೊಕದ್ದಮೆ ಬಾಕಿಯಿರುವಾಗ. ಮಧ್ಯಂತರ ಭರಣ ಅಥವಾ ಪಾಲನೆಯಂತಹ, ಪ್ರಕರಣ ಅಂತಿಮವಾಗಿ ನಿರ್ಧರಿಸುವವರೆಗೆ ಅದರ ಅವಧಿಗೆ ಮಾತ್ರ ಅನ್ವಯಿಸುವ ಆದೇಶ, ಹಕ್ಕು, ಅಥವಾ ವ್ಯವಸ್ಥೆಯನ್ನು ವಿವರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.',
  'ex-post-facto':
    'ಸಂಗತಿಯ ನಂತರ. ಒಂದು ಕೃತ್ಯವನ್ನು ಅಪರಾಧೀಕರಿಸಲು, ಅಥವಾ ಕಾನೂನು ಸ್ವತಃ ಮಾಡಲಾದ ದಿನಾಂಕಕ್ಕೆ ಮೊದಲಿನಿಂದ ಪರಿಣಾಮ ಬೀರುವಂತೆ ಅದರ ಶಿಕ್ಷೆಯನ್ನು ಹೆಚ್ಚಿಸಲು ಪ್ರಯತ್ನಿಸುವ ಕಾನೂನಿಗೆ ಹೆಚ್ಚಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ - ಸಂವಿಧಾನ ಸಾಮಾನ್ಯವಾಗಿ ಕ್ರಿಮಿನಲ್ ವಿಷಯಗಳಲ್ಲಿ ನಿಷೇಧಿಸುವ ಸಂಗತಿ.',
  'nunc-pro-tunc':
    'ಆಗಿನ ಪರಿಹಾರ ಈಗ. ನ್ಯಾಯಾಲಯ ಈಗ ಮಾಡುವ ಆದರೆ ಹಿಂದಿನ ದಿನಾಂಕದಿಂದ ಕಾನೂನು ಪರಿಣಾಮ ಪಡೆಯುವ ಆದೇಶ, ಸಾಮಾನ್ಯವಾಗಿ ವಿಳಂಬ ಅಥವಾ ಲೋಪ ಇಲ್ಲದಿದ್ದರೆ ಒಂದು ಪಕ್ಷದ ಹಕ್ಕುಗಳನ್ನು ಅನ್ಯಾಯವಾಗಿ ಬಾಧಿಸುತ್ತಿದ್ದ ದಾಖಲೆಯನ್ನು ಸರಿಪಡಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.',
  'quantum-meruit':
    'ಒಬ್ಬ ವ್ಯಕ್ತಿ ಗಳಿಸಿದಷ್ಟು. ಪರಿಹಾರಕ್ಕಾಗಿ ಹಕ್ಕಿಗೆ ಬದಲಾಗಿ, ಯಾವುದೇ ನಿಗದಿತ ಬೆಲೆಯನ್ನು ಒಪ್ಪದಿದ್ದಾಗ, ಅಥವಾ ಒಪ್ಪಂದವನ್ನು ಪೂರ್ಣಗೊಳಿಸಲಾಗದಿದ್ದಾಗ, ಮಾಡಿದ ಕೆಲಸ ಅಥವಾ ನೀಡಿದ ಸೇವೆಗಳಿಗೆ ಸಮಂಜಸ ಪಾವತಿಗಾಗಿ ಮಾಡಿದ ಹಕ್ಕು.',
  'bona-vacantia':
    'ಮಾಲೀಕರಹಿತ ಆಸ್ತಿ. ಗುರುತಿಸಬಹುದಾದ ಮಾಲೀಕರಿಲ್ಲದ ಆಸ್ತಿ, ಉದಾಹರಣೆಗೆ ವಿಸರ್ಜಿತ ಕಂಪನಿಯ ಆಸ್ತಿಗಳು ಅಥವಾ ವಾರಸುದಾರರು ಅಥವಾ ಇಚ್ಛಾಪತ್ರವಿಲ್ಲದೆ ಮೃತರಾದ ವ್ಯಕ್ತಿಯ ಆಸ್ತಿಗಳು, ಕಾನೂನಿನ ಮೂಲಕ ಸರ್ಕಾರಕ್ಕೆ ಹೋಗುತ್ತವೆ.',
  'modus-operandi':
    'ಕಾರ್ಯನಿರ್ವಹಿಸುವ ನಿರ್ದಿಷ್ಟ ವಿಧಾನ ಅಥವಾ ಮಾದರಿ. ಕ್ರಿಮಿನಲ್ ವಿಷಯಗಳಲ್ಲಿ, ಇದು ಒಂದು ಅಪರಾಧವನ್ನು ಎಸಗುವ ವಿಶಿಷ್ಟ ವಿಧಾನವನ್ನು ಸೂಚಿಸುತ್ತದೆ, ಇದು ಕೆಲವೊಮ್ಮೆ ಆರೋಪಿಯನ್ನು ಹಿಂದಿನ ಸಮಾನ ಅಪರಾಧಗಳಿಗೆ ಜೋಡಿಸಲು ಸಹಾಯ ಮಾಡಬಹುದು.',
  'coram-non-judice':
    'ನ್ಯಾಯಾಧೀಶರಲ್ಲದ ವ್ಯಕ್ತಿಯ ಮುಂದೆ, ಅಥವಾ ವಿಷಯವನ್ನು ಆಲಿಸುವ ಅಧಿಕಾರವಿಲ್ಲದ ನ್ಯಾಯಾಲಯದ ಮುಂದೆ. coram non judice ಆಗಿ ನೀಡಲಾದ ಆದೇಶವನ್ನು ಅನೂರ್ಜಿತವೆಂದು ಪರಿಗಣಿಸಲಾಗುತ್ತದೆ, ಏಕೆಂದರೆ ಅದನ್ನು ಆರಂಭದಿಂದಲೇ ಸರಿಯಾದ ಅಧಿಕಾರವ್ಯಾಪ್ತಿ ಇಲ್ಲದೆ ಮಾಡಲಾಗಿತ್ತು.',
  'mutatis-mutandis':
    'ಅಗತ್ಯ ಬದಲಾವಣೆಗಳನ್ನು ಮಾಡಿದ ನಂತರ. ಒಂದು ಪರಿಸ್ಥಿತಿಗೆ ಬರೆದ ನಿಯಮ, ಕ್ಲಾಸ್, ಅಥವಾ ನಿಬಂಧನೆಯನ್ನು ಇನ್ನೊಂದು ಸಮಾನ ಪರಿಸ್ಥಿತಿಗೆ ಅನ್ವಯಿಸುವಾಗ, ಅಗತ್ಯವಾಗಿ ಭಿನ್ನವಾಗಿರಬೇಕಾದ ವಿವರಗಳನ್ನು ಮಾತ್ರ ಹೊಂದಿಸುತ್ತಾ ಬಳಸಲಾಗುತ್ತದೆ.',
  'sine-die':
    'ಮುಂದುವರಿಸಲು ಯಾವುದೇ ನಿಗದಿತ ದಿನಾಂಕವಿಲ್ಲದೆ. "sine die" ಮುಂದೂಡಲಾದ ವಿಚಾರಣೆ ಅಥವಾ ವಿಷಯವನ್ನು, ಅದನ್ನು ಮುಂದೆ ಯಾವಾಗ ತೆಗೆದುಕೊಳ್ಳಲಾಗುವುದು ಎಂಬ ಯಾವುದೇ ನಿರ್ದಿಷ್ಟ ದಿನಾಂಕ ನಿಗದಿಪಡಿಸದೆ, ಅನಿರ್ದಿಷ್ಟವಾಗಿ ಮುಂದೂಡಲಾಗುತ್ತದೆ.',
  'sine-qua-non':
    'ಒಂದು ಅಗತ್ಯ ಪರಿಸ್ಥಿತಿ, ಅದು ಇಲ್ಲದೆ ಏನೂ ಸಂಭವಿಸಲು ಅಥವಾ ಅಸ್ತಿತ್ವದಲ್ಲಿರಲು ಸಾಧ್ಯವಿಲ್ಲ. ಒಂದು ನಿರ್ದಿಷ್ಟ ಫಲಿತಾಂಶಕ್ಕೆ ಸಂಪೂರ್ಣವಾಗಿ ಅನಿವಾರ್ಯವಾದ ಅವಶ್ಯಕತೆಯನ್ನು ವಿವರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.',
  'nemo-judex-in-causa-sua':
    'ಯಾರೂ ತಮ್ಮ ಸ್ವಂತ ವಿಷಯದಲ್ಲಿ ನ್ಯಾಯಾಧೀಶರಾಗಬಾರದು. ಒಂದು ವಿಷಯವನ್ನು ನಿರ್ಧರಿಸುವ ವ್ಯಕ್ತಿ ಅಥವಾ ಪ್ರಾಧಿಕಾರಕ್ಕೆ ಅದರ ಫಲಿತಾಂಶದಲ್ಲಿ ವ್ಯಕ್ತಿಗತ ಹಿತಾಸಕ್ತಿ ಇರಬಾರದು ಎಂದು ಬೇಡುವ ಸ್ವಾಭಾವಿಕ ನ್ಯಾಯದ ಮೂಲ ತತ್ವ.',
  'volenti-non-fit-injuria':
    'ಒಪ್ಪಿಗೆಯ ವ್ಯಕ್ತಿಗೆ ಯಾವುದೇ ಹಾನಿ ಮಾಡಲಾಗುವುದಿಲ್ಲ. ಮುಖ್ಯವಾಗಿ ಟಾರ್ಟ್ ಕಾನೂನಿನಲ್ಲಿ, ಹಾನಿಯ ಅಪಾಯವನ್ನು ತಿಳಿದುಕೊಂಡು ಸ್ವಯಂಪ್ರೇರಿತವಾಗಿ ಒಪ್ಪಿಕೊಂಡ ವ್ಯಕ್ತಿ, ಆ ಹಾನಿಗೆ ನಂತರ ಪರಿಹಾರ ಕೋರಲು ಸಾಧ್ಯವಿಲ್ಲ ಎಂಬ ಪ್ರತಿವಾದ.',
};
